insert into cfg.data_domain (code, level, grp, name, parent_name, description) values
  ('MOET01', 1, null, 'Giáo dục và đào tạo', null, 'Toàn bộ dữ liệu phục vụ quản lý, vận hành và ra quyết định trong ngành giáo dục'),
  ('MOET02', 2, null, 'Nghiệp vụ dùng chung', 'Giáo dục và đào tạo', 'Dữ liệu về các nghiệp vụ dùng chung trong toàn ngành GDĐT'),
  ('MOET03', 3, null, 'Tài chính và đầu tư giáo dục', 'Nghiệp vụ dùng chung', 'Chi ngân sách GD, học phí, nguồn thu ngoài NSNN; đầu tư công cho GDĐT'),
  ('MOET04', 3, null, 'Hồ sơ, văn bản và tài liệu lưu trữ', 'Nghiệp vụ dùng chung', 'Quản lý hồ sơ, văn bản và lưu trữ'),
  ('MOET05', 3, null, 'Thủ tục hành chính', 'Nghiệp vụ dùng chung', 'Quy trình, thủ tục hành chính'),
  ('MOET06', 2, 'Con người', 'Người học', 'Giáo dục và đào tạo', 'Người học và hoạt động học tập trong hệ thống giáo dục quốc dân'),
  ('MOET07', 3, 'Con người', 'Định danh và thông tin cơ bản về người học', 'Người học', 'Định danh duy nhất người học: họ tên, ngày sinh, giới tính, dân tộc, quốc tịch, nơi sinh, cha mẹ/người giám hộ, sức khỏe, khuyết tật…'),
  ('MOET08', 3, 'Con người', 'Tuyển sinh và nhập học', 'Người học', 'Đăng ký, hồ sơ nhập học, kết quả tuyển sinh'),
  ('MOET09', 3, 'Con người', 'Thông tin chính sách và hỗ trợ người học', 'Người học', 'Chế độ chính sách, hỗ trợ tài chính, học bổng, ưu đãi'),
  ('MOET10', 3, 'Con người', 'Tình trạng học tập', 'Người học', 'Đang học, bảo lưu, thôi học, chuyển trường; lý do, ngày chuyển trạng thái'),
  ('MOET11', 3, 'Con người', 'Quá trình học tập, rèn luyện của người học', 'Người học', 'Điểm thường xuyên/định kỳ, chuyên cần, ngoại khóa, hoạt động trải nghiệm, tự học, nghiên cứu khoa học'),
  ('MOET12', 3, 'Con người', 'Hoạt động và kết quả nghiên cứu khoa học của người học', 'Người học', 'Hoạt động và kết quả nghiên cứu khoa học của người học'),
  ('MOET13', 3, 'Con người', 'Kết quả, quyết định công nhận tốt nghiệp của người học', 'Người học', 'Kết quả, quyết định công nhận tốt nghiệp'),
  ('MOET14', 3, 'Con người', 'Thông tin khen thưởng, kỷ luật của người học', 'Người học', 'Khen thưởng, kỷ luật người học'),
  ('MOET15', 3, 'Con người', 'Thông tin về việc làm của người học', 'Người học', 'Việc làm và kết quả đầu ra sau tốt nghiệp'),
  ('MOET16', 3, 'Con người', 'Hồ sơ học tập suốt đời', 'Người học', 'Học bạ, văn bằng, chứng chỉ, bảng điểm, giải thưởng, thành tích học tập'),
  ('MOET17', 2, 'Con người', 'Nhà giáo và cán bộ quản lý giáo dục', 'Giáo dục và đào tạo', 'Đội ngũ nhà giáo và cán bộ quản lý giáo dục'),
  ('MOET18', 3, 'Con người', 'Định danh và thông tin cơ bản về nhà giáo và cán bộ quản lý giáo dục', 'Nhà giáo và cán bộ quản lý giáo dục', 'Mã định danh cán bộ/nhà giáo, số định danh cá nhân, họ tên, ngày sinh, giới tính, quê quán, nơi ở, sức khỏe, gia đình…'),
  ('MOET19', 3, 'Con người', 'Trình độ chuyên môn của nhà giáo và cán bộ quản lý giáo dục', 'Nhà giáo và cán bộ quản lý giáo dục', 'Trình độ, năng lực của nhà giáo và CBQLGD'),
  ('MOET20', 3, 'Con người', 'Thông tin tuyển dụng, vị trí việc làm của nhà giáo và cán bộ quản lý giáo dục', 'Nhà giáo và cán bộ quản lý giáo dục', 'Tuyển dụng, vị trí việc làm, quá trình công tác'),
  ('MOET21', 3, 'Con người', 'Quá trình công tác của nhà giáo và cán bộ quản lý giáo dục', 'Nhà giáo và cán bộ quản lý giáo dục', 'Thuyên chuyển, biệt phái, điều động, nghỉ, nghỉ hưu'),
  ('MOET22', 3, 'Con người', 'Quá trình đào tạo và bồi dưỡng của cán bộ/nhà giáo', 'Nhà giáo và cán bộ quản lý giáo dục', 'Quá trình đào tạo và bồi dưỡng'),
  ('MOET23', 3, 'Con người', 'Hoạt động và kết quả nghiên cứu khoa học của cán bộ/nhà giáo', 'Nhà giáo và cán bộ quản lý giáo dục', 'Hoạt động và kết quả nghiên cứu khoa học của cán bộ/nhà giáo'),
  ('MOET24', 3, 'Con người', 'Thông tin đánh giá chuẩn nghề nghiệp nhà giáo và cán bộ quản lý giáo dục', 'Nhà giáo và cán bộ quản lý giáo dục', 'Vị trí, công việc, đánh giá chuẩn nghề nghiệp'),
  ('MOET25', 3, 'Con người', 'Thông tin lương và phụ cấp nhà giáo và cán bộ quản lý giáo dục', 'Nhà giáo và cán bộ quản lý giáo dục', 'Bậc lương, ngạch, hạng, quá trình lương và phụ cấp'),
  ('MOET26', 3, 'Con người', 'Thông tin hỗ trợ, thu hút, trọng dụng đối với nhà giáo', 'Nhà giáo và cán bộ quản lý giáo dục', 'Hỗ trợ theo vùng miền, bồi dưỡng, chăm sóc sức khỏe, phụ cấp theo đối tượng'),
  ('MOET27', 3, 'Con người', 'Tôn vinh, khen thưởng, kỷ luật và xử lý vi phạm nhà giáo', 'Nhà giáo và cán bộ quản lý giáo dục', 'Khen thưởng, kỷ luật, xử lý vi phạm'),
  ('MOET28', 2, 'Tổ chức', 'Cơ sở giáo dục, cơ quan quản lý giáo dục và các tổ chức hoạt động trong lĩnh vực giáo dục', 'Giáo dục và đào tạo', 'Cơ sở giáo dục, cơ quan quản lý và tổ chức hoạt động trong lĩnh vực giáo dục'),
  ('MOET29', 3, 'Tổ chức', 'Định danh và thông tin cơ bản về cơ quan quản lý giáo dục, tổ chức hoạt động trong lĩnh vực giáo dục', 'Cơ sở giáo dục, cơ quan quản lý giáo dục và các tổ chức hoạt động trong lĩnh vực giáo dục', 'Định danh cơ quan quản lý giáo dục, tổ chức hoạt động trong lĩnh vực giáo dục'),
  ('MOET30', 3, 'Tổ chức', 'Định danh và thông tin cơ bản về cơ sở giáo dục', 'Cơ sở giáo dục, cơ quan quản lý giáo dục và các tổ chức hoạt động trong lĩnh vực giáo dục', 'Định danh cơ sở giáo dục gắn với miền dữ liệu tổ chức quốc gia'),
  ('MOET31', 3, 'Tổ chức', 'Tổ chức giảng dạy', 'Cơ sở giáo dục, cơ quan quản lý giáo dục và các tổ chức hoạt động trong lĩnh vực giáo dục', 'Lớp học, sĩ số, phân công GV bộ môn/chủ nhiệm, thời khóa biểu, kế hoạch dạy học, phòng học'),
  ('MOET32', 3, 'Tổ chức', 'Cơ sở vật chất, thiết bị phục vụ dạy học, đào tạo của cơ sở giáo dục', 'Cơ sở giáo dục, cơ quan quản lý giáo dục và các tổ chức hoạt động trong lĩnh vực giáo dục', 'Cơ sở vật chất, thiết bị và tài sản'),
  ('MOET33', 3, 'Tổ chức', 'Chất lượng cơ sở giáo dục', 'Cơ sở giáo dục, cơ quan quản lý giáo dục và các tổ chức hoạt động trong lĩnh vực giáo dục', 'Kiểm định, đánh giá chất lượng tối thiểu, đánh giá hạng cơ sở giáo dục'),
  ('MOET34', 3, 'Tổ chức', 'Chuyển đổi số và thống kê GDĐT', 'Cơ sở giáo dục, cơ quan quản lý giáo dục và các tổ chức hoạt động trong lĩnh vực giáo dục', 'Ứng dụng CNTT, chuyển đổi số và thống kê trong giáo dục'),
  ('MOET35', 3, 'Tổ chức', 'Hoạt động, sản phẩm nghiên cứu khoa học của cơ sở giáo dục đại học', 'Cơ sở giáo dục, cơ quan quản lý giáo dục và các tổ chức hoạt động trong lĩnh vực giáo dục', 'Hoạt động, sản phẩm nghiên cứu khoa học của cơ sở giáo dục đại học'),
  ('MOET36', 3, 'Tổ chức', 'Hợp tác quốc tế, hợp tác doanh nghiệp', 'Cơ sở giáo dục, cơ quan quản lý giáo dục và các tổ chức hoạt động trong lĩnh vực giáo dục', 'Hợp tác quốc tế, hợp tác giữa các doanh nghiệp'),
  ('MOET37', 3, 'Tổ chức', 'Thanh tra và kiểm tra chuyên ngành giáo dục', 'Cơ sở giáo dục, cơ quan quản lý giáo dục và các tổ chức hoạt động trong lĩnh vực giáo dục', 'Hoạt động thanh tra, kiểm tra trong giáo dục'),
  ('MOET38', 2, null, 'Chương trình và nội dung đào tạo', 'Giáo dục và đào tạo', 'Thiết kế, ban hành, triển khai và đánh giá chương trình giáo dục, đào tạo'),
  ('MOET39', 3, null, 'Chương trình giáo dục và đào tạo', 'Chương trình và nội dung đào tạo', 'Khung chương trình, thời lượng, mục tiêu, danh sách môn học, số tín chỉ/tiết, cách đánh giá, chuẩn đầu ra'),
  ('MOET40', 3, null, 'Sách giáo khoa, giáo trình, tài liệu giáo dục', 'Chương trình và nội dung đào tạo', 'Sách giáo khoa, giáo trình, tài liệu'),
  ('MOET41', 3, null, 'Kiểm định chất lượng chương trình đào tạo', 'Chương trình và nội dung đào tạo', 'Hoạt động và kết quả kiểm định chương trình đào tạo');
insert into cfg.data_term (code, name, definition, context, domains, technical_name, data_type, data_type_vi, length, core_code) values
  ('BG_00001', 'Tên loại thu chi', 'Là tên gọi của nhóm phân loại các khoản thu hoặc chi trong hoạt động tài chính của cơ sở đào tạo', 'Thuộc tính ghi nhận tên loại thu chi của tài chính và đầu tư giáo dục.', array['MOET03']::text[], 'tenLoaiThuChi', 'String', 'Chuỗi ký tự', '50', null),
  ('BG_00002', 'Mã loại thu chi', 'Là mã định danh của loại thu hoặc chi', 'Thuộc tính mô tả mã loại thu chi.', array['MOET03']::text[], 'maLoaiThuChi', 'String', 'Chuỗi ký tự', '50', null),
  ('BG_00003', 'Tên khoản thu chi', 'Là tên cụ thể của từng khoản thu hoặc chi', 'Thuộc tính ghi nhận tên khoản thu chi của tài chính và đầu tư giáo dục.', array['MOET03']::text[], 'tenKhoanThuChi', 'String', 'Chuỗi ký tự', '100', null),
  ('BG_00004', 'Số tiền khoản thu chi', 'Là số tiền của khoản thu hoặc chi, được ghi nhận theo đơn vị tiền tệ quy định', 'Thuộc tính định lượng phản ánh số tiền khoản thu chi.', array['MOET03']::text[], 'soTienKhoanThuChi', 'Decimal', 'Số thập phân', null, null),
  ('BG_00005', 'Năm báo cáo khoản thu chi', 'Là năm tài chính mà khoản thu hoặc chi được ghi nhận', 'Thuộc tính định lượng phản ánh năm báo cáo khoản thu chi.', array['MOET03']::text[], 'namBaoCaoKhoanThuChi', 'Integer', 'Số nguyên', null, null),
  ('BG_00006', 'Mã số hồ sơ học tập suốt đời của cá nhân', 'Người học tham gia trong hệ thống giáo dục quốc dân được cấp một mã số hồ sơ học tập suốt đời duy nhất theo số định danh cá nhân. Trước khi cấp mã số hồ sơ học tập suốt đời, các thông tin cơ bản của cá nhân phải được kiểm tra, đối chiếu với Cơ sở dữ liệu quốc gia về dân cư.', 'Mã số hồ sơ học tập suốt đời của cá nhân được dùng làm mã khóa truy cập để khai thác dữ liệu hồ sơ học tập suốt đời của người học lưu giữ trong Cơ sở dữ liệu quốc gia về giáo dục và đào tạo. Thông tin về mã số hồ sơ học tập suốt đời và các dữ liệu liên quan được quản lý theo các quy định của pháp luật về bảo vệ dữ liệu cá nhân.', array['MOET07']::text[], 'maHoSoHocTapSuotDoi', 'String', 'Chuỗi ký tự', '50', null),
  ('BG_00007', 'Họ và tên người học', 'Là họ và tên người học', 'Thuộc tính mô tả họ và tên của người học.', array['MOET07']::text[], 'hoTenNh', 'String', 'Chuỗi ký tự', '200', null),
  ('BG_00008', 'Tên viết tắt người học', 'Là tên viết tắt nếu có của người học.', 'Thuộc tính ghi nhận tên viết tắt của người học.', array['MOET07']::text[], 'tenTat', 'String', 'Chuỗi ký tự', '200', null),
  ('BG_00009', 'Ngày sinh của người học', 'Là ngày tháng năm sinh của người học được quản lý trong hệ thống quản lý giáo dục quốc dân.', 'Thuộc tính ghi nhận mốc thời gian ngày sinh của người học.', array['MOET07']::text[], 'ngaySinhNh', 'Date', 'Ngày tháng', '10', 'CDE-TG-001'),
  ('BG_00010', 'Giới tính', 'Mã số xác định giới tính sinh học của cá nhân theo hệ thống mã hóa quốc tế. Sử dụng hệ thống mã 1 chữ số theo chuẩn ISO/IEC 5218 để đảm bảo khả năng trao đổi dữ liệu quốc tế và tránh nhầm lẫn do khác biệt ngôn ngữ (Nam/Nữ vs M/F).', 'Thuộc tính phân loại giới tính của cá nhân', array['MOET07', 'MOET18']::text[], 'gioiTinh', 'String', 'Chuỗi ký tự', '1', 'CDE-CN-002'),
  ('BG_00011', 'Số định danh cá nhân', 'Dãy 12 chữ số được Bộ Công an cấp cho mỗi công dân Việt Nam, là định danh duy nhất và bất biến cho người đó trong suốt cuộc đời. Từ năm 2021, số định danh cá nhân thay thế hoàn toàn số CMND (9 số) và là số CCCD mới (12 số) theo Luật Căn cước 2023. Dùng làm khóa liên kết chính giữa các cơ sở dữ liệu quốc gia.', 'Trường dữ liệu định danh dùng để nhận diện duy nhất mỗi công dân do Bộ Công an cấp; phục vụ tra cứu, tham chiếu và liên thông dữ liệu giữa các CSDL quốc gia.', array['MOET07', 'MOET18']::text[], 'soDinhDanhCaNhan', 'String', 'Chuỗi ký tự', '12', 'CDE-CN-001'),
  ('BG_00012', 'Nơi cấp căn cước của người học', 'Là nơi cấp căn cước của người học được quản lý trong hệ thống quản lý giáo dục quốc dân.', 'Thuộc tính mô tả nơi cấp căn cước của người học.', array['MOET07']::text[], 'noiCapCanCuocNh', 'Enumeration', 'Danh mục liệt kê', null, null),
  ('BG_00013', 'Ngày cấp căn cước của người học', 'Là ngày cấp số định danh cá nhân của người học được quản lý trong hệ thống quản lý giáo dục quốc dân.', 'Thuộc tính ghi nhận mốc thời gian ngày cấp căn cước của người học.', array['MOET07']::text[], 'ngayCapCanCuocNh', 'Date', 'Ngày tháng', '10', 'CDE-TG-001'),
  ('BG_00014', 'Tỉnh/Thành phố nơi thường trú của người học', 'Là địa chỉ hành chính xác định tỉnh/ thành phố nơi thường trú của người học hoặc cán bộ/nhà giáo được quản lý trong hệ thống quản lý giáo dục quốc dân', 'Thuộc tính phân loại Tỉnh/Thành phố nơi thường trú của người học theo Quyết định số: 19/2025/QĐTTg: Ban hành bảng danh mục và mã số các đơn vị hành chính Việt Nam; phục vụ thống kê và báo cáo trong quản lý giáo dục.', array['MOET07']::text[], 'tinhTpNoiThuongTruNh', 'Enumeration', 'Danh mục liệt kê', null, 'CDE-DC-001'),
  ('BG_00015', 'Xã/Phường/Đặc khu nơi thường trú của người học', 'Là thông tin chỉ địa giới hành chính (xã/phường) nơi thường trú của người học', 'Thuộc tính phân loại Xã/Phường/Đặc khu nơi thường trú của người học theo Quyết định số: 19/2025/QĐ-TTg: Ban hành bảng danh mục và mã số các đơn vị hành chính Việt Nam; phục vụ thống kê và báo cáo trong quản lý giáo dục.', array['MOET07']::text[], 'xaPhuongNoiThuongTruNh', 'Enumeration', 'Danh mục liệt kê', null, 'CDE-DC-003'),
  ('BG_00016', 'Địa chỉ chi tiết nơi thường trú của người học', 'Là địa chỉ hành chính chi tiết như số nhà, đường, tổ/thôn xóm... nơi thường trú của người học được quản lý trong hệ thống quản lý giáo dục quốc dân.', 'Thuộc tính mô tả thông tin địa chỉ nơi thường trú của người học', array['MOET07']::text[], 'diaChiChiTietNoiThuongTruNh', 'String', 'Chuỗi ký tự', '500', null),
  ('BG_00017', 'Tỉnh/Thành phố nơi sinh của người học', 'Là địa chỉ hành chính xác định tỉnh/ thành phố nơi sinh của người học được quản lý trong hệ thống quản lý giáo dục quốc dân.', 'Thuộc tính phân loại Tỉnh/Thành phố nơi sinh của người học theo Quyết định số: 19/2025/QĐ-TTg: Ban hành bảng danh mục và mã số các đơn vị hành chính Việt Nam; phục vụ thống kê và báo cáo trong quản lý giáo dục.', array['MOET07']::text[], 'tinhTpNoiSinhNh', 'Enumeration', 'Danh mục liệt kê', null, 'CDE-DC-001'),
  ('BG_00018', 'Xã/Phường/Đặc khu nơi sinh của người học', 'Là địa chỉ hành chính xác định Xã/Phường/Đặc khu nơi sinh của người học được quản lý trong hệ thống quản lý giáo dục quốc dân.', 'Thuộc tính phân loại Xã/Phường/Đặc khu nơi sinh của người học theo Quyết định số: 19/2025/QĐTTg: Ban hành bảng danh mục và mã số các đơn vị hành chính Việt Nam; phục vụ thống kê và báo cáo trong quản lý giáo dục.', array['MOET07']::text[], 'xaPhuongNoiSinhNh', 'Enumeration', 'Danh mục liệt kê', null, 'CDE-DC-003'),
  ('BG_00019', 'Địa chỉ chi tiết nơi sinh của người học', 'Là địa chỉ hành chính chi tiết như số nhà, đường, tổ/thôn xóm, bệnh viện, trạm xá... nơi sinh của người học được quản lý trong hệ thống quản lý giáo dục quốc dân.', 'Thuộc tính mô tả thông tin địa chỉ nơi sinh của người học.', array['MOET07']::text[], 'diaChiChiTietNoiSinhNh', 'String', 'Chuỗi ký tự', '500', null),
  ('BG_00020', 'Tỉnh/Thành phố quê quán của người học', 'Là thông tin địa chỉ hành chính xác định tỉnh/ thành phố quê quán của người học được quản lý trong hệ thống quản lý giáo dục quốc dân.', 'Thuộc tính phân loại Tỉnh/Thành phố quê quán của người học theo Quyết định số: 19/2025/QĐ-TTg: Ban hành bảng danh mục và mã số các đơn vị hành chính Việt Nam; phục vụ thống kê và báo cáo trong quản lý giáo dục.', array['MOET07']::text[], 'tinhTpQueQuanNh', 'Enumeration', 'Danh mục liệt kê', null, 'CDE-DC-001'),
  ('BG_00021', 'Xã/Phường/Đặc khu quê quán của người học', 'Là thông tin địa chỉ hành chính xác định xã/phường/đặc khu quê quán của người học được quản lý trong hệ thống quản lý giáo dục quốc dân.', 'Thuộc tính phân loại Xã/Phường/Đặc khu quê quán của người học theo Quyết định số: 19/2025/QĐTTg: Ban hành bảng danh mục và mã số các đơn vị hành chính Việt Nam; phục vụ thống kê và báo cáo trong quản lý giáo dục.', array['MOET07']::text[], 'xaPhuongQueQuanNh', 'Enumeration', 'Danh mục liệt kê', null, 'CDE-DC-003'),
  ('BG_00022', 'Địa chỉ chi tiết quê quán của người học', 'Là thông tin địa chỉ hành chính chi tiết như số nhà, đường, tổ/thôn xóm... quê quán của người học được quản lý trong hệ thống quản lý giáo dục quốc dân.', 'Thuộc tính mô tả thông tin địa chỉ chi tiết quê quán của người học.', array['MOET07']::text[], 'diaChiChiTietQueQuanNh', 'String', 'Chuỗi ký tự', '500', null),
  ('BG_00023', 'Tỉnh/Thành phố chỗ ở hiện nay của người học', 'Là thông tin địa chỉ hành chính xác định tỉnh/ thành phố chỗ ở hiện nay của người học được quản lý trong hệ thống quản lý giáo dục quốc dân.', 'Thuộc tính phân loại Tỉnh/Thành phố chỗ ở hiện nay của người học theo Quyết định số: 19/2025/QĐTTg: Ban hành bảng danh mục và mã số các đơn vị hành chính Việt Nam; phục vụ thống kê và báo cáo trong quản lý giáo dục.', array['MOET07']::text[], 'tinhTpChoOHienNayNh', 'Enumeration', 'Danh mục liệt kê', null, 'CDE-DC-001'),
  ('BG_00024', 'Xã/Phường/Đặc khu chỗ ở hiện nay của người học', 'Là thông tin địa chỉ hành chính xác định xã/phường/đặc khu chỗ ở hiện nay của người học được quản lý trong hệ thống quản lý giáo dục quốc dân.', 'Thuộc tính phân loại Xã/Phường/Đặc khu chỗ ở hiện nay của người học theo Quyết định số: 19/2025/QĐ-TTg: Ban hành bảng danh mục và mã số các đơn vị hành chính Việt Nam; phục vụ thống kê và báo cáo trong quản lý giáo dục.', array['MOET07']::text[], 'xaPhuongChoOHienNayNh', 'Enumeration', 'Danh mục liệt kê', null, 'CDE-DC-003'),
  ('BG_00025', 'Địa chỉ chi tiết chỗ ở hiện nay của người học', 'Là thông tin địa chỉ hành chính chi tiết như số nhà, đường, tổ/thôn xóm... chỗ ở hiện nay của người học được quản lý trong hệ thống quản lý giáo dục quốc dân.', 'Thuộc tính mô tả thông tin địa chỉ chi tiết chỗ ở hiện nay của người học.', array['MOET07']::text[], 'diaChiChiTietChoOHienNayNh', 'String', 'Chuỗi ký tự', '500', null),
  ('BG_00026', 'Quốc tịch', 'Là thông tin quốc tịch của người học được quản lý trong hệ thống quản lý giáo dục quốc dân.', 'Thuộc tính phân loại quốc tịch của cá nhân.', array['MOET07', 'MOET18']::text[], 'quocTich', 'String', 'Chuỗi ký tự', '2', 'CDE-CN-003'),
  ('BG_00027', 'Dân tộc', 'Mã số xác định thành phần dân tộc của cá nhân trong danh sách 54 dân tộc được Nhà nước Việt Nam công nhận. Thông tin này được sử dụng trong quản lý nhân khẩu, chính sách dân tộc, thống kê xã hội và hỗ trợ chính sách vùng.', 'Thuộc tính dân tộc của công dân Việt Nam, phục vụ thống kê và báo cáo trong quản lý giáo dục.', array['MOET07', 'MOET18']::text[], 'danToc', 'String', 'Chuỗi ký tự', '2', 'CDE-CN-004'),
  ('BG_00028', 'Tôn giáo', 'Mã số xác định tôn giáo hoặc tín ngưỡng mà cá nhân theo hoặc thực hành. Chỉ áp dụng cho các tôn giáo đã được Nhà nước Việt Nam công nhận theo Luật Tín ngưỡng, Tôn giáo 2016.', 'Thuộc tính phân loại tôn giáo của cá nhân', array['MOET07', 'MOET18']::text[], 'tonGiao', 'String', 'Chuỗi ký tự', '5', 'CDE-CN-005'),
  ('BG_00029', 'Loại khuyết tật', 'Là thông tin xác định có người học khuyết tật tham gia học tập tại các cơ sở giáo dục và loại khuyết tật của người học đó.', 'Thuộc tính phân loại loại khuyết tật của người học.', array['MOET07']::text[], 'loaiKhuyetTat', 'Enumeration', 'Danh mục liệt kê', null, null),
  ('BG_00030', 'Khuyết tật không đánh giá', 'Là học sinh khuyết tật không đánh giá (hoặc đánh giá theo cách riêng) là hình thức giáo dục hòa nhập, nơi kết quả rèn luyện và học tập của học sinh khuyết tật được nhận xét dựa trên sự tiến bộ cá nhân, không so sánh với học sinh khác, và không gò ép, áp đặt theo chuẩn kiến thức, kỹ năng thông thường.', 'Thuộc tính đánh dấu khuyết tật không đánh giá của người học (giá trị có/không).', array['MOET07']::text[], 'isKhuyetTatKhongDanhGia', 'Boolean', 'Đúng/Sai', '1', null),
  ('BG_00031', 'Tên cha', 'Là thông tin họ tên của cha người học', 'Thuộc tính ghi nhận tên cha của người học.', array['MOET07']::text[], 'tenCha', 'String', 'Chuỗi ký tự', '200', null),
  ('BG_00032', 'Nghề nghiệp cha', 'Là thông tin về nghề nghiệp của cha của người học.', 'Thuộc tính mô tả nghề nghiệp cha của việc làm của người học.', array['MOET07']::text[], 'ngheNghiepCha', 'String', 'Chuỗi ký tự', '255', null),
  ('BG_00033', 'Năm sinh cha', 'Là năm sinh của cha của người học.', 'Thuộc tính định lượng phản ánh năm sinh cha của người học; phục vụ thống kê, tổng hợp và đánh giá.', array['MOET07']::text[], 'namSinhCha', 'Integer', 'Số nguyên', null, null),
  ('BG_00034', 'Tên mẹ', 'Là thông tin họ tên của mẹ người học', 'Thuộc tính mô tả tên mẹ của người học.', array['MOET07']::text[], 'tenMe', 'String', 'Chuỗi ký tự', '200', null),
  ('BG_00035', 'Nghề nghiệp mẹ', 'Là thông tin về nghề nghiệp của mẹ của người học.', 'Thuộc tính mô tả nghề nghiệp mẹ của người học.', array['MOET07']::text[], 'ngheNghiepMe', 'String', 'Chuỗi ký tự', '255', null),
  ('BG_00036', 'Năm sinh mẹ', 'Là năm sinh của mẹ của người học.', 'Thuộc tính mô tả năm sinh mẹ của người học.', array['MOET07']::text[], 'namSinhMe', 'Integer', 'Số nguyên', null, null),
  ('BG_00037', 'Tên người đỡ đầu', 'Là thông tin họ tên của người đỡ đầu của người học', 'Thuộc tính mô tả tên người đỡ đầu của người học.', array['MOET07']::text[], 'tenNguoiDd', 'String', 'Chuỗi ký tự', '200', null),
  ('BG_00038', 'Nghề nghiệp người đỡ đầu', 'Là thông tin về nghề nghiệp của người đỡ đầu của người học.', 'Thuộc tính mô tả nghề nghiệp người đỡ đầu của người học.', array['MOET07']::text[], 'ngheNghiepNguoiDd', 'String', 'Chuỗi ký tự', '255', null),
  ('BG_00039', 'Năm sinh người đỡ đầu', 'Là năm sinh của người đỡ đầu của người học.', 'Thuộc tính mô tả năm sinh người đỡ đầu của người học.', array['MOET07']::text[], 'namSinhNguoiDoDau', 'Integer', 'Số nguyên', null, null),
  ('BG_00040', 'Cha dân tộc', 'Là thông tin xác định người học có cha là người dân tộc không thuộc dân tộc Kinh', 'Thuộc tính đánh dấu cha dân tộc của người học (giá trị có/không).', array['MOET07']::text[], 'isChaDt', 'Boolean', 'Đúng/Sai', '1', null),
  ('BG_00041', 'Mẹ dân tộc', 'Là thông tin xác định người học có mẹ là người dân tộc không thuộc dân tộc Kinh', 'Thuộc tính đánh dấu mẹ dân tộc của người học (giá trị có/không).', array['MOET07']::text[], 'isMeDt', 'Boolean', 'Đúng/Sai', '1', null),
  ('BG_00042', 'Tên dân tộc theo giấy khai sinh', 'Là tên dân tộc mà người học ghi trên giấy khai sinh.', 'Thuộc tính ghi nhận tên dân tộc theo giấy khai sinh của người học.', array['MOET07']::text[], 'danTocTheoGiayKhaiSinh', 'String', 'Chuỗi ký tự', '200', null),
  ('BG_00043', 'Số điện thoại của người học', 'Là ''số điện thoại'' của người học hoặc của người giám hộ cho người học dùng để liên lạc với người đó trong trường hợp cần thiết.', 'Thuộc tính mô tả số điện thoại của người học hoặc của người giám hộ cho người học .', array['MOET07']::text[], 'soDienThoaiNh', 'String', 'Chuỗi ký tự', '50', 'CDE-LL-001'),
  ('BG_00044', 'Chiều cao', 'Là chỉ số sức khỏe của người học được ghi nhận trong hồ sơ quản lý.', 'Thuộc tính định lượng phản ánh chiều cao của người học; phục vụ thống kê, tổng hợp và đánh giá.', array['MOET07']::text[], 'chieuCao', 'Number', 'Số thập phân', null, null),
  ('BG_00045', 'Cân nặng', 'Là chỉ số sức khỏe của người học được ghi nhận trong hồ sơ quản lý.', 'Thuộc tính định lượng phản ánh cân nặng của người học; phục vụ thống kê, tổng hợp và đánh giá.', array['MOET07']::text[], 'canNang', 'Number', 'Số thập phân', null, null),
  ('BG_00046', 'Nhóm máu', 'Là chỉ số sức khỏe của người học được ghi nhận trong hồ sơ quản lý.', 'Thuộc tính mô tả nhóm máu của người học.', array['MOET07']::text[], 'nhomMau', 'String', 'Chuỗi ký tự', '255', null),
  ('BG_00047', 'Chỉ số (BMI)', 'Là chỉ số sức khỏe của người học được ghi nhận trong hồ sơ quản lý.', 'Thuộc tính định lượng phản ánh chỉ số (BMI) của người học.', array['MOET07']::text[], 'chiSoBmi', 'Number', 'Số thập phân', null, null),
  ('BG_00048', 'Các bệnh về mắt', 'Là danh sách mô tả các bệnh về mắt', 'Thuộc tính mô tả các bệnh về mắt của người học.', array['MOET07']::text[], 'benhVeMat', 'String', 'Chuỗi ký tự', '255', null),
  ('BG_00049', 'Các bệnh bẩm sinh', 'Là danh sách mô tả các bệnh bẩm sinh', 'Thuộc tính mô tả các bệnh bẩm sinh của người học.', array['MOET07']::text[], 'benhBamSinh', 'String', 'Chuỗi ký tự', '255', null),
  ('BG_00050', 'Các bệnh về cột sống', 'Là danh sách để mô tả ''các bệnh về cột sống''', 'Thuộc tính mô tả các bệnh về cột sống của người học.', array['MOET07']::text[], 'benhCotSong', 'String', 'Chuỗi ký tự', '255', null),
  ('BG_00051', 'Bệnh còi xương', 'Là bệnh khiến xương phát triển chậm, trẻ bị hạn chế chiều cao và dễ gãy xương', 'Thuộc tính mô tả bệnh còi xương của người học.', array['MOET07']::text[], 'benhCoiXuong', 'String', 'Chuỗi ký tự', '255', null),
  ('BG_00052', 'Biết bơi', 'Là thông tin xác định người học có biết bơi', 'Thuộc tính mô tả biết bơi của người học.', array['MOET07']::text[], 'bietBoi', 'String', 'Chuỗi ký tự', '255', null),
  ('BG_00053', 'Đội viên', 'Là thiếu niên Việt Nam từ 9 đến hết 15 tuổi, được kết nạp vào Đội Thiếu niên Tiền phong Hồ Chí Minh.', 'Thuộc tính đánh dấu người học đã được kết nạp là đội viên (giá trị có/không).', array['MOET07']::text[], 'isDoiVien', 'Boolean', 'Đúng/Sai', '1', null),
  ('BG_00054', 'Đoàn viên', 'Là những bạn trẻ từ 16 tuổi trở lên (thường là học sinh THPT), tích cực học tập, rèn luyện, tán thành Điều lệ Đoàn và được kết nạp vào Đoàn TNCS Hồ Chí Minh.', 'Thuộc tính đánh dấu người học đã được kết nạp là đoàn viên (giá trị có/không).', array['MOET07']::text[], 'isDoanVien', 'Boolean', 'Đúng/Sai', '1', null),
  ('BG_00055', 'Ngày vào đảng của người học', 'Là ngày người học được kết nạp vào Đảng.', 'Thuộc tính ghi nhận mốc thời gian ngày vào đảng của người học.', array['MOET07']::text[], 'ngayVaoDangNh', 'Date', 'Ngày tháng', '10', 'CDE-TG-001'),
  ('BG_00056', 'Ngày vào đảng chính thức của người học', 'Là ngày người học được công nhận là đảng viên chính thức sau thời gian dự bị theo quy định của Điều lệ Đảng.', 'Thuộc tính ghi nhận mốc thời gian ngày vào đảng chính thức của người học.', array['MOET07']::text[], 'ngayVaoDangCtNh', 'Date', 'Ngày tháng', '10', 'CDE-TG-001'),
  ('BG_00057', 'Ngày vào đoàn', 'Là ngày người học chính thức được kết nạp vào Đoàn theo quyết định của tổ chức Đoàn.', 'Thuộc tính ghi nhận mốc thời gian ngày vào đoàn của người học.', array['MOET07']::text[], 'ngayVaoDoan', 'Date', 'Ngày tháng', '10', 'CDE-TG-001'),
  ('BG_00058', 'Đã học lớp cảm tình đảng', 'Là người học đã tham gia học lớp cảm tình Đảng.', 'Thuộc tính đánh dấu đã học lớp cảm tình đảng của người học (giá trị có/không).', array['MOET07']::text[], 'daHocCamTinhDang', 'Boolean', 'Đúng/Sai', '1', null),
  ('BG_00059', 'Mã số BHXH', 'Mã số gồm 10 chữ số được Bảo hiểm Xã hội Việt Nam cấp cho mỗi người tham gia hệ thống bảo hiểm xã hội, bảo hiểm y tế, bảo hiểm thất nghiệp.', 'Thuộc tính về số bảo hiểm xã hội của cá nhân.', array['MOET07', 'MOET18']::text[], 'maSoBaoHiemXaHoi', 'String', 'Chuỗi ký tự', '10', 'CDE-CN-006'),
  ('BG_00060', 'Hình thức học bán trú', 'Là học sinh tham gia học bán trú tại trường theo hình thức Diện chính sách hay tự nguyện...', 'Thuộc tính phân loại hình thức học bán trú của chính sách, hỗ trợ người học; chuẩn hóa danh mục, phục vụ thống kê và báo cáo trong quản lý giáo dục.', array['MOET07']::text[], 'hocBanTru', 'Enumeration', 'Danh mục liệt kê', null, null),
  ('BG_00061', 'Nhu cầu hỗ trợ ngoại ngữ', 'Là người học gặp khó khăn trong việc tiếp thu chương trình ngoại ngữ chính khóa hoặc có nhu cầu phát triển ngôn ngữ chuyên sâu vượt mức cơ bản.', 'Thuộc tính đánh dấu nhu cầu hỗ trợ ngoại ngữ của chính sách, hỗ trợ người học (giá trị có/không).', array['MOET07']::text[], 'isNhuCauHoTroNngu', 'Boolean', 'Đúng/Sai', '1', null),
  ('BG_00062', 'Tăng cường tiếng Việt', 'Là hoạt động hỗ trợ ngôn ngữ đặc thù trong các cơ sở giáo dục, tập trung chủ yếu cho người học mầm non và tiểu học người dân tộc thiểu số.', 'Thuộc tính đánh dấu tăng cường tiếng Việt của chính sách, hỗ trợ người học (giá trị có/không).', array['MOET07']::text[], 'isTangCuongTiengViet', 'Boolean', 'Đúng/Sai', '1', null),
  ('BG_00063', 'Học sinh dân tộc trợ giảng', 'Là người học thuộc người dân tộc thiểu số đóng vai trò là cầu nối ngôn ngữ và văn hóa.', 'Thuộc tính đánh dấu học sinh dân tộc trợ giảng của người học (giá trị có/không).', array['MOET07']::text[], 'isHocSinhDtTroGiang', 'Boolean', 'Đúng/Sai', '1', null),
  ('BG_00064', 'Tuyển mới mầm non', 'Là các trẻ em trong độ tuổi từ 3 tháng đến 6 tuổi, lần đầu đăng ký nhập học hoặc chuyển trường vào các cơ sở giáo dục mầm non ở năm học hiện tại.', 'Thuộc tính đánh dấu người học thuộc loại tuyển mới mầm non.', array['MOET08']::text[], 'isTuyenMoiMn', 'Boolean', 'Đúng/Sai', '1', null),
  ('BG_00065', 'Đối tượng đầu vào', 'Là phân loại người học theo diện tuyển sinh khi nhập học.', 'Thuộc tính mô tả đầu vào của tuyển sinh và nhập học.', array['MOET08']::text[], 'doiTuongDauVao', 'String', 'Chuỗi ký tự', '80', null),
  ('BG_00066', 'Khóa học', 'Là niên khóa hoặc khoảng thời gian đào tạo mà người học tham gia', 'Thuộc tính mô tả khóa học của người học cấp đại học/giáo dục nghề nghiệp.', array['MOET08']::text[], 'khoaHoc', 'String', 'Chuỗi ký tự', '80', null),
  ('BG_00067', 'Khoa', 'Là đơn vị chuyên môn thuộc cơ sở đào tạo quản lý chương trình học của người học.', 'Thuộc tính mô tả khoa của hoạt động nghiên cứu khoa học của người học.', array['MOET08']::text[], 'khoa', 'String', 'Chuỗi ký tự', '80', null),
  ('BG_00068', 'Lớp sinh hoạt', 'Là đơn vị tổ chức quản lý người học theo lớp hành chính hoặc lớp học, phục vụ quản lý sinh hoạt và học tập.', 'Thuộc tính mô tả lớp sinh hoạt của quá trình học tập, rèn luyện của người học.', array['MOET08']::text[], 'lopSinhHoat', 'String', 'Chuỗi ký tự', '80', null),
  ('BG_00069', 'Bằng tốt nghiệp liên thông', 'Là văn bằng được cấp cho người học sau khi hoàn thành chương trình đào tạo theo hình thức liên thông.', 'Thuộc tính mô tả bằng tốt nghiệp liên thông của người học.', array['MOET08']::text[], 'bangTotNghiepLienThong', 'String', 'Chuỗi ký tự', '100', null),
  ('BG_00070', 'Số quyết định nhập học', 'Là số quyết định được xác định trong văn bản nhập học của người học do cơ quan có thẩm quyền ban hành.', 'Thuộc tính ghi nhận số quyết định nhập học của người học.', array['MOET08']::text[], 'soQdNhapHoc', 'String', 'Chuỗi ký tự', '50', null),
  ('BG_00071', 'Ngày quyết định nhập học', 'Là ngày ghi trên số quyết định nhập học của người học do cơ quan có thẩm quyền ban hành.', 'Thuộc tính ghi nhận mốc thời gian ngày quyết định nhập học của người học.', array['MOET08']::text[], 'ngayQdNhapHoc', 'Date', 'Ngày tháng', '10', 'CDE-TG-001'),
  ('BG_00072', 'Kết quả tuyển sinh', 'Là kết quả đánh giá đầu vào của người học trong kỳ tuyển sinh (ví dụ: trúng tuyển, không trúng tuyển, điểm xét tuyển).', 'Thuộc tính mô tả kết quả tuyển sinh của người học.', array['MOET08']::text[], 'ketQuaTuyenSinh', 'String', 'Chuỗi ký tự', '20', null),
  ('BG_00073', 'Học sinh bán trú dân nuôi', 'Là học sinh được hưởng mô hình giáo dục đặc thù tại các vùng khó khăn, dân tộc thiểu số được tổ chức ăn, nghỉ tại cơ sở giáo dục trong ngày nhưng không ở lại qua đêm.', 'Thuộc tính đánh dấu học sinh bán trú dân nuôi của người học (giá trị có/không).', array['MOET09']::text[], 'isHocSinhBanTruDanNuoi', 'Boolean', 'Đúng/Sai', '1', null),
  ('BG_00074', 'Học sinh nội trú dân nuôi', 'Là học sinh được hưởng mô hình giáo dục đặc thù tại các vùng khó khăn, dân tộc thiểu số được tổ chức ăn, nghỉ qua đêm tại cơ sở giáo dục.', 'Thuộc tính đánh dấu học sinh nội trú dân nuôi của người học (giá trị có/không).', array['MOET09']::text[], 'isHocSinhNoiTruDanNuoi', 'Boolean', 'Đúng/Sai', '1', null),
  ('BG_00075', 'Học sinh phổ thông dân tộc bán trú', 'Là học sinh trung học cơ sở (chủ yếu là người dân tộc thiểu số), sinh sống tại các xã, thôn đặc biệt khó khăn, không thể đi đến trường và trở về nhà trong ngày do đó được tổ chức ăn, nghỉ tại cơ sở giáo dục trong ngày nhưng không ở lại qua đêm.', 'Thuộc tính đánh dấu học sinh phổ thông dân tộc bán trú của người học (giá trị có/không).', array['MOET09']::text[], 'isHocSinhPtDtBanTru', 'Boolean', 'Đúng/Sai', '1', null),
  ('BG_00076', 'Diện chính sách', 'Là học sinh thuộc các diện chính sách được hỗ trợ dựa trên quy định của pháp luật hiện hành.', 'Thuộc tính phân loại diện chính sách của chính sách, hỗ trợ người học thuộc hoặc được hưởng.', array['MOET09']::text[], 'dienChinhSach', 'Enumeration', 'Danh mục liệt kê', null, null),
  ('BG_00077', 'Hộ nghèo', 'Là thông tin xác định người học có thuộc diện ''hộ nghèo''', 'Thuộc tính đánh dấu hộ nghèo của người học (giá trị có/không).', array['MOET09']::text[], 'isHoNgheo', 'Boolean', 'Đúng/Sai', '1', null),
  ('BG_00078', 'Miễn học phí', 'Là người học được hưởng chính sách không thu học phí theo quy định của pháp luật hiện hành.', 'Thuộc tính đánh dấu miễn học phí của chính sách, hỗ trợ người học (giá trị có/không).', array['MOET09']::text[], 'isMienHocPhi', 'Boolean', 'Đúng/Sai', '1', null),
  ('BG_00079', 'Giảm học phí', 'Là người học được hưởng chính sách miễn giảm học phí theo quy định của pháp luật hiện hành.', 'Thuộc tính đánh dấu giảm học phí của chính sách, hỗ trợ người học (giá trị có/không).', array['MOET09']::text[], 'isGiamHocPhi', 'Boolean', 'Đúng/Sai', '1', null),
  ('BG_00080', 'Hỗ trợ chi phí học tập', 'Là người học được hỗ trợ chi phí học tập là chính sách ưu đãi của Nhà nước, cấp một khoản tiền trực tiếp (VNĐ/tháng theo các quy định hiện hành) cho trẻ mầm non, học sinh phổ thông có hoàn cảnh đặc biệt khó khăn (mồ côi, khuyết tật, hộ nghèo, vùng sâu) để mua sách, vở và đồ dùng học tập.', 'Thuộc tính đánh dấu hỗ trợ chi phí học tập của chính sách, hỗ trợ người học (giá trị có/không).', array['MOET09']::text[], 'isHoTroChiPhiHocTap', 'Boolean', 'Đúng/Sai', '1', null),
  ('BG_00081', 'Hỗ trợ nhà ở', 'Là trường hợp học sinh phải tự túc chỗ ở (do nhà trường không bố trí được ký túc xá hoặc học sinh cần thuê trọ gần trường) sẽ nhận được mức hỗ trợ tiền thuê trọ/chỗ ở', 'Thuộc tính đánh dấu hỗ trợ nhà ở cho người học (giá trị có/không).', array['MOET09']::text[], 'isHoTroNhaO', 'Boolean', 'Đúng/Sai', '1', null),
  ('BG_00082', 'Cấp tiền hàng tháng', 'Là học sinh cấp tiền hàng tháng là các chính sách hỗ trợ của Nhà nước nhằm giảm bớt gánh nặng tài chính, giúp học sinh khó khăn tiếp tục đến trường.', 'Thuộc tính đánh dấu cấp tiền hàng tháng của chính sách, hỗ trợ người học (giá trị có/không).', array['MOET09']::text[], 'isCapTienHangThang', 'Boolean', 'Đúng/Sai', '1', null),
  ('BG_00083', 'Cấp gạo', 'là chính sách an sinh xã hội của Nhà nước Việt Nam, hỗ trợ gạo từ nguồn dự trữ quốc gia cho học sinh tại các khu vực đặc biệt khó khăn, vùng dân tộc thiểu số và miền núi', 'Thuộc tính đánh dấu cấp gạo của chính sách, hỗ trợ người học (giá trị có/không).', array['MOET09']::text[], 'isCapGao', 'Boolean', 'Đúng/Sai', '1', null),
  ('BG_00084', 'Hỗ trợ ăn trưa', 'Là trẻ bán trú được nhà nước hỗ trợ tiền ăn trưa.', 'Thuộc tính đánh dấu trẻ có được hỗ trợ ăn trưa (giá trị có/không).', array['MOET09']::text[], 'isHoTroAnTrua', 'Boolean', 'Đúng/Sai', '1', null),
  ('BG_00085', 'Hưởng khuyến khích', 'Là thông tin người học được hưởng điểm khuyến khích hoặc chế độ ưu tiên theo quy định trong kỳ thi hoặc xét tốt nghiệp.', 'Thuộc tính mô tả hưởng khuyến khích của chính sách, hỗ trợ người học.', array['MOET09']::text[], 'huongKk', 'String', 'Chuỗi ký tự', '50', null),
  ('BG_00086', 'Trạng thái hiện tại của người học', 'Là trạng thái hiện tại của người học theo quy định trong hệ thống quản lý giáo dục quốc dân.', 'Thuộc tính phân loại trạng thái hiện tại của người học.', array['MOET10']::text[], 'trangThaiHienTaiCuaNh', 'Enumeration', 'Danh mục liệt kê', null, null),
  ('BG_00087', 'Loại lý do thôi học của người học', 'Là danh mục dùng để xác định lý do thôi học của người học theo quy định trong hệ thống quản lý giáo dục.', 'Thuộc tính phân loại loại lý do thôi học của người học.', array['MOET10']::text[], 'loaiLyDoThoiHocCuaNh', 'Enumeration', 'Danh mục liệt kê', null, null),
  ('BG_00088', 'Ngày vào trường', 'Là ngày người học bắt đầu đi học tại một cơ sở giáo dục.', 'Thuộc tính ghi nhận mốc thời gian ngày vào trường của người học.', array['MOET10']::text[], 'ngayVaoTruong', 'Date', 'Ngày tháng', '10', 'CDE-TG-001'),
  ('BG_00089', 'Ngày chuyển trạng thái người học', 'Là ngày phát sinh thay đổi các trạng thái của người học như: chuyển đến, chuyển đi, đang học, nghỉ học, thôi học...', 'Thuộc tính ghi nhận mốc thời gian ngày chuyển trạng thái của người học.', array['MOET10']::text[], 'ngayChuyenTtNh', 'Date', 'Ngày tháng', '10', 'CDE-TG-001'),
  ('BG_00090', 'Trạng thái người học', 'Là tình trạng học tập của người học.', 'Thuộc tính phân loại trạng thái của người học; chuẩn hóa danh mục, phục vụ thống kê và báo cáo trong quản lý giáo dục.', array['MOET10']::text[], 'trangThaiNh', 'Enumeration', 'Danh mục liệt kê', null, null),
  ('BG_00091', 'Lưu ban năm trước', 'Là học sinh lưu ban (hay ở lại lớp) năm trước là người không đạt yêu cầu học tập hoặc rèn luyện, buộc phải học lại lớp cũ trong năm học mới thay vì được lên lớp trên.', 'Thuộc tính đánh dấu lưu ban năm trước của mục tiêu, chuẩn đầu ra và yêu cầu cần đạt của chương trình đào tạo (giá trị có/không).', array['MOET11']::text[], 'isLuuBanNamTruoc', 'Boolean', 'Đúng/Sai', '1', null),
  ('BG_00092', 'Học mẫu giáo 5 tuổi', 'Là người học cấp Tiểu học đã được học mẫu giáo 5 tuổi.', 'Thuộc tính đánh dấu học mẫu giáo 5 tuổi của người học.', array['MOET11']::text[], 'isHocLopMg5t', 'Boolean', 'Đúng/Sai', '1', null),
  ('BG_00093', 'Điểm tổng kết của người học', 'Là trung bình cộng của điểm trung bình cả năm của các môn học đánh giá bằng cho điểm.', 'Thuộc tính mô tả điểm tổng kết của người học.', array['MOET11']::text[], 'diemTongKet', 'String', 'Chuỗi ký tự', '4', null),
  ('BG_00094', 'Học lực của người học', 'Là kết quả đánh giá năng lực học tập dựa trên điểm số (theo Thông tư 58/2011/TT-BGDĐT).', 'Thuộc tính phân loại học lực của người học.', array['MOET11']::text[], 'hocLuc', 'Enumeration', 'Danh mục liệt kê', null, null),
  ('BG_00095', 'Hạnh kiểm của người học', 'Là việc đánh giá ý thức, đạo đức, thái độ và hành vi của học sinh đối với các quy định của nhà trường, thầy cô và tập thể.', 'Thuộc tính phân loại hạnh kiểm của người học căn cứ theo căn cứ theo quy định về đánh giá học sinh của bộ giáo dục', array['MOET11']::text[], 'hanhKiem', 'Enumeration', 'Danh mục liệt kê', null, null),
  ('BG_00096', 'Kết quả học tập của người học', 'Là kết quả học tập của học sinh phổ thông và giáo dục thường xuyên là mức độ đạt được về kiến thức, kỹ năng và năng lực của một học kỳ, năm học được đánh giá qua điểm trung bình môn học kỳ/cả năm của các môn học.', 'Thuộc tính phân loại kết quả học tập của người học.', array['MOET11']::text[], 'ketQuaHocTap', 'Enumeration', 'Danh mục liệt kê', null, null),
  ('BG_00097', 'Kết quả rèn luyện của người học', 'Là kết quả rèn luyện của học sinh phổ thông là sự đánh giá phẩm chất đạo đức, lối sống, tác phong và ý thức kỷ luật theo từng học kỳ và cả năm học theo chương trình giáo dục phổ thông và chương trình giáo dục thường xuyên.', 'Thuộc tính phân loại kết quả rèn luyện của người học.', array['MOET11']::text[], 'ketQuaRenLuyen', 'Enumeration', 'Danh mục liệt kê', null, null),
  ('BG_00098', 'Danh hiệu của người học', 'Là danh hiệu cơ sở giáo dục trao cho học sinh để ghi nhận, biểu dương và tôn vinh các cá nhân có thành tích xuất sắc trong học tập, rèn luyện cuối năm học.', 'Thuộc tính phân loại danh hiệu của người học.', array['MOET11']::text[], 'danhHieu', 'Enumeration', 'Danh mục liệt kê', null, null),
  ('BG_00099', 'Số ngày nghỉ của người học', 'Là số buổi nghỉ học của học sinh trong một năm học.', 'Thuộc tính mô tả số ngày nghỉ của người học.', array['MOET11']::text[], 'soNgayNghi', 'String', 'Chuỗi ký tự', '10', null),
  ('BG_00100', 'Nhận xét của hiệu trưởng cho của người học', 'Là đánh giá chính thức của cơ sở giáo dục về toàn bộ kết quả học tập và rèn luyện đạo đức của người học trong một năm học', 'Thuộc tính mô tả nhận xét của hiệu trưởng cho của người học.', array['MOET11']::text[], 'nhanXetHieuTruong', 'String', 'Chuỗi ký tự', '255', null),
  ('BG_00101', 'Người học được lên lớp', 'Là học sinh được đánh giá đủ điều kiện để "được lên lớp"', 'Thuộc tính đánh dấu người học được lên lớp của người học (giá trị có/không).', array['MOET11']::text[], 'isLenLop', 'Boolean', 'Đúng/Sai', '1', null),
  ('BG_00102', 'Người học được rèn luyện lại', 'Là trường hợp học sinh có kết quả rèn luyện cả năm học được đánh giá mức Chưa đạt thì phải rèn luyện trong kì nghỉ hè.', 'Thuộc tính đánh dấu người học được rèn luyện lại của người học (giá trị có/không).', array['MOET11']::text[], 'isRenLuyenLai', 'Boolean', 'Đúng/Sai', '1', null),
  ('BG_00103', 'Điểm môn học', 'Là điểm số mà người học đạt được cho một môn học nào đó', 'Thuộc tính định lượng phản ánh điểm môn học của người học mà giáo viên bộ môn chấm điểm cho người học đó trong thời gian tham gia học tập.', array['MOET11']::text[], 'diem', 'Decimal', 'Số thập phân', null, null),
  ('BG_00104', 'Hoàn thành chương trình mầm non', 'Là trẻ em 5 tuổi đã hoàn thành chương trình giáo dục mầm non theo quy định của Bộ Giáo dục và Đào tạo, đảm bảo phát triển toàn diện về thể chất, tình cảm, trí tuệ và ngôn ngữ, sẵn sàng tâm thế vào lớp 1. Trẻ sẽ được cấp Giấy chứng nhận hoàn thành chương trình giáo dục mầm non', 'Thuộc tính đánh dấu hoàn thành chương trình mầm non của chương trình giáo dục và đào tạo (giá trị có/không).', array['MOET11']::text[], 'isHoanThanhChuongTrinhMamNon', 'Boolean', 'Đúng/Sai', '1', null),
  ('BG_00105', 'Số sổ đăng bộ', 'Là mã số (hoặc số thứ tự) được ghi trong sổ đăng bộ – tài liệu pháp lý lưu trữ danh sách học sinh nhập học theo khóa học do cơ sở giáo dục quản lý.', 'Thuộc tính mô tả số sổ đăng bộ của cơ sở giáo dục, trung tâm, cơ sở đào tạo.', array['MOET11']::text[], 'soSoDangBo', 'String', 'Chuỗi ký tự', '150', null),
  ('BG_00106', 'Số ngày nghỉ có phép', 'Là tổng số ngày (hoặc buổi) người học vắng mặt tại cơ sở giáo dục nhưng đã thực hiện đúng quy trình xin phép và được sự đồng ý của giáo viên chủ nhiệm.', 'Thuộc tính mô tả số ngày nghỉ có phép của hoạt động nghiên cứu khoa học của người học.', array['MOET11']::text[], 'tongSoBuoiNghiCoPhep', 'Number', 'Số', null, null),
  ('BG_00107', 'Số ngày nghỉ không phép', 'Là tổng số ngày (hoặc buổi) người học vắng mặt tại cơ sở giáo dục nhưng chưa thực hiện xin phép giáo viên chủ nhiệm.', 'Thuộc tính mô tả số ngày nghỉ không phép của cơ sở giáo dục, trung tâm, cơ sở đào tạo.', array['MOET11']::text[], 'tongSoBuoiNghiKhongPhep', 'Number', 'Số', null, null),
  ('BG_00108', 'Kết quả xếp loại', 'Là đánh giá kết quả giáo dục cuối năm học của người học cấp Tiểu học căn cứ vào quá trình tổng hợp kết quả đánh giá về học tập từng môn học, hoạt động giáo dục và từng phẩm chất chủ yếu, năng lực cốt lõi, giáo viên chủ nhiệm thực hiện đánh giá theo 4 mức: Hoàn thành xuất sắc, Hoàn thành tốt, Hoàn thành và Chưa hoàn thành.', 'Thuộc tính mô tả kết quả xếp loại của người học khi tham gia chương trình giáo dục cấp tiểu học trong một năm học.', array['MOET11']::text[], 'ketQuaXepLoai', 'String', 'Chuỗi ký tự', '150', null),
  ('BG_00109', 'Nội dung hoàn thành chương trình lớp học cấp tiểu học', 'Là nội dung mà cơ sở giáo dục nhận xét các người học hoàn thành chương trình lớp học cấp tiểu học.', 'Thuộc tính mô tả nội dung hoàn thành chương trình lớp học cấp tiểu học của người học.', array['MOET11']::text[], 'noiDungHoanThanhCtLhCapTh', 'String', 'Chuỗi ký tự', '255', null),
  ('BG_00110', 'Người học hoàn thành chương trình lớp học cấp tiểu học', 'Là những người học cấp tiểu học được đánh giá kết quả giáo dục ở một trong ba mức: Hoàn thành xuất sắc, Hoàn thành tốt, Hoàn thành.', 'Thuộc tính mô tả người học hoàn thành chương trình lớp học cấp tiểu học của người học.', array['MOET11']::text[], 'hoanThanhCtLhCapTh', 'String', 'Chuỗi ký tự', '255', null),
  ('BG_00111', 'Người học hoàn thành chương trình tiểu học', 'Là người học hoàn thành chương trình lớp 5 được xác nhận và ghi vào Học bạ: Hoàn thành chương trình tiểu học.', 'Thuộc tính mô tả người học hoàn thành chương trình tiểu học của người học.', array['MOET11']::text[], 'daHoanThanhChuongTrinhTieuHoc', 'String', 'Chuỗi ký tự', '1', null),
  ('BG_00112', 'Nhận xét giáo viên chủ nhiệm', 'Là nội dung mà cán bộ/nhà giáo được phân công chủ nhiệm lớp nhận xét về người học trong một năm học.', 'Thuộc tính mô tả nhận xét giáo viên chủ nhiệm cho người học.', array['MOET11']::text[], 'nhanXetGvcn', 'String', 'Chuỗi ký tự', '900', null),
  ('BG_00113', 'Mức đạt được môn học của người học', 'Là danh mục mà cán bộ/nhà giáo sử dụng để đánh giá người học về mức độ đạt được của môn học cấp tiểu học sau một giai đoạn học tập như giữa kỳ, cuối kỳ, cả năm học.', 'Thuộc tính mô tả mức đạt được môn học của người học cấp tiểu học.', array['MOET11']::text[], 'mucDatDuoc', 'String', 'Chuỗi ký tự', '10', null),
  ('BG_00114', 'Điểm kiểm tra định kỳ của người học', 'Là điểm số của môn học mà người học đạt được sau khi làm các bài kiểm tra định kỳ sau một giai đoạn học tập như giữa kỳ, cuối kỳ, cả năm học.', 'Thuộc tính mô tả điểm kiểm tra định kỳ của người học.', array['MOET11']::text[], 'diemKiemTraDinhKy', 'String', 'Chuỗi ký tự', '2', null),
  ('BG_00115', 'Năng lực tự chủ tự học của người học', 'Là việc đánh giá khả năng người học ở cấp tiểu học tự làm chủ bản thân (quản lý cảm xúc, hành vi, mục tiêu) và chủ động thu nhận, phát triển kiến thức, kỹ năng một cách độc lập mà không cần sự giám sát hay phụ thuộc hoàn toàn vào người khác.', 'Thuộc tính mô tả năng lực tự chủ tự học của người học.', array['MOET11']::text[], 'nangLucTuChuTuHoc', 'String', 'Chuỗi ký tự', '20', null),
  ('BG_00116', 'Năng lực giao tiếp hợp tác của người học', 'Là việc đánh giá khả năng người học ở cấp tiểu học sử dụng ngôn ngữ, cử chỉ và tư duy để tương tác, trao đổi thông tin và phối hợp chặt chẽ với nhau.', 'Thuộc tính mô tả năng lực giao tiếp hợp tác của người học.', array['MOET11']::text[], 'nangLucGiaoTiepHopTac', 'String', 'Chuỗi ký tự', '20', null),
  ('BG_00117', 'Năng lực giải quyết vấn đề sáng tạo của người học', 'Là khả năng người học ở cấp tiểu học nhận diện, phân tích tình huống, sau đó vận dụng kiến thức và tư duy độc lập để đề xuất, triển khai các giải pháp mới mẻ, độc đáo, mang lại hiệu quả cao.', 'Thuộc tính mô tả năng lực giải quyết vấn đề sáng tạo của người học.', array['MOET11']::text[], 'nangLucGiaiQuyetVanDeSangTao', 'String', 'Chuỗi ký tự', '20', null),
  ('BG_00118', 'Năng lực ngôn ngữ của người học', 'Là khả năng người học ở cấp tiểu học có thể sử dụng ngôn ngữ (bao gồm năng lực sử dụng tiếng Việt và năng lực sử dụng ngoại ngữ) qua các hoạt động: nghe, nói, đọc, viết.', 'Thuộc tính mô tả năng lực ngôn ngữ của người học.', array['MOET11']::text[], 'nangLucNgonNgu', 'String', 'Chuỗi ký tự', '20', null),
  ('BG_00119', 'Năng lực tính toán của người học', 'Là khả năng người học ở cấp tiểu học nắm vững các kiến thức số học cơ bản (số tự nhiên, phân số, số thập phân) và các phép tính, kết hợp cùng tư duy toán học để thực hiện tính toán chính xác và vận dụng giải quyết các vấn đề thực tiễn.', 'Thuộc tính mô tả năng lực tính toán của người học.', array['MOET11']::text[], 'nangLucTinhToan', 'String', 'Chuỗi ký tự', '20', null),
  ('BG_00120', 'Năng lực khoa học của người học', 'Là khả năng người học ở cấp tiểu học quan sát, tìm hiểu, giải thích các hiện tượng tự nhiên và vận dụng kiến thức đã học vào thực tiễn.', 'Thuộc tính mô tả năng lực khoa học của người học.', array['MOET11']::text[], 'nangLucKhoaHoc', 'String', 'Chuỗi ký tự', '20', null),
  ('BG_00121', 'Năng lực công nghệ của người học', 'Là khả năng người học ở cấp tiểu học bước đầu làm quen với quy trình tạo ra các sản phẩm đơn giản, nhận biết vai trò của công nghệ trong đời sống, sử dụng an toàn các công cụ cơ bản và hình thành tư duy kỹ thuật.', 'Thuộc tính mô tả năng lực công nghệ của người học.', array['MOET11']::text[], 'nangLucCongNghe', 'String', 'Chuỗi ký tự', '20', null),
  ('BG_00122', 'Năng lực tin học của người học', 'Là khả năng người học ở cấp tiểu học biết sử dụng các thiết bị công nghệ (máy tính, máy tính bảng) và môi trường kỹ thuật số để học tập, vui chơi, giải quyết vấn đề đơn giản, đồng thời hình thành ý thức ứng xử an toàn trên mạng.', 'Thuộc tính mô tả năng lực tin học của người học.', array['MOET11']::text[], 'nangLucTinHoc', 'String', 'Chuỗi ký tự', '20', null),
  ('BG_00123', 'Năng lực thẩm mĩ của người học', 'Là khả năng người học ở cấp tiểu học cảm nhận, thấu hiểu, đánh giá và sáng tạo cái đẹp trong tự nhiên, cuộc sống cũng như các tác phẩm nghệ thuật.', 'Thuộc tính mô tả năng lực thẩm mĩ của người học.', array['MOET11']::text[], 'nangLucThamMi', 'String', 'Chuỗi ký tự', '20', null),
  ('BG_00124', 'Năng lực thể chất của người học', 'Là khả năng người học ở cấp tiểu học biết vận động, rèn luyện sức khỏe, xây dựng lối sống lành mạnh và tự chăm sóc bản thân.', 'Thuộc tính mô tả năng lực thể chất của người học.', array['MOET11']::text[], 'nangLucTheChat', 'String', 'Chuỗi ký tự', '20', null),
  ('BG_00125', 'Phẩm chất yêu nước của người học', 'Là đánh giá người học ở cấp tiểu học có ý thức, tình cảm gắn bó với quê hương, đất nước và thiên nhiên.', 'Thuộc tính mô tả phẩm chất yêu nước của người học.', array['MOET11']::text[], 'phamChatYeuNuoc', 'String', 'Chuỗi ký tự', '20', null),
  ('BG_00126', 'Phẩm chất nhân ái của người học', 'Là đánh giá người học ở cấp tiểu học có lối sống biết yêu thương, đùm bọc, tôn trọng và sẵn sàng giúp đỡ mọi người.', 'Thuộc tính mô tả phẩm chất nhân ái của người học.', array['MOET11']::text[], 'phamChatNhanAi', 'String', 'Chuỗi ký tự', '20', null),
  ('BG_00127', 'Phẩm chất chăm chỉ của người học', 'Là đánh giá người học ở cấp tiểu học có tinh thần miệt mài, cố gắng trong học tập và lao động.', 'Thuộc tính mô tả phẩm chất chăm chỉ của người học.', array['MOET11']::text[], 'phamChatChamChi', 'String', 'Chuỗi ký tự', '20', null),
  ('BG_00128', 'Phẩm chất trung thực của người học', 'Là đánh giá người học ở cấp tiểu học thật thà, ngay thẳng và tôn trọng sự thật trong học tập cũng như sinh hoạt hàng ngày.', 'Thuộc tính mô tả phẩm chất trung thực của người học.', array['MOET11']::text[], 'phamChatTrungThuc', 'String', 'Chuỗi ký tự', '20', null),
  ('BG_00129', 'Phẩm chất trách nhiệm của người học', 'Là đánh giá người học ở cấp tiểu học có ý thức tự giác thực hiện bổn phận đối với bản thân, gia đình, nhà trường và xã hội.', 'Thuộc tính mô tả phẩm chất trách nhiệm của người học.', array['MOET11']::text[], 'phamChatTrachNhiem', 'String', 'Chuỗi ký tự', '20', null),
  ('BG_00130', 'Nhận xét phẩm chất của người học', 'Là đánh giá của giáo viên chủ nhiệm về các phẩm chất đạo đức của người học.', 'Thuộc tính mô tả nhận xét phẩm chất của người học.', array['MOET11']::text[], 'nhanXetPhamChat', 'String', 'Chuỗi ký tự', '500', null),
  ('BG_00131', 'Nhận xét năng lực chung của người học', 'Là đánh giá của giáo viên chủ nhiệm về các năng lực chung: tự học, giao tiếp, hợp tác, giải quyết vấn đề của người học.', 'Thuộc tính mô tả nhận xét năng lực chung của người học.', array['MOET11']::text[], 'nhanXetNangLucChung', 'String', 'Chuỗi ký tự', '500', null),
  ('BG_00132', 'Nhận xét năng lực đặc thù của người học', 'Là đánh giá của giáo viên chủ nhiệm về các năng lực đặc thù theo môn học của người học.', 'Thuộc tính mô tả nhận xét năng lực đặc thù của người học.', array['MOET11']::text[], 'nhanXetNangLucDacThu', 'String', 'Chuỗi ký tự', '500', null),
  ('BG_00133', 'Nội dung hoàn thành chương trình cấp THCS, THPT, GDTX', 'Là nội dung mà cơ sở giáo dục nhận xét các người học hoàn thành chương trình cấp THCS, THPT, GDTX.', 'Thuộc tính mô tả nội dung hoàn thành chương trình cấp THCS, THPT, GDTX được nhận xét cho người học.', array['MOET11']::text[], 'noiDungHoanThanhCtPtGdtx', 'String', 'Chuỗi ký tự', '150', null),
  ('BG_00134', 'Kết quả tham gia các cuộc thi cấp THCS, THPT, GDTX', 'Là nội dung kết quả mà người học đã đạt được khi tham gia các cuộc thi cấp THCS, THPT, GDTX.', 'Thuộc tính mô tả nội dung kết quả tham gia các cuộc thi cấp THCS, THPT, GDTX của người học.', array['MOET11']::text[], 'ketQuaThamGiaCacCuocThi', 'String', 'Chuỗi ký tự', '500', null),
  ('BG_00135', 'Tên chứng chỉ người học', 'Là danh sách chứng chỉ mà người học đạt được tại cấp THCS, THPT, GDTX.', 'Thuộc tính ghi nhận tên chứng chỉ của người học.', array['MOET11']::text[], 'chungChiTenChungChi', 'String', 'Chuỗi ký tự', '150', null),
  ('BG_00136', 'Loại chứng chỉ người học', 'Là loại chứng chỉ: nghề, ngoại ngữ, tin học...mà người học đã đạt được tại cấp THCS, THPT, GDTX.', 'Thuộc tính mô tả loại chứng chỉ mà người học đạt được.', array['MOET11']::text[], 'chungChiLoaiChungChi', 'String', 'Chuỗi ký tự', '50', null),
  ('BG_00137', 'Điểm đánh giá thường xuyên của người học', 'Là điểm số đánh giá kết quả rèn luyện và học tập của học sinh diễn ra trong quá trình thực hiện hoạt động dạy học theo yêu cầu cần đạt được quy định trong Chương trình giáo dục phổ thông; cung cấp thông tin phản hồi cho cán bộ/nhà giáo và học sinh để kịp thời điều chỉnh trong quá trình dạy học; hỗ trợ, thúc đẩy sự tiến bộ của học sinh; xác nhận kết quả đạt được của học sinh trong quá trình thực hiện các nhiệm vụ rèn luyện và học tập.', 'Thuộc tính mô tả điểm thường xuyên mà giáo viên bộ môn chấm điểm người học trong quá trình tham gia học tập môn học đó.', array['MOET11']::text[], 'diemDanhGiaThuongXuyen', 'Number', 'Số', null, null),
  ('BG_00138', 'Điểm đánh giá định kỳ của người học', 'Là điểm số đánh giá kết quả rèn luyện và học tập sau một giai đoạn trong năm học nhằm xác định mức độ hoàn thành nhiệm vụ rèn luyện và học tập của học sinh theo yêu cầu cần đạt được quy định trong Chương trình giáo dục phổ thông; cung cấp thông tin phản hồi cho cán bộ quản lý giáo dục, cán bộ/nhà giáo, học sinh để điều chỉnh hoạt động dạy học; xác nhận kết quả đạt được của học sinh.', 'Thuộc tính mô tả điểm đánh giá định kỳ mà giáo viên bộ môn chấm điểm người học sau khi hoàn thành bài thi, bài kiểm tra hoặc thực hành.', array['MOET11']::text[], 'diemDanhGiaDinhKy', 'Number', 'Số', null, null),
  ('BG_00139', 'Điểm trung bình môn học kỳ 1 của người học', 'Là kết quả học tập của người học cấp THCS, THPT, GDTX trong nửa đầu năm học cho một môn học. Điểm này được tính dựa trên điểm số của các bài kiểm tra thường xuyên, giữa kỳ và cuối kỳ, áp dụng hệ số khác nhau theo quy định của Bộ Giáo dục và Đào tạo ban hành.', 'Thuộc tính mô tả điểm trung bình môn học kỳ 1 của người học.', array['MOET11']::text[], 'diemHocKy1', 'String', 'Chuỗi ký tự', '10', null),
  ('BG_00140', 'Điểm trung bình môn học kỳ 2 của người học', 'Là kết quả học tập của người học cấp THCS, THPT, GDTX trong nửa cuối năm học cho một môn học. Điểm này được tính dựa trên điểm số của các bài kiểm tra thường xuyên, giữa kỳ và cuối kỳ, áp dụng hệ số khác nhau theo quy định của Bộ Giáo dục và Đào tạo ban hành.', 'Thuộc tính mô tả điểm trung bình môn học kỳ 2 của người học.', array['MOET11']::text[], 'diemHocKy2', 'String', 'Chuỗi ký tự', '2', null),
  ('BG_00141', 'Điểm trung bình môn cả năm của người học', 'Là kết quả học tập của người học cấp THCS, THPT, GDTX cả năm học cho một môn học. Điểm này được tính dựa trên điểm trung bình môn học kỳ 1, học kỳ 2 áp dụng hệ số khác nhau theo quy định của Bộ Giáo dục và Đào tạo ban hành.', 'Thuộc tính mô tả điểm trung bình môn cả năm của người học.', array['MOET11']::text[], 'diemCn', 'Number', 'Số', null, null),
  ('BG_00142', 'Điểm kiểm tra lại của người học', 'Là kết quả đánh giá lại của một môn học nào đó của người học.', 'Thuộc tính mô tả điểm kiểm tra lại của người học.', array['MOET11']::text[], 'diemKiemTraLai', 'Number', 'Số', null, null),
  ('BG_00143', 'Nhận xét môn học của người học', 'Là nội dung giáo viên bộ môn đánh giá quá trình học tập của người học.', 'Thuộc tính mô tả nhận xét môn học của người học.', array['MOET11']::text[], 'nhanXetMonHoc', 'String', 'Chuỗi ký tự', '200', null),
  ('BG_00144', 'Kết quả đánh giá rèn luyện lại trong hè', 'Là kết quả đánh giá rèn luyện lại sau hè của người học.', 'Thuộc tính mô tả kết quả đánh giá rèn luyện lại sau hè của người học cấp phổ thông.', array['MOET11']::text[], 'kqrlLaiTrongHe', 'String', 'Chuỗi ký tự', '2', null),
  ('BG_00145', 'Kết quả đánh giá học tập lại trong hè', 'Là kết quả học tập sau khi người học đã thực hiện kiểm tra lại các môn không đạt trong năm học.', 'Thuộc tính mô tả kết quả đánh giá học tập lại trong hè của người học cấp phổ thông.', array['MOET11']::text[], 'kqhtLaiTrongHe', 'String', 'Chuỗi ký tự', '2', null),
  ('BG_00146', 'Nội dung kết quả rèn luyện trong hè', 'Là nội dung kết quả đánh giá lại hoặc sau rèn luyện hè được ghi trong học bạ cấp THCS, THPT, GDTX của người học.', 'Thuộc tính mô tả nội dung kết quả rèn luyện trong hè.', array['MOET11']::text[], 'noiDungKqrlTrongHe', 'String', 'Chuỗi ký tự', '500', null),
  ('BG_00147', 'Tổng số tín chỉ tích lũy', 'Là tổng số tín chỉ của các học phần đạt yêu cầu của người học.', 'Thuộc tính mô tả tổng số tín chỉ tích lũy của người học.', array['MOET11']::text[], 'tongSoTinChi', 'Number', 'Số', '3', null),
  ('BG_00148', 'Tên đề tài nghiên cứu của người học', 'Là tên gọi chính thức của đề tài nghiên cứu khoa học của người học.', 'Thuộc tính mô tả tên đề tài nghiên cứu khoa học của người học.', array['MOET12']::text[], 'tenDeTaiNcCuaNh', 'String', 'Chuỗi ký tự', '1000', null),
  ('BG_00149', 'Mã đề tài nghiên cứu của người học', 'Là mã quản lý đề tài nghiên cứu của người học.', 'Thuộc tính thể hiện mã quản lý đề tài nghiên cứu của người học.', array['MOET12']::text[], 'maDeTaiNcCuaNh', 'String', 'Chuỗi ký tự', '50', null),
  ('BG_00150', 'Thời gian bắt đầu đề tài nghiên cứu', 'Là thời điểm bắt đầu thực hiện đề tài nghiên cứu của người học.', 'Thuộc tính ghi nhận thời điểm bắt đầu thực hiện đề tài nghiên cứu của người học.', array['MOET12']::text[], 'tgBatDauDeTaiNcCuaNh', 'Date', 'Ngày tháng', '10', null),
  ('BG_00151', 'Thời gian kết thúc đề tài nghiên cứu', 'Là thời điểm hoàn thành hoặc nghiệm thu đề tài nghiên cứu của người học.', 'Thuộc tính ghi nhận thời điểm hoàn thành hoặc nghiệm thu đề tài nghiên cứu của người học.', array['MOET12']::text[], 'tgKetThucDeTaiNcCuaNh', 'Date', 'Ngày tháng', '10', null),
  ('BG_00152', 'Sản phẩm đề tài nghiên cứu khoa học của người học', 'Là mô tả sản phẩm đề tài nghiên cứu khoa học của người học.', 'Thuộc tính mô tả sản phẩm của đề tài nghiên cứu khoa học của người học.', array['MOET12']::text[], 'sanPhamDeTaiNh', 'String', 'Chuỗi ký tự', '3000', null),
  ('BG_00153', 'Tên người hướng dẫn đề tài', 'Là người chịu trách nhiệm hướng dẫn chuyên môn cho người học thực hiện đề tài', 'Thuộc tính ghi nhận người hướng dẫn chuyên môn cho đề tài nghiên cứu của người học.', array['MOET12']::text[], 'tenNguoiHuongDan', 'String', 'Chuỗi ký tự', '50', null),
  ('BG_00154', 'Chức danh', 'Là chức danh của người hướng dẫn đề tài.', 'Thuộc tính thể hiện chức danh của người hướng dẫn đề tài.', array['MOET12']::text[], 'chucDanhNguoiHuongDan', 'String', 'Chuỗi ký tự', '200', null),
  ('BG_00155', 'Thời gian bắt đầu hướng dẫn đề tài', 'Là thời điểm bắt đầu thực hiện hướng dẫn đề tài nghiên cứu của người học.', 'Thuộc tính ghi nhận thời điểm bắt đầu hướng dẫn đề tài nghiên cứu của người học.', array['MOET12']::text[], 'tgBatDauHdDeTai', 'Date', 'Ngày tháng', '10', null),
  ('BG_00156', 'Thời gian kết thúc hướng dẫn đề tài', 'Là thời điểm kết thúc hướng dẫn đề tài nghiên cứu của người học.', 'Thuộc tính ghi nhận thời điểm kết thúc hướng dẫn đề tài nghiên cứu của người học.', array['MOET12']::text[], 'tgKetThucHdDeTai', 'Date', 'Ngày tháng', '10', null),
  ('BG_00157', 'Đối tượng', 'Là loại người học (Nghiên cứu sinh/Học viên) được hướng dẫn trong hoạt động đào tạo.', 'Thuộc tính mô tả của hoạt động nghiên cứu khoa học của người học.', array['MOET12']::text[], 'doiTuongNhDuocHdNcsHv', 'String', 'Chuỗi ký tự', '100', null),
  ('BG_00158', 'Năm cấp bằng NCS/HV', 'Là năm mà nghiên cứu sinh hoặc học viên được cơ sở đào tạo cấp bằng tốt nghiệp sau khi hoàn thành chương trình đào tạo và bảo vệ thành công luận án/luận văn.', 'Thuộc tính ghi nhận mốc thời gian năm cấp bằng NCS/HV của người học.', array['MOET12']::text[], 'namCapBangNcsHv', 'Date', 'Ngày tháng', '10', null),
  ('BG_00159', 'Tên văn bằng, chứng chỉ', 'Là tên của văn bằng, chứng chỉ.', 'Thuộc tính ghi nhận tên văn bằng, chứng chỉ của người học.', array['MOET13']::text[], 'tenVbcc', 'String', 'Chuỗi ký tự', '50', null),
  ('BG_00160', 'Số hiệu văn bằng, chứng chỉ', 'Là một chuỗi mã số duy nhất được in trực tiếp trên văn bằng/chứng chỉ.', 'Thuộc tính ghi nhận số hiệu văn bằng, chứng chỉ, gắn với hồ sơ, văn bản, giấy tờ của người học.', array['MOET13']::text[], 'soHieuVbcc', 'String', 'Chuỗi ký tự', '20', null),
  ('BG_00161', 'Số quyết định thành lập hội đồng đánh giá (chỉ dùng cho bậc Thạc sĩ, Tiến sĩ)', 'Là số quyết định thành lập hội đồng đánh giá luận văn thạc sĩ/luận án tiến sĩ là văn bản pháp lý do cơ quan có thẩm quyền ban hành, chỉ định các chuyên gia đánh giá công trình nghiên cứu của người học.', 'Thuộc tính ghi nhận số quyết định thành lập hội đồng đánh giá (chỉ dùng cho bậc Thạc sĩ, Tiến sĩ), gắn với hồ sơ, văn bản, giấy tờ của kết quả, quyết định công nhận tốt nghiệp của người học.', array['MOET13']::text[], 'soQdThanhLapHoiDong', 'String', 'Chuỗi ký tự', '50', null),
  ('BG_00162', 'Người học được dự xét tốt nghiệp', 'Là các người học đủ điều kiện dự xét tốt nghiệp theo quy định.', 'Thuộc tính đánh dấu người học được dự xét tốt nghiệp của người học (giá trị có/không).', array['MOET13']::text[], 'isDuXetTotNghiep', 'Boolean', 'Đúng/Sai', '1', null),
  ('BG_00163', 'Loại tốt nghiệp', 'Là hình thức phân loại chất lượng học sinh tốt nghiệp cuối cấp.', 'Thuộc tính đánh dấu loại tốt nghiệp của người học.', array['MOET13']::text[], 'isLoaiTotNghiep', 'Boolean', 'Đúng/Sai', '1', null),
  ('BG_00164', 'Năm tốt nghiệp của người học', 'Là thời gian (năm dương lịch) người học chính thức hoàn thành toàn bộ chương trình giáo dục phổ thông hoặc chương trình đào tạo, đủ điều kiện được công nhận và cấp văn bằng, chứng chỉ theo quy định của cơ sở giáo dục.', 'Thuộc tính mô tả năm tốt nghiệp của người học.', array['MOET13']::text[], 'namTotNghiep', 'Number', 'Số', '4', null),
  ('BG_00165', 'Số quyết định công nhận tốt nghiệp', 'Là số quyết định của văn bản pháp lý do người có thẩm quyền ký ban hành, xác nhận người học đã hoàn thành đủ các điều kiện để được công nhận tốt nghiệp.', 'Thuộc tính ghi nhận số quyết định công nhận tốt nghiệp, gắn với quyết định công nhận tốt nghiệp của người học.', array['MOET13']::text[], 'soQdCnTotNghiep', 'String', 'Chuỗi ký tự', '50', null),
  ('BG_00166', 'Ngày quyết định công nhận tốt nghiệp', 'Là ngày ghi trên văn bản quyết định công nhận tốt nghiệp của người học do cơ quan có thẩm quyền ký ban hành.', 'Thuộc tính mô tả ngày quyết định công nhận tốt nghiệp của người học.', array['MOET13']::text[], 'ngayQdCnTotNghiep', 'String', 'Chuỗi ký tự', '10', 'CDE-TG-001'),
  ('BG_00167', 'Khóa thi tốt nghiệp', 'Là khóa thi tốt nghiệp của người học cấp THPT.', 'Thuộc tính mô tả khóa thi tốt nghiệp THPT của người học.', array['MOET13']::text[], 'khoaThi', 'String', 'Chuỗi ký tự', '50', null),
  ('BG_00168', 'Hội đồng thi tốt nghiệp', 'Là hội đồng thi mà người học tham gia dự thi tốt nghiệp THPT.', 'Thuộc tính mô tả hội đồng thi tốt nghiệp THPT của người học.', array['MOET13']::text[], 'hoiDongThi', 'String', 'Chuỗi ký tự', '150', null),
  ('BG_00169', 'Số vào sổ gốc cấp văn bằng', 'Là một dãy số hoặc chuỗi ký tự duy nhất được ghi trên bản chính của văn bằng/chứng chỉ, đồng thời tương ứng với số thứ tự quản lý được lưu lại trong sổ gốc của cơ sở giáo dục hoặc cơ quan có thẩm quyền cấp phát.', 'Thuộc tính mô tả số vào sổ gốc cấp văn bằng cho các loại bằng cấp của người học.', array['MOET13']::text[], 'soVaoSo', 'String', 'Chuỗi ký tự', '20', null),
  ('BG_00170', 'Xếp loại/hạng tốt nghiệp', 'Là danh mục dùng để đánh giá kết quả Xếp loại/hạng tốt nghiệp của người học tốt nghiệp.', 'Thuộc tính mô tả xếp loại/hạng tốt nghiệp mà người học đã đạt được.', array['MOET13']::text[], 'xepLoai', 'String', 'Chuỗi ký tự', '50', null),
  ('BG_00171', 'Tên đơn vị cấp bằng', 'Là tên chính thức của cơ sở giáo dục, cơ quan quản lý giáo dục được quy định trong các quyết định thành lập mà đang thực hiện cấp văn bằng, chứng chỉ tốt nghiệp cho người học.', 'Thuộc tính ghi nhận tên đơn vị cấp bằng của kết quả, quyết định công nhận tốt nghiệp của người học.', array['MOET13']::text[], 'dvCapBang', 'String', 'Chuỗi ký tự', '250', null),
  ('BG_00172', 'Họ và tên người ký văn bằng', 'Là họ và tên người thực hiện ký số văn bằng.', 'Thuộc tính mô tả họ và tên người ký văn bằng của người học.', array['MOET13']::text[], 'hoTenNguoiKyVb', 'String', 'Chuỗi ký tự', '150', null),
  ('BG_00173', 'Chức danh người ký văn bằng', 'Là chức vụ của người thực hiện ký số văn bằng.', 'Thuộc tính mô tả chức danh người ký văn bằng của người học.', array['MOET13']::text[], 'chucDanhNguoiKyVbcc', 'String', 'Chuỗi ký tự', '150', null),
  ('BG_00174', 'Họ tên người ký văn bằng bản giấy', 'Là họ và tên người thực hiện ký văn bằng giấy.', 'Thuộc tính mô tả họ tên người ký văn bằng bản giấy của người học.', array['MOET13']::text[], 'hoTenNguoiKyVbcc', 'String', 'Chuỗi ký tự', '150', null),
  ('BG_00175', 'Chức danh người ký văn bằng bản giấy', 'Là chức vụ của người thực hiện ký văn bằng giấy.', 'Thuộc tính mô tả chức danh người ký văn bằng bản giấy của người học.', array['MOET13']::text[], 'chucDanhNguoiKyVbcc', 'String', 'Chuỗi ký tự', '150', null),
  ('BG_00176', 'Ngày tạo lập văn bằng số', 'Là ngày thao tác tạo lập văn bằng số.', 'Thuộc tính mô tả ngày tạo lập văn bằng số của người học', array['MOET13']::text[], 'ngayTaoVbcc', 'String', 'Chuỗi ký tự', '10', 'CDE-TG-001'),
  ('BG_00177', 'Ngày cấp bằng của người học', 'Là ngày cấp văn bằng, chứng chỉ của người học.', 'Thuộc tính mô tả ngày cấp bằng của người học.', array['MOET13']::text[], 'ngayCapVbcc', 'String', 'Chuỗi ký tự', '10', 'CDE-TG-001'),
  ('BG_00178', 'Tên quyết định hiệu chỉnh', 'Là tên của quyết định hiệu chỉnh văn bằng, chứng chỉ số.', 'Thuộc tính ghi nhận tên quyết định hiệu chỉnh văn bằng, chứng chỉ của người học.', array['MOET13']::text[], 'qdHieuChinhVbcc', 'String', 'Chuỗi ký tự', '200', null),
  ('BG_00179', 'Số quyết định hiệu chỉnh', 'Là số quyết định ghi trên văn bản hiệu chỉnh văn bằng, chứng chỉ số do cơ quan có thẩm quyền ban hành.', 'Thuộc tính ghi nhận số quyết định hiệu chỉnh văn bằng, chứng chỉ của người học.', array['MOET13']::text[], 'soQdHieuChinhVbcc', 'String', 'Chuỗi ký tự', '50', null),
  ('BG_00180', 'Ngày ban hành quyết định hiệu chỉnh', 'Là ngày ghi trên số quyết định hiệu chỉnh văn bằng, chứng chỉ số.', 'Thuộc tính mô tả ngày ban hành quyết định hiệu chỉnh văn bằng, chứng chỉ của người học.', array['MOET13']::text[], 'ngayQdHieuChinhVbcc', 'String', 'Chuỗi ký tự', '10', 'CDE-TG-001'),
  ('BG_00181', 'Họ tên người ký quyết định hiệu chỉnh', 'Là họ và tên người thực hiện ký quyết định hiệu chỉnh văn bằng, chứng chỉ số.', 'Thuộc tính mô tả họ tên người ký quyết định hiệu chỉnh văn bằng, chứng chỉ của người học.', array['MOET13']::text[], 'hoTenNguoiKy', 'String', 'Chuỗi ký tự', '150', null),
  ('BG_00182', 'Chức danh người ký quyết định hiệu chỉnh', 'Là chức vụ của người thực hiện ký quyết định hiệu chỉnh văn bằng, chứng chỉ số.', 'Thuộc tính mô tả chức danh người ký quyết định hiệu chỉnh văn bằng, chứng chỉ của người học.', array['MOET13']::text[], 'chucDanhNguoiKyHc', 'String', 'Chuỗi ký tự', '150', null),
  ('BG_00183', 'Lý do hiệu chỉnh văn bằng', 'Là nội dung lý do cần hiệu chỉnh văn bằng, chứng chỉ số.', 'Thuộc tính mô tả lý do hiệu chỉnh văn bằng, chứng chỉ của người học.', array['MOET13']::text[], 'lyDoHieuChinh', 'String', 'Chuỗi ký tự', '2000', null),
  ('BG_00184', 'Nội dung quyết định hiệu chỉnh văn bằng', 'Là nội dung của quyết định hiệu chỉnh văn bằng, chứng chỉ số.', 'Thuộc tính mô tả nội dung quyết định hiệu chỉnh văn bằng, chứng chỉ của người học.', array['MOET13']::text[], 'ndQdHieuChinh', 'String', 'Chuỗi ký tự', '2000', null),
  ('BG_00185', 'Thông tin phụ lục hiệu chỉnh VBCC', 'Là phụ lục hiệu chỉnh văn bằng, chứng chỉ số.', 'Thuộc tính mô tả thông tin phụ lục hiệu chỉnh văn bằng, chứng chỉ của người học.', array['MOET13']::text[], 'phuLucHieuChinh', 'String', 'Chuỗi ký tự', '255', null),
  ('BG_00186', 'Thông tin được hiệu chỉnh', 'Là danh sách các thông tin được hiệu chỉnh lại trong văn bằng, chứng chỉ số.', 'Thuộc tính mô tả thông tin được hiệu chỉnh văn bằng, chứng chỉ của người học.', array['MOET13']::text[], 'ttPhuLucHieuChinh', 'String', 'Chuỗi ký tự', '255', null),
  ('BG_00187', 'Mã đơn vị cấp bằng', 'Là mã định danh duy nhất của cơ sở giáo dục, đào tạo, hoặc cơ quan nhà nước có thẩm quyền cấp văn bằng, chứng chỉ tốt nghiệp cho người học.', 'Thuộc tính mô tả mã đơn vị cấp văn bằng, chứng chỉ của người học.', array['MOET13']::text[], 'maDonViCapBang', 'String', 'Chuỗi ký tự', '20', null),
  ('BG_00188', 'Điểm văn thi tốt nghiệp THPT', 'Là kết quả điểm thi môn Ngữ văn của học sinh trong kỳ thi xét tốt nghiệp THPT.', 'Thuộc tính định lượng phản ánh điểm văn thi tốt nghiệp THPT của người học.', array['MOET13']::text[], 'diemVan', 'Decimal', 'Số thập phân', null, null),
  ('BG_00189', 'Điểm toán thi tốt nghiệp THPT', 'Là kết quả điểm thi môn Toán học của học sinh trong kỳ thi xét tốt nghiệp THPT.', 'Thuộc tính định lượng phản ánh điểm toán thi tốt nghiệp THPT của người học.', array['MOET13']::text[], 'diemToan', 'Decimal', 'Số thập phân', null, null),
  ('BG_00190', 'Điểm ngoại ngữ thi tốt nghiệp THPT', 'Là kết quả điểm thi môn Ngoại ngữ của học sinh trong kỳ thi xét tốt nghiệp THPT.', 'Thuộc tính mô tả điểm ngoại ngữ thi tốt nghiệp THPT của người học.', array['MOET13']::text[], 'diemNgoaiNguThiTnThpt', 'Number', 'Số', null, null),
  ('BG_00191', 'Điểm thi môn tổ hợp', 'Là tổng điểm của 3 môn thi thành phần theo quy định của các trường, kết hợp với điểm ưu tiên (nếu có)', 'Thuộc tính định lượng phản ánh điểm thi môn tổ hợp của người học.', array['MOET13']::text[], 'diemThiMonToHop', 'Decimal', 'Số thập phân', null, null),
  ('BG_00192', 'Thí sinh tự do', 'Là những người học đã hoàn thành chương trình trung học phổ thông (THPT) hoặc giáo dục thường xuyên (GDTX) nhưng chưa tốt nghiệp ở các năm trước, hoặc người học đã tốt nghiệp THPT/trung cấp muốn dự thi lại để lấy kết quả xét tuyển sinh đại học năm học mới.', 'Thuộc tính đánh dấu người học là thí sinh tự do tham gia thi tốt nghiệp (giá trị có/không).', array['MOET13']::text[], 'isThiSinhTuDo', 'Boolean', 'Đúng/Sai', '1', null),
  ('BG_00193', 'Tốt nghiệp', 'Là người học đã đủ điều kiện tốt nghiệp THPT theo quy chế của cơ quan có thẩm quyền ban hành.', 'Thuộc tính đánh dấu người học đủ điều kiện tốt nghiệp THPT của người học (giá trị có/không).', array['MOET13']::text[], 'isTotNghiep', 'Boolean', 'Đúng/Sai', '1', null),
  ('BG_00194', 'Miễn thi', 'Là quyền lợi không phải tham dự một hoặc nhiều môn thi trong kỳ thi (thường là tốt nghiệp THPT) nhưng vẫn được công nhận kết quả theo quy định.', 'Thuộc tính đánh dấu miễn thi của người học (giá trị có/không).', array['MOET13']::text[], 'isMien', 'Boolean', 'Đúng/Sai', '1', null),
  ('BG_00195', 'Đặc cách', 'Là người học được công nhận tốt nghiệp hoặc hoàn thành chương trình học theo diện đặc cách theo quy định.', 'Thuộc tính đánh dấu người học là đối tượng được đặc cách trong kỳ thi tốt nghiệp THPT.', array['MOET13']::text[], 'isDacCach', 'Boolean', 'Đúng/Sai', '1', null),
  ('BG_00196', 'Tên người hướng dẫn chính', 'Là họ tên cán bộ/nhà giáo chịu trách nhiệm chính trong việc hướng dẫn luận văn hoặc luận án của người học', 'Thuộc tính ghi nhận tên người hướng dẫn chính cho luận văn/luận án của người học.', array['MOET13']::text[], 'tenNguoiHdChinh', 'String', 'Chuỗi ký tự', '50', null),
  ('BG_00197', 'Học hàm người hướng dẫn chính', 'Là học hàm của cán bộ/nhà giáo hướng dẫn chính cho người học.', 'Thuộc tính phân loại học hàm người hướng dẫn chính cho luận văn/luận án người học.', array['MOET13']::text[], 'hocHamNguoiHuongDanChinh', 'Enumeration', 'Danh mục liệt kê', null, null),
  ('BG_00198', 'Cơ quan công tác người hướng dẫn chính', 'Là đơn vị nơi cán bộ/nhà giáo hướng dẫn chính đang công tác.', 'Thuộc tính mô tả cơ quan công tác người hướng dẫn chính cho luận văn/luận án của người học.', array['MOET13']::text[], 'coQuanNguoiHdChinh', 'String', 'Chuỗi ký tự', '100', null),
  ('BG_00199', 'Tên người hướng dẫn phụ', 'Là họ tên cán bộ/nhà giáo tham gia hỗ trợ hướng dẫn người học trong quá trình thực hiện luận văn/luận án.', 'Thuộc tính ghi nhận tên người hướng dẫn phụ cho luận văn/luận án người học.', array['MOET13']::text[], 'tenNguoiHdPhu', 'String', 'Chuỗi ký tự', '50', null),
  ('BG_00200', 'Học hàm người hướng dẫn phụ', 'Là học hàm của cán bộ/nhà giáo hướng dẫn phụ.', 'Thuộc tính phân loại học hàm người hướng dẫn phụ cho luận văn/luận án người học.', array['MOET13']::text[], 'hocHamNguoiHuongDanPhu', 'Enumeration', 'Danh mục liệt kê', null, null),
  ('BG_00201', 'Cơ quan công tác người hướng dẫn phụ', 'Là đơn vị nơi cán bộ/nhà giáo hướng dẫn phụ đang công tác.', 'Thuộc tính mô tả cơ quan công tác người hướng dẫn phụ cho luận văn/luận án người học.', array['MOET13']::text[], 'coQuanNguoiHdPhu', 'String', 'Chuỗi ký tự', '100', null),
  ('BG_00202', 'Số quyết định thành lập Hội đồng bảo vệ cấp cơ sở', 'Là số quyết định được xác định trong văn bản thành lập Hội đồng bảo vệ cấp cơ sở do cơ quan có thẩm quyền ban hành.', 'Thuộc tính ghi nhận số quyết định thành lập Hội đồng bảo vệ cấp cơ sở.', array['MOET13']::text[], 'soQdThanhLapHdCapCoSo', 'String', 'Chuỗi ký tự', '50', null),
  ('BG_00203', 'Ngày quyết định thành lập Hội đồng bảo vệ cấp cơ sở', 'Là ngày ghi trên số quyết địnhthành lập Hội đồng bảo vệ cấp cơ sở do cơ quan có thẩm quyền ban hành.', 'Thuộc tính ghi nhận mốc thời gian ngày quyết định thành lập Hội đồng bảo vệ cấp cơ sở sử dụng', array['MOET13']::text[], 'ngayQdThanhLapHdCapCoSo', 'Date', 'Ngày tháng', '10', 'CDE-TG-001'),
  ('BG_00204', 'Số quyết định thành lập Hội đồng bảo vệ cấp trường', 'Là số quyết định được xác định trong văn bản thành lập Hội đồng bảo vệ cấp trường do cơ quan có thẩm quyền ban hành.', 'Thuộc tính ghi nhận số quyết định thành lập Hội đồng bảo vệ cấp trường.', array['MOET13']::text[], 'soQdThanhLapHdCapTruong', 'String', 'Chuỗi ký tự', '50', null),
  ('BG_00205', 'Ngày quyết định thành lập Hội đồng bảo vệ cấp trường', 'Là ngày ghi trên số quyết định thành lập Hội đồng bảo vệ cấp trường do cơ quan có thẩm quyền ban hành.', 'Thuộc tính ghi nhận mốc thời gian ngày quyết định thành lập Hội đồng bảo vệ cấp trường.', array['MOET13']::text[], 'ngayQdThanhLapHdCapTruong', 'Date', 'Ngày tháng', '10', 'CDE-TG-001'),
  ('BG_00206', 'Số quyết định công nhận học vị tiến sĩ/ thạc sĩ', 'Là số quyết định được xác định trong văn bản công nhận học vị tiến sĩ/ thạc sĩ do cơ quan có thẩm quyền ban hành.', 'Thuộc tính ghi nhận số quyết định công nhận học vị tiến sĩ/ thạc sĩ của người học.', array['MOET13']::text[], 'soQdCongNhanHocVi', 'String', 'Chuỗi ký tự', '50', null),
  ('BG_00207', 'Ngày quyết định học vị tiến sĩ/ thạc sĩ', 'Là ngày ghi trên số quyết định công nhận học vị tiến sĩ/ thạc sĩ do cơ quan có thẩm quyền ban hành.', 'Thuộc tính ghi nhận mốc thời gian ngày quyết định học vị tiến sĩ/ thạc sĩ của kết quả, quyết định công nhận tốt nghiệp của người học.', array['MOET13']::text[], 'ngayQdCongNhanHocVi', 'Date', 'Ngày tháng', '10', 'CDE-TG-001'),
  ('BG_00208', 'Ngày bảo vệ luận văn/luận án của người học', 'Là thời điểm người học thực hiện buổi bảo vệ luận văn/luận án trước hội đồng đánh giá.', 'Thuộc tính ghi nhận mốc thời gian ngày bảo vệ luận văn/luận án của người học.', array['MOET13']::text[], 'ngayBaoVeLuanVanNh', 'Date', 'Ngày tháng', '10', 'CDE-TG-001'),
  ('BG_00209', 'Có cập nhật khen thưởng', 'Là thông tin liên quan đến việc người học có được cập nhật các khen thưởng trong quá trình học tập và rèn luyện.', 'Thuộc tính mô tả có cập nhật khen thưởng của khen thưởng, kỷ luật của người học.', array['MOET14']::text[], 'capNhatKhenThuong', 'String', 'Chuỗi ký tự', '255', null),
  ('BG_00210', 'Loại khen thưởng người học', 'Là dùng để xác định loại khen thưởng người học theo quy định trong hệ thống quản lý giáo dục quốc dân.', 'Thuộc tính phân loại loại khen thưởng của người học.', array['MOET14']::text[], 'loaiKhenThuongNh', 'Enumeration', 'Danh mục liệt kê', null, null),
  ('BG_00211', 'Nội dung khen thưởng người học', 'Là thông tin liên quan đến nội dung khen thưởng của người học trong quá trình học tập và rèn luyện.', 'Thuộc tính mô tả nội dung khen thưởng của người học.', array['MOET14']::text[], 'noiDungKtNh', 'String', 'Chuỗi ký tự', '255', null),
  ('BG_00212', 'Loại bạo lực học đường', 'Là dùng để xác định về loại bạo lực học đường xảy ra liên quan đến người học.', 'Thuộc tính phân loại loại bạo lực học đường.', array['MOET14']::text[], 'loaiBaoLucHocDuong', 'Enumeration', 'Danh mục liệt kê', null, null),
  ('BG_00213', 'Đối tượng gây bạo lực', 'Là thông tin liên quan đến đối tương gây bạo lực học đường xảy ra liên quan đến người học.', 'Thuộc tính mô tả đối tượng gây bạo lực trong học đường.', array['MOET14']::text[], 'doiTuong', 'String', 'Chuỗi ký tự', '25', null),
  ('BG_00214', 'Hình thức bạo lực', 'Là thông tin ghi nhận về hình thức bạo lực học đường xảy ra liên quan đến người học.', 'Thuộc tính mô tả hình thức bạo lực.', array['MOET14']::text[], 'hinhThucBaoLuc', 'String', 'Chuỗi ký tự', '25', null),
  ('BG_00215', 'Địa điểm xảy ra bạo lực', 'Là thông tin ghi nhận về địa điểm bạo lực học đường xảy ra liên quan đến người học.', 'Thuộc tính mô tả địa điểm xảy ra bạo lực.', array['MOET14']::text[], 'diaDiemXayRaBaoLuc', 'String', 'Chuỗi ký tự', '25', null),
  ('BG_00216', 'Thời lượng', 'Là thông tin ghi nhận về thời lượng bạo lực học đường xảy ra liên quan đến người học.', 'Thuộc tính mô tả thời lượng diễn ra bạo lực.', array['MOET14']::text[], 'thoiLuong', 'String', 'Chuỗi ký tự', '25', null),
  ('BG_00217', 'Kết quả xử lý', 'Là thông tin quản lý liên quan đến ''kết quả xử lý'' bạo lực học đường xảy ra liên quan đến người học.', 'Thuộc tính mô tả kết quả xử lý hành vi bạo lực học đường của người học.', array['MOET14']::text[], 'ketQuaXuLy', 'String', 'Chuỗi ký tự', '255', null),
  ('BG_00218', 'Kỷ luật', 'Là nội dung đánh giá rèn luyện, giáo dục giúp học sinh tiến bộ thay vì chỉ trừng phạt. Các hình thức kỷ luật được áp dụng mang tính giáo dục, bao gồm phê bình và yêu cầu viết bản kiểm điểm, tôn trọng danh dự học sinh.', 'Thuộc tính mô tả kỷ luật của khen thưởng, kỷ luật của người học.', array['MOET14']::text[], 'kyLuat', 'String', 'Chuỗi ký tự', '255', null),
  ('BG_00219', 'Nội dung khen thưởng đột xuất người học', 'Là nội dung mà cơ sở giáo dục nhận xét các người học có thành tích đột xuất trong năm học.', 'Thuộc tính mô tả nội dung khen thưởng đột xuất của người học.', array['MOET14']::text[], 'noiDungKhenThuongDotXuat', 'String', 'Chuỗi ký tự', '500', null),
  ('BG_00220', 'Cấp quyết định khen thưởng người học', 'Là các cấp quản lý giáo dục hoặc tổ chức xã hội có thẩm quyền khen thưởng người học.', 'Thuộc tính mô tả cấp quyết định khen thưởng của người học.', array['MOET14']::text[], 'capQuyetDinhKhenThuongNh', 'String', 'Chuỗi ký tự', '200', null),
  ('BG_00221', 'Số quyết định khen thưởng người học', 'Là số quyết định được xác định trong quyết định khen thưởng.', 'Thuộc tính ghi nhận số quyết định khen thưởng người học.', array['MOET14']::text[], 'soQuyetDinhKhenThuongNh', 'String', 'Chuỗi ký tự', '50', null),
  ('BG_00222', 'Ngày quyết định khen thưởng người học', 'Là ngày quyết định được xác định trong quyết định khen thưởng.', 'Thuộc tính ghi nhận mốc thời gian ngày quyết định khen thưởng người học.', array['MOET14']::text[], 'ngayQdKhenThuongNh', 'Date', 'Ngày tháng', '10', 'CDE-TG-001'),
  ('BG_00223', 'Năm khen thưởng người học', 'Là danh mục năm ban hành quyết định khen thưởng...', 'Thuộc tính năm khen thưởng người học.', array['MOET14']::text[], 'namKhenThuongNh', 'Integer', 'Số nguyên', null, null),
  ('BG_00224', 'Loại kỷ luật người học', 'Là hình thức xử lý kỷ luật áp dụng đối với người học khi có hành vi vi phạm quy định trong quá trình học tập.', 'Thuộc tính phân loại loại kỷ luật của người học.', array['MOET14']::text[], 'loaiKyLuatNh', 'Enumeration', 'Danh mục liệt kê', null, null),
  ('BG_00225', 'Nội dung kỷ luật người học', 'Là nội dung mô tả hành vi vi phạm hoặc nguyên nhân dẫn đến việc người học bị xử lý kỷ luật', 'Thuộc tính mô tả nội dung kỷ luật người học.', array['MOET14']::text[], 'lyDoKyLuatNh', 'String', 'Chuỗi ký tự', '500', null),
  ('BG_00226', 'Cấp quyết định kỷ luật người học', 'Là người đứng đầu cơ quan, tổ chức có thẩm quyền ký ban hành văn bản quyết định kỷ luật', 'Thuộc tính mô tả cấp quyết định kỷ luật người học.', array['MOET14']::text[], 'capQuyetDinhKyLuatNh', 'String', 'Chuỗi ký tự', '200', null),
  ('BG_00227', 'Số quyết định kỷ luật người học', 'Là số quyết định được xác định trong quyết định kỷ luật', 'Thuộc tính ghi nhận số quyết định kỷ luật người học.', array['MOET14']::text[], 'soQuyetDinhKyLuatNh', 'String', 'Chuỗi ký tự', '50', null),
  ('BG_00228', 'Ngày quyết định kỷ luật người học', 'Là ngày quyết định được xác định trong quyết định kỷ luật', 'Thuộc tính ghi nhận mốc thời gian ngày quyết định kỷ luật của người học.', array['MOET14']::text[], 'ngayQdKyLuatNh', 'Date', 'Ngày tháng', '10', 'CDE-TG-001'),
  ('BG_00229', 'Năm kỷ luật người học', 'Là năm ban hành quyết định kỷ luật', 'Thuộc tính năm kỷ luật người học.', array['MOET14']::text[], 'namKyLuatNh', 'Integer', 'Số nguyên', null, null),
  ('BG_00230', 'Đơn vị tuyển dụng người học', 'Là tên cơ quan, doanh nghiệp, tổ chức hoặc cá nhân sử dụng lao động đã tuyển dụng người học vào làm việc theo thỏa thuận hoặc hợp đồng lao động.', 'Thuộc tính mô tả đơn vị tuyển dụng người học sau khi đã tốt nghiệp.', array['MOET15']::text[], 'donViTuyenDung', 'String', 'Chuỗi ký tự', '50', null),
  ('BG_00231', 'Hình thức tuyển dụng của người học', 'Là phương thức mà người học được tuyển vào làm việc tại đơn vị sử dụng lao động.', 'Thuộc tính mô tả hình thức tuyển dụng của người học.', array['MOET15']::text[], 'hinhThucTuyenDung', 'String', 'Chuỗi ký tự', '20', null),
  ('BG_00232', 'Thời gian tuyển dụng của người học', 'Là thời điểm hoặc khoảng thời gian người học chính thức được tuyển dụng và bắt đầu làm việc tại đơn vị sử dụng lao động', 'Thuộc tính ghi nhận mốc thời gian thời gian tuyển dụng của người học.', array['MOET15']::text[], 'thoiGianTuyenDung', 'Date', 'Ngày tháng', '10', null),
  ('BG_00233', 'Vị trí việc làm của người học', 'Là chức danh công việc, vai trò, mà người học đảm nhận ở đơn vị tuyển dụng.', 'Thuộc tính mô tả vị trí việc làm của người học.', array['MOET15']::text[], 'viTriViecLam', 'String', 'Chuỗi ký tự', '50', null),
  ('BG_00234', 'Học bạ số', 'Là dữ liệu điện tử có giá trị pháp lý, ghi nhận có hệ thống quá trình học tập, kết quả học tập, kết quả rèn luyện, nhận xét, đánh giá và các thông tin liên quan đến người học trong quá trình học tập tại cơ sở giáo dục.', 'Dự thảo 2 Thông tư của Bộ Giáo dục và Đào tạo về Quy định về quản lý và sử dụng học bạ số trong các cơ sở giáo dục phổ thông và cơ sở giáo dục thường xuyên.', array['MOET16']::text[], 'hocBa', 'Object', 'Đối tượng', null, null),
  ('BG_00235', 'Văn bằng, chứng chỉ số', 'Là văn bằng, chứng chỉ được cấp dưới dạng kỹ thuật số từ cơ sở dữ liệu về văn bằng, chứng chỉ của Bộ Giáo dục và Đào tạo hoặc của cơ quan cấp văn bằng, chứng chỉ nếu được phân cấp (sau đây gọi chung là cơ sở dữ liệu về văn bằng, chứng chỉ).', 'Thông tư số 10/2026/TT-BGDĐT của Bộ Giáo dục và Đào tạo ban hành ngày 26/02/2026 về Ban hành quy chế văn bằng, chứng chỉ của hệ thống giáo dục quốc dân.', array['MOET16']::text[], 'vanBangChungChi', 'Object', 'Đối tượng', null, null),
  ('BG_00236', 'Mã định danh học bạ', 'Là một số duy nhất UUID (Universal Unique Identifier – Mã số định danh duy nhất) có độ dài 32 ký tự chữ và 4 ký tự gạch ngang. Ví dụ: 123e4567-e89b-42d3a456-556642440000.', 'Trường dữ liệu định danh dùng để nhận diện duy nhất người học; phục vụ tra cứu, tham chiếu và liên thông dữ liệu giữa các hệ thống quản lý giáo dục.', array['MOET16']::text[], 'maDinhDanhHocBa', 'String', 'Chuỗi ký tự', '36', null),
  ('BG_00237', 'Mã định danh văn bằng, chứng chỉ', 'Là mã định danh duy nhất của một văn bằng, chứng chỉ được cơ sở đào tạo ban hành hoặc cấp phát để phục vụ việc quản lý, trao đổi và liên thông dữ liệu về văn bằng, chứng chỉ.', 'Trường dữ liệu định danh văn bằng, chứng chỉ của người học; phục vụ tra cứu, tham chiếu và liên thông dữ liệu giữa các hệ thống quản lý giáo dục.', array['MOET16']::text[], 'maDinhDanhVbcc', 'String', 'Chuỗi ký tự', '36', null),
  ('BG_00238', 'Họ và tên cán bộ/nhà giáo', 'Là họ và tên cán bộ/nhà giáo', 'Thuộc tính mô tả họ và tên của nhà giáo, cán bộ quản lý giáo dục.', array['MOET18']::text[], 'hoVaTenDoiNgu', 'String', 'Chuỗi ký tự', '200', null),
  ('BG_00239', 'Ngày sinh của cán bộ/nhà giáo', 'Là ngày tháng năm sinh của cán bộ/nhà giáo được quản lý trong hệ thống quản lý giáo dục quốc dân.', 'Thuộc tính ghi nhận mốc thời gian ngày sinh của nhà giáo và cán bộ quản lý giáo dục.', array['MOET18']::text[], 'ngaySinhDoiNgu', 'Date', 'Ngày tháng', '10', 'CDE-TG-001'),
  ('BG_00240', 'Mã định danh cán bộ/nhà giáo', 'Là mã định danh duy nhất của một cán bộ, nhà giáo trong hệ thống quản lý giáo dục, được cơ quan quản lý giáo dục ban hành hoặc cấp phát để phục vụ việc quản lý, trao đổi và liên thông dữ liệu về cán bộ, nhà giáo.', 'Trường dữ liệu định danh dùng để nhận diện duy nhất nhà giáo, cán bộ quản lý giáo dục; phục vụ tra cứu, tham chiếu và liên thông dữ liệu giữa các hệ thống quản lý giáo dục.', array['MOET18']::text[], 'maDinhDanhDn', 'String', 'Chuỗi ký tự', '50', null),
  ('BG_00241', 'Nơi cấp căn cước của cán bộ/nhà giáo', 'Là nơi cấp căn cước của cán bộ/nhà giáo được quản lý trong hệ thống quản lý giáo dục quốc dân.', 'Thuộc tính mô tả nơi cấp căn cước của nhà giáo, cán bộ quản lý giáo dục. sử dụng', array['MOET18']::text[], 'noiCapCanCuocDn', 'Enumeration', 'Danh mục liệt kê', null, null),
  ('BG_00242', 'Ngày cấp căn cước của cán bộ/nhà giáo', 'Là ngày cấp số định danh cá nhân của cán bộ/nhà giáo được quản lý trong hệ thống quản lý giáo dục quốc dân.', 'Thuộc tính ghi nhận mốc thời gian ngày cấp căn cước của nhà giáo, cán bộ quản lý giáo dục.', array['MOET18']::text[], 'ngayCapCanCuocDn', 'Date', 'Ngày tháng', '10', 'CDE-TG-001'),
  ('BG_00243', 'Số điện thoại của cán bộ/nhà giáo', 'Là ''số điện thoại'' của cán bộ/nhà giáo dùng để liên lạc với người đó trong trường hợp cần thiết.', 'Thuộc tính mô tả số điện thoại của cán bộ/nhà giáo.', array['MOET18']::text[], 'soDienThoaiDn', 'String', 'Chuỗi ký tự', '50', 'CDE-LL-001'),
  ('BG_00244', 'Tỉnh/Thành phố nơi thường trú của cán bộ/nhà giáo', 'Là địa chỉ hành chính xác định tỉnh/ thành phố nơi thường trú của người học hoặc cán bộ/nhà giáo được quản lý trong hệ thống quản lý giáo dục quốc dân', 'Thuộc tính phân loại Tỉnh/Thành phố nơi thường trú của cán bộ nhà giáo theo Quyết định số: 19/2025/QĐ-TTg: Ban hành bảng danh mục và mã số các đơn vị hành chính Việt Nam; phục vụ thống kê và báo cáo trong quản lý giáo dục.', array['MOET18']::text[], 'tinhTpNoiThuongTruDn', 'Enumeration', 'Danh mục liệt kê', null, 'CDE-DC-001'),
  ('BG_00245', 'Xã/Phường/Đặc khu nơi thường trú của cán bộ/nhà giáo', 'Là thông tin chỉ địa giới hành chính (xã/phường) nơi thường trú của cá bộ nhà giáo', 'Thuộc tính phân loại Xã/Phường/Đặc khu nơi thường trú của cán bộ/nhà giáo theo Quyết định số: 19/2025/QĐ-TTg: Ban hành bảng danh sử dụng mục và mã số các đơn vị hành chính Việt Nam; phục vụ thống kê và báo cáo trong quản lý giáo dục.', array['MOET18']::text[], 'xaPhuongNoiThuongTruDn', 'Enumeration', 'Danh mục liệt kê', null, 'CDE-DC-003'),
  ('BG_00246', 'Địa chỉ chi tiết nơi thường trú của cán bộ/nhà giáo', 'Là địa chỉ hành chính chi tiết như số nhà, đường, tổ/thôn xóm... nơi thường trú của cán bộ/nhà giáo được quản lý trong hệ thống quản lý giáo dục quốc dân.', 'Thuộc tính mô tả thông tin địa chỉ, vị trí hành chính của nhà giáo, cán bộ quản lý giáo dục.', array['MOET18']::text[], 'diaChiChiTietNoiThuongTruDn', 'String', 'Chuỗi ký tự', '500', null),
  ('BG_00247', 'Tỉnh/Thành phố nơi sinh của cán bộ/nhà giáo', 'Là địa chỉ hành chính xác định tỉnh/ thành phố nơi sinh của cán bộ/nhà giáo được quản lý trong hệ thống quản lý giáo dục quốc dân.', 'Thuộc tính phân loại Tỉnh/Thành phố nơi sinh của cán bộ/nhà giáo theo Quyết định số: 19/2025/QĐTTg: Ban hành bảng danh mục và mã số các đơn vị hành chính Việt Nam; phục vụ thống kê và báo cáo trong quản lý giáo dục.', array['MOET18']::text[], 'tinhTpNoiSinhDn', 'Enumeration', 'Danh mục liệt kê', null, 'CDE-DC-001'),
  ('BG_00248', 'Xã/Phường/Đặc khu nơi sinh của cán bộ/nhà giáo', 'Là địa chỉ hành chính xác định Xã/Phường/Đặc khu nơi sinh của cán bộ/nhà giáo được quản lý trong hệ thống quản lý giáo dục quốc dân.', 'Thuộc tính phân loại Xã/Phường/Đặc khu nơi sinh của cán bộ/nhà giáo theo Quyết định số: 19/2025/QĐ-TTg: Ban hành bảng danh mục và mã số các đơn vị hành chính sử dụng Việt Nam; phục vụ thống kê và báo cáo trong quản lý giáo dục.', array['MOET18']::text[], 'xaPhuongNoiSinhDn', 'Enumeration', 'Danh mục liệt kê', null, 'CDE-DC-003'),
  ('BG_00249', 'Địa chỉ chi tiết nơi sinh của cán bộ/nhà giáo', 'Là địa chỉ hành chính chi tiết như số nhà, đường, tổ/thôn xóm, bệnh viện, trạm xá... nơi sinh của cán bộ/nhà giáo được quản lý trong hệ thống quản lý giáo dục quốc dân.', 'Thuộc tính mô tả thông tin địa chỉ, vị trí hành chính nơi sinh của nhà giáo, cán bộ quản lý giáo dục.', array['MOET18']::text[], 'diaChiChiTietNoiSinhDn', 'String', 'Chuỗi ký tự', '500', null),
  ('BG_00250', 'Tỉnh/Thành phố quê quán của cán bộ/nhà giáo', 'Là thông tin địa chỉ hành chính xác định tỉnh/ thành phố quê quán của cán bộ/nhà giáo được quản lý trong hệ thống quản lý giáo dục quốc dân.', 'Thuộc tính phân loại Tỉnh/Thành phố quê quán của cán bộ/nhà giáo theo Quyết định số: 19/2025/QĐTTg: Ban hành bảng danh mục và mã số các đơn vị hành chính Việt Nam; phục vụ thống kê và báo cáo trong quản lý giáo dục.', array['MOET18']::text[], 'tinhTpQueQuanDn', 'Enumeration', 'Danh mục liệt kê', null, 'CDE-DC-001'),
  ('BG_00251', 'Xã/Phường/Đặc khu quê quán của cán bộ/nhà giáo', 'Là thông tin địa chỉ hành chính xác định xã/phường/đặc khu quê quán của cán bộ/nhà giáo được quản lý trong hệ thống quản lý giáo dục quốc dân.', 'Thuộc tính phân loại Xã/Phường/Đặc khu quê quán của cán bộ/nhà giáo theo Quyết định số: 19/2025/QĐ-TTg: Ban hành bảng danh mục và mã số các đơn vị hành chính Việt Nam; phục vụ thống kê và báo cáo sử dụng trong quản lý giáo dục.', array['MOET18']::text[], 'xaPhuongQueQuanDn', 'Enumeration', 'Danh mục liệt kê', null, 'CDE-DC-003'),
  ('BG_00252', 'Địa chỉ chi tiết quê quán của cán bộ nhà giáo', 'Là thông tin địa chỉ hành chính chi tiết như số nhà, đường, tổ/thôn xóm... quê quán của cán bộ/nhà giáo được quản lý trong hệ thống quản lý giáo dục quốc dân.', 'Thuộc tính mô tả thông tin địa chỉ chi tiết, vị trí hành chính quê quán của nhà giáo, cán bộ quản lý giáo dục.', array['MOET18']::text[], 'diaChiChiTietQueQuanDn', 'String', 'Chuỗi ký tự', '500', null),
  ('BG_00253', 'Tỉnh/Thành phố chỗ ở hiện nay của cám bộ/nhà giáo', 'Là thông tin địa chỉ hành chính xác định tỉnh/ thành phố chỗ ở hiện nay của cán bộ/nhà giáo được quản lý trong hệ thống quản lý giáo dục quốc dân.', 'Thuộc tính phân loại Tỉnh/Thành phố chỗ ở hiện nay của cán bộ/nhà giáo theo Quyết định số: 19/2025/QĐ-TTg: Ban hành bảng danh mục và mã số các đơn vị hành chính Việt Nam; phục vụ thống kê và báo cáo trong quản lý giáo dục.', array['MOET18']::text[], 'tinhTpChoOHienNayDn', 'Enumeration', 'Danh mục liệt kê', null, 'CDE-DC-001'),
  ('BG_00254', 'Xã/Phường/Đặc khu chỗ ở hiện nay của cán bộ/nhà giáo', 'Là thông tin địa chỉ hành chính xác định xã/phường/đặc khu chỗ ở hiện nay của cán bộ/nhà giáo được quản lý trong hệ thống quản lý giáo dục quốc dân.', 'Thuộc tính phân loại Xã/Phường/Đặc khu chỗ ở hiện nay của cán bộ/nhà giáo theo Quyết định số: 19/2025/QĐ-TTg: Ban hành bảng danh mục và mã số các đơn vị hành chính Việt Nam; phục vụ thống kê và báo cáo trong quản lý giáo dục.', array['MOET18']::text[], 'xaPhuongChoOHienNayDn', 'Enumeration', 'Danh mục liệt kê', null, 'CDE-DC-003'),
  ('BG_00255', 'Địa chỉ chi tiết chỗ ở hiện nay của cán bộ/nhà giáo', 'Là thông tin địa chỉ hành chính chi tiết như số nhà, đường, tổ/thôn xóm... chỗ ở hiện nay của cán bộ/nhà giáo được quản lý trong hệ thống quản lý giáo dục quốc dân.', 'Thuộc tính mô tả thông tin địa chỉ chi tiết, vị trí hành chính chỗ ở hiện nay của cán bộ/nhà giáo quản lý giáo dục.', array['MOET18']::text[], 'diaChiChiTietChoOHienNayDn', 'String', 'Chuỗi ký tự', '500', null),
  ('BG_00256', 'Trạng thái cán bộ/nhà giáo', 'Là trạng thái để phân loại tình trạng công tác hiện tại của cán bộ/nhà giáo như đang làm việc, nghỉ thai sản, đi học, biệt phái, hoặc đã nghỉ hưu.', 'Thuộc tính phân loại trạng thái của nhà giáo, cán bộ quản lý giáo dục; chuẩn hóa danh mục, phục vụ thống kê và báo cáo trong quản lý giáo dục.', array['MOET18']::text[], 'trangThaiDn', 'Enumeration', 'Danh mục liệt kê', null, null),
  ('BG_00257', 'Email cán bộ/nhà giáo', 'Là địa chỉ hòm thư điện tử của cán bộ/nhà giáo', 'Thuộc tính mô tả email của nhà giáo, cán bộ quản lý giáo dục.', array['MOET18']::text[], 'emailDn', 'String', 'Chuỗi ký tự', '255', 'CDE-LL-002'),
  ('BG_00258', 'Đảng viên', 'Là cán bộ/nhà giáo được kết nạp và sinh hoạt trong Đảng.', 'Thuộc tính phân loại đảng viên của nhà giáo, cán bộ quản lý giáo dục; chuẩn hóa danh mục, phục vụ thống kê và báo cáo trong quản lý giáo dục.', array['MOET18']::text[], 'dangVien', 'Enumeration', 'Danh mục liệt kê', null, null),
  ('BG_00259', 'Thông tin ký số của cán bộ/nhà giáo', 'Là thông tin chữ ký điện tử của cán bộ/nhà giáo được sử dụng để xác nhận, phê duyệt nội dung học tập trên học bạ số hoặc phát hành học bạ số, văn bằng số cho người học theo vai trò, thẩm quyền và trách nhiệm được phân công. Cấu trúc bao gồm: Chữ ký số (Signature): Thẻ gốc biểu diễn thông tin chữ ký, có thuộc tính "id " là số định danh cá nhân. Signature/SignedInfo: Dữ liệu được ký số và thuật toán mã hóa (base64). Signature/SignatureValue: Giá trị của chữ ký số (mã hóa base64). Signature/KeyInfo/X509 Data/X509Certificate: Thông tin chứng thư chữ ký số (X.509) chứa khóa công khai để xác thực. SigningTime: Thời điểm thực hiện ký số, định dạng YYYY-MMDDThh:mm:ss', 'Đối tượng tham chiếu mô tả thông tin ký số của cán bộ/nhà giáo; dùng để ký số xác nhận nội dung trên học bạ số hoặc văn bằng số .', array['MOET18']::text[], 'chuKySoCaNhanCuaGvcn', 'Object', 'Đối tượng', 'Dữ liệu cấu trúc', null),
  ('BG_00260', 'Ngày vào đảng của cán bộ/nhà giáo', 'Là ngày cán bộ/nhà giáo được kết nạp vào Đảng.', 'Thuộc tính ghi nhận mốc thời gian ngày vào đảng của nhà giáo, cán bộ quản lý giáo dục.', array['MOET18']::text[], 'ngayVaoDangDn', 'Date', 'Ngày tháng', '10', 'CDE-TG-001'),
  ('BG_00261', 'Ngày vào đảng chính thức của cán bộ/nhà giáo', 'Là ngày cán bộ/nhà giáo được công nhận là đảng viên chính thức sau thời gian dự bị theo quy định của Điều lệ Đảng.', 'Thuộc tính ghi nhận mốc thời gian ngày vào đảng chính thức của cán bộ/nhà giáo', array['MOET18']::text[], 'ngayVaoDangCtDn', 'Date', 'Ngày tháng', '10', 'CDE-TG-001'),
  ('BG_00262', 'Ngày nhập ngũ', 'Là thời điểm cán bộ/nhà giáo bắt đầu thực hiện nghĩa vụ quân sự hoặc tham gia phục vụ trong lực lượng vũ trang theo quy định của pháp luật.', 'Thuộc tính ghi nhận mốc thời gian ngày nhập ngũ của nhà giáo, cán bộ quản lý giáo dục.', array['MOET18']::text[], 'ngayNhapNgu', 'Date', 'Ngày tháng', '10', 'CDE-TG-001'),
  ('BG_00263', 'Ngày xuất ngũ', 'Là thời điểm cán bộ/nhà giáo hoàn thành nghĩa vụ quân sự và được xuất ngũ theo quyết định của cơ quan có thẩm quyền', 'Thuộc tính ghi nhận mốc thời gian ngày xuất ngũ của nhà giáo, cán bộ quản lý giáo dục.', array['MOET18']::text[], 'ngayXuatNgu', 'Date', 'Ngày tháng', '10', 'CDE-TG-001'),
  ('BG_00264', 'Quân hàm', 'Là quân hàm của cán bộ/nhà giáo.', 'Thuộc tính mô tả quân hàm của cán bộ/nhà giáo.', array['MOET18']::text[], 'quanHam', 'String', 'Chuỗi ký tự', '50', null),
  ('BG_00265', 'Sở trường công tác', 'Là điểm mạnh hoặc kinh nghiệm của cán bộ/nhà giáo trong lĩnh vực nào đó.', 'Thuộc tính mô tả điểm mạnh, kinh nghiệm công tác của cán bộ/ nhà giáo trong lĩnh vực cụ thể.', array['MOET18']::text[], 'soTruongCongTac', 'String', 'Chuỗi ký tự', '100', null),
  ('BG_00266', 'Tình trạng sức khỏe cán bộ/nhà giáo', 'Là tình trạng sức khỏe của cán bộ/nhà giáo được đánh giá theo năm.', 'Thuộc tính phân loại tình trạng sức khỏe của nhà giáo, cán bộ quản lý giáo dục; chuẩn hóa danh mục, phục vụ thống kê và báo cáo trong quản lý giáo dục.', array['MOET18']::text[], 'tinhTrangSucKhoeDn', 'Enumeration', 'Danh mục liệt kê', null, null),
  ('BG_00267', 'Hạng thương binh', 'Là những cán bộ nhà giáo phân loại mức độ suy giảm khả năng lao động (tỷ lệ tổn thương cơ thể) của thương binh. Cán bộ, nhà giáo công tác tại cơ sở giáo dục đại học là thương binh sẽ được xếp hạng theo quy định và hưởng song song hai nhóm quyền lợi.', 'Thuộc tính phân loại hạng thương binh của nhà giáo, cán bộ quản lý giáo dục; chuẩn hóa danh mục, phục vụ thống kê và báo cáo trong quản lý giáo dục.', array['MOET18']::text[], 'hangThuongBinh', 'Enumeration', 'Danh mục liệt kê', null, null),
  ('BG_00268', 'Loại tiếng dân tộc', 'Là tên môn học dùng để xác định loại ngôn ngữ dân tộc thiểu số mà cán bộ/nhà giáo biết sử dụng hoặc giảng dạy trong hệ thống quản lý dữ liệu của ngành giáo dục.', 'Thuộc tính mô tả loại tiếng dân tộc của cán bộ/nhà giáo biết sử dụng; phục vụ thống kê và báo cáo trong quản lý giáo dục.', array['MOET19']::text[], 'loaiTiengDanToc', 'Enumeration', 'Danh mục liệt kê', null, null),
  ('BG_00269', 'Loại chứng chỉ tiếng dân tộc thiểu số', 'Là chứng chỉ mà cán bộ/nhà giáo đạt được để công nhận trình độ tiếng dân tộc.', 'Thuộc tính phân loại loại chứng chỉ tiếng dân tộc thiểu số của cán bộ/nhà giáo', array['MOET19']::text[], 'loaiChungChiTiengDanTocThieuSo', 'Enumeration', 'Danh mục liệt kê', null, null),
  ('BG_00270', 'Loại bồi dưỡng thường xuyên', 'Là chương trình hoặc nội dung bồi dưỡng thường xuyên mà cán bộ/nhà giáo tham gia trong hệ thống quản lý giáo dục quốc dân.', 'Thuộc tính mô tả loại bồi dưỡng thường xuyên của cán bộ/nhà giáo', array['MOET19']::text[], 'loaiBoiDuongThuongXuyen', 'Enumeration', 'Danh mục liệt kê', null, null),
  ('BG_00271', 'Loại trình độ chuyên môn', 'Là trình độ chuyên môn nghiệp vụ của cán bộ/nhà giáo.', 'Thuộc tính mô tả loại trình độ chuyên môn của cán bộ/nhà giáo', array['MOET19']::text[], 'loaiTrinhDoChuyenMon', 'Enumeration', 'Danh mục liệt kê', null, null),
  ('BG_00272', 'Loại trình độ lý luận chính trị', 'Là trình độ lý luận chính trị của cán bộ/nhà giáo.', 'Thuộc tính mô tả trình độ lý luận chính trị của cán bộ/nhà giáo', array['MOET19']::text[], 'loaiTrinhDoLyLuanChinhTri', 'Enumeration', 'Danh mục liệt kê', null, null),
  ('BG_00273', 'Loại trình độ quản lý giáo dục', 'Là trình độ quản lý giáo dục của cán bộ/nhà giáo.', 'Thuộc tính mô tả loại trình độ quản lý giáo dục của cán bộ/nhà giáo', array['MOET19']::text[], 'loaiTrinhDoQuanLyGiaoDuc', 'Enumeration', 'Danh mục liệt kê', null, null),
  ('BG_00274', 'Loại ngoại ngữ', 'Là tên ngoại ngữ mà cán bộ/nhà giáo đã được đào tạo.', 'Thuộc tính mô tả loại ngoại ngữ mà cán bộ/nhà giáo đã được đào tạo.', array['MOET19']::text[], 'loaiNgoaiNgu', 'Enumeration', 'Danh mục liệt kê', null, null),
  ('BG_00275', 'Loại trình độ ngoại ngữ', 'Là trình độ của loại ngoại ngữ mà cán bộ/nhà giáo đã được đào tạo.', 'Thuộc tính mô tả loại trình độ ngoại ngữ mà cán bộ/nhà giáo đã được đào tạo.', array['MOET19']::text[], 'loaiTrinhDoNgoaiNgu', 'Enumeration', 'Danh mục liệt kê', null, null),
  ('BG_00276', 'Điểm ngoại ngữ', 'Là số điểm thể hiện kết quả đạt được của cán bộ/nhà giáo trong kỳ thi hoặc bài kiểm tra đánh giá năng lực ngoại ngữ.', 'Sử dụng để đánh giá số điểm đạt được của cán bộ/nhà giáo trong kỳ thi hoặc bài kiểm tra đánh giá năng lực ngoại ngữ.', array['MOET19']::text[], 'diemNgoaiNgu', 'Number', 'Số', null, null),
  ('BG_00277', 'Ngày cấp chứng chỉ ngoại ngữ', 'Là ngày được cấp chứng chỉ ngoại ngữ sau khi người học hoàn thành kỳ thi hoặc bài kiểm tra đánh giá năng lực ngoại ngữ.', 'Thuộc tính ghi nhận mốc thời gian ngày cấp chứng chỉ ngoại ngữ của người học.', array['MOET19']::text[], 'ngayCapChungChiNn', 'Date', 'Ngày tháng', '10', 'CDE-TG-001'),
  ('BG_00278', 'Loại trình độ tin học', 'Là trình độ thể hiện mức độ kỹ năng hoặc chứng chỉ tin học của cán bộ/nhà giáo.', 'Thuộc tính mô tả loại trình độ tin học của cán bộ/nhà giáo', array['MOET19']::text[], 'loaiTrinhDoTinHoc', 'Enumeration', 'Danh mục liệt kê', null, null),
  ('BG_00279', 'Loại chuyên môn 1', 'Là tên chuyên ngành đào tạo chính (chuyên môn chính) của cán bộ/nhà giáo.', 'Thuộc tính mô tả chuyên môn chính của cán bộ/nhà giáo', array['MOET19']::text[], 'loaiChuyenMon1', 'Enumeration', 'Danh mục liệt kê', null, null),
  ('BG_00280', 'Loại trình độ 1', 'Là trình độ thể hiện mức độ đạt được của cán bộ/nhà giáo trong chuyên ngành đào tạo chính.', 'Thuộc tính mô tả trình độ thể hiện mức độ đạt được của cán bộ/nhà giáo trong chuyên ngành đào tạo chính.', array['MOET19']::text[], 'loaiTrinhDo1', 'Enumeration', 'Danh mục liệt kê', null, null),
  ('BG_00281', 'Loại chuyên môn 2', 'Là tên chuyên ngành đào tạo thứ hai của cán bộ/nhà giáo nếu người đó có thêm một bằng cấp chuyên môn khác ngoài chuyên môn chính.', 'Thuộc tính mô tả chuyên ngành đào tạo thứ hai của cán bộ/nhà giáo nếu người đó có thêm một bằng cấp chuyên môn khác ngoài chuyên môn chính.', array['MOET19']::text[], 'loaiChuyenMon2', 'Enumeration', 'Danh mục liệt kê', null, null),
  ('BG_00282', 'Loại trình độ 2', 'Là trình độ thể hiện mức độ đạt được của cán bộ/nhà giáo trong chuyên ngành đào tạo 2.', 'Thuộc tính mô tả trình độ thể hiện mức độ đạt được của cán bộ/nhà giáo trong chuyên ngành đào tạo 2.', array['MOET19']::text[], 'loaiTrinhDo2', 'Enumeration', 'Danh mục liệt kê', null, null),
  ('BG_00283', 'Có chứng chỉ bồi dưỡng chức danh nghề nghiệp', 'Là văn bằng bắt buộc đối với viên chức (cán bộ/nhà giáo, y tế, kế toán...) trong các đơn vị công lập, chứng nhận đã hoàn thành khóa học cập nhật kiến thức, kỹ năng chuyên môn.', 'Thuộc tính đánh dấu có chứng chỉ bồi dưỡng chức danh nghề nghiệp của cán bộ/nhà giáo (giá trị có/không).', array['MOET19']::text[], 'isCoCcBoiDuongChucDanhNgheNghiep', 'Boolean', 'Đúng/Sai', null, null),
  ('BG_00284', 'Học hàm', 'Là chức danh khoa học do Nhà nước phong tặng cho cá nhân có trình độ chuyên môn cao và có đóng góp trong giảng dạy hoặc nghiên cứu khoa học.', 'Thuộc tính mô tả học hàm của cán bộ/nhà giáo.', array['MOET19']::text[], 'hocHam', 'Enumeration', 'Danh mục liệt kê', null, null),
  ('BG_00285', 'Bác sĩ/Dược sĩ chuyên khoa', 'Là chức danh của cán bộ/nhà giáo có thêm bằng Bác sĩ chuyên khoa I, II/ Dược sĩ chuyên khoa I, II', 'Thuộc tính mô tả chức danh của cán bộ/nhà giáo có thêm bằng Bác sĩ//Dược sĩ chuyên khoa', array['MOET19']::text[], 'bacSiCkDuocSiCk', 'String', 'Chuỗi ký tự', '100', null),
  ('BG_00286', 'Khung năng lực ngoại ngữ của cán bộ/nhà giáo', 'Là phản ánh trình độ ngoại ngữ hiện tại của cán bộ/nhà giáo.', 'Thuộc tính mô tả khung năng lực ngoại ngữ của cán bộ/nhà giáo', array['MOET19']::text[], 'khungNangLucNgoaiNgu', 'Enumeration', 'Danh mục liệt kê', null, null),
  ('BG_00287', 'Chứng chỉ bồi dưỡng sư phạm cho cán bộ/nhà giáo', 'Là cán bộ/nhà giáo có chứng chỉ bồi dưỡng nghiệp vụ sư phạm cho cán bộ/nhà giáo.', 'Thuộc tính đánh dấu cán bộ/nhà giáo có chứng chỉ bồi dưỡng nghiệp vụ sư phạm (giá trị có/không).', array['MOET19']::text[], 'chungChiBoiDuongNghiepVuSuPham', 'String', 'Chuỗi ký tự', '255', null),
  ('BG_00288', 'Chuyên môn được đào tạo của cán bộ/nhà giáo', 'Là lĩnh vực chuyên ngành mà cán bộ/nhà giáo đã được đào tạo hoặc có trình độ chuyên môn, được xác định thông qua bằng cấp, chứng chỉ hoặc quá trình đào tạo chính quy.', 'Thuộc tính mô tả chuyên môn được đào tạo của cán bộ/nhà giáo; thuộc nhóm dữ liệu về trình độ chuyên môn của nhà giáo, cán bộ quản lý giáo dục.', array['MOET19']::text[], 'chuyenMonDuocDaoTao', 'String', 'Chuỗi ký tự', '100', null),
  ('BG_00289', 'Nhóm cán bộ', 'Là dùng để phân loại nhóm cán bộ/ nhà giáo ngành giáo dục dựa trên vị trí việc làm.', 'Thuộc tính phân loại nhóm cán bộ/nhà giáo; phục vụ thống kê và báo cáo trong quản lý giáo dục.', array['MOET20']::text[], 'nhomCb', 'Enumeration', 'Danh mục liệt kê', null, null),
  ('BG_00290', 'Loại cán bộ', 'Là dùng để phân loại cán bộ/ nhà giáo trong nhóm cán bộ ngành giáo dục dựa trên vị trí việc làm.', 'Thuộc tính phân loại loại cán bộ/nhà giáo; phục vụ thống kê và báo cáo trong quản lý giáo dục.', array['MOET20']::text[], 'loaiCb', 'Enumeration', 'Danh mục liệt kê', null, null),
  ('BG_00291', 'Loại hình thức hợp đồng', 'Là dùng để phân loại hình thức hợp đồng của cán bộ/nhà giáo.', 'Thuộc tính phân loại loại hình thức hợp đồng của cán bộ/nhà giáo, phục vụ thống kê và báo cáo trong quản lý giáo dục.', array['MOET20']::text[], 'loaiHinhThucHopDong', 'Enumeration', 'Danh mục liệt kê', null, null),
  ('BG_00292', 'Ngày tuyển dụng', 'Là ngày được ghi trong quyết định tuyển dụng của cán bộ/nhà giáo tại một cơ sở giáo dục.', 'Thuộc tính ghi nhận mốc thời gian ngày tuyển dụng của cán bộ/nhà giáo.', array['MOET20']::text[], 'ngayTuyenDung', 'Date', 'Ngày tháng', '10', 'CDE-TG-001'),
  ('BG_00293', 'Cơ quan tuyển dụng', 'Là cơ quan chuyên môn chủ trì, có thẩm quyền tuyển dụng cán bộ/nhà giáo tại các cơ sở giáo dục.', 'Thuộc tính mô tả thông tin cơ quan chuyên môn chủ trì, có thẩm quyền tuyển dụng cán bộ/nhà giáo tại các cơ sở giáo dục.', array['MOET20']::text[], 'coQuanTuyenDung', 'String', 'Chuỗi ký tự', '255', null),
  ('BG_00294', 'Nghề nghiệp khi được tuyển dụng', 'Là công việc của cán bộ/nhà giáo khi được tuyển dụng có ghi trong quyết định tuyển dụng.', 'Thuộc tính mô tả nghề nghiệp khi được tuyển dụng của tuyển dụng, vị trí việc làm của nhà giáo và cán bộ quản lý giáo dục.', array['MOET20']::text[], 'ngheNghiepKhiDuocTuyenDung', 'String', 'Chuỗi ký tự', '255', null),
  ('BG_00295', 'Ngạch/hạng', 'Là hạng chức danh nghề nghiệp của cán bộ/nhà giáo.', 'Thuộc tính mô tả ngạch/hạng của lương, phụ cấp của cán bộ/nhà giáo.', array['MOET20']::text[], 'maNgach', 'String', 'Chuỗi ký tự', '255', null),
  ('BG_00296', 'Số ngạch/hạng', 'Là mã số gắn liền với hạng chức danh nghề nghiệp của cán bộ/nhà giáo.', 'Thuộc tính mô tả số ngạch/hạng của lương, phụ cấp của cán bộ/nhà giáo.', array['MOET20']::text[], 'maSoNgach', 'String', 'Chuỗi ký tự', '255', null),
  ('BG_00297', 'Môn dạy', 'Là tên môn học dùng để xác định một môn học cụ thể mà cán bộ/nhà giáo đó đang phụ trách giảng dạy.', 'Thuộc tính mô tả môn dạy của môn học, học phần.', array['MOET20']::text[], 'maMonDay', 'String', 'Chuỗi ký tự', '255', null),
  ('BG_00298', 'Môn kiêm nhiệm', 'Là tên môn học dùng hoặc nhiệm vụ giáo dục mà cán bộ/nhà giáo đó đang kiêm nhiệm, bên cạnh môn dạy chính.', 'Thuộc tính mô tả môn kiêm nhiệm của trình độ chuyên môn của nhà giáo, cán bộ quản lý giáo dục.', array['MOET20']::text[], 'maMonKiemNhiem', 'String', 'Chuỗi ký tự', '255', null),
  ('BG_00299', 'Số tiết thực dạy trên tuần', 'Là tổng số tiết học mà cán bộ/nhà giáo trực tiếp đứng lớp giảng dạy trong một tuần theo thời khóa biểu của cơ sở giáo dục.', 'Thuộc tính mô tả số tiết thực dạy trên tuần của tổ chức giảng dạy.', array['MOET20']::text[], 'soTietThucDayTuan', 'String', 'Chuỗi ký tự', '255', null),
  ('BG_00300', 'Số tiết thực kiêm nhiệm trên tuần', 'Là số tiết được tính cho các công việc kiêm nhiệm mà cán bộ/nhà giáo đảm nhận ngoài việc giảng dạy, và các công việc này được quy đổi ra số tiết trong một tuần.', 'Thuộc tính mô tả số tiết thực kiêm nhiệm trên tuần của đánh giá chuẩn nghề nghiệp nhà giáo, cán bộ quản lý giáo dục.', array['MOET20']::text[], 'soTietThucKiemNhiemTuan', 'String', 'Chuỗi ký tự', '255', null),
  ('BG_00301', 'Có dạy lớp khuyết tật', 'Là việc cán bộ/nhà giáo giảng dạy cho học sinh khuyết tật hoặc lớp học có học sinh khuyết tật, theo các hình thức giáo dục phù hợp với khả năng và nhu cầu đặc biệt của các em.', 'Thuộc tính đánh dấu có dạy lớp khuyết tật của trình độ chuyên môn của nhà giáo, cán bộ quản lý giáo dục (giá trị có/không).', array['MOET20']::text[], 'isDayLopKhuyetTat', 'Boolean', 'Đúng/Sai', '1', null),
  ('BG_00302', 'Có dạy 1 buổi/ngày', 'Là cán bộ/nhà giáo chỉ dạy 1 buổi/ngày.', 'Thuộc tính đánh dấu cán bộ/nhà giáo có dạy 1 buổi/ngày (giá trị có/không).', array['MOET20']::text[], 'isDay1Buoi', 'Boolean', 'Đúng/Sai', '1', null),
  ('BG_00303', 'Có dạy 2 buổi/ngày', 'Là cán bộ/nhà giáo dạy 2 buổi/ngày.', 'Thuộc tính đánh dấu cán bộ/nhà giáo có dạy 2 buổi/ngày (giá trị có/không).', array['MOET20']::text[], 'isDay2Buoi', 'Boolean', 'Đúng/Sai', '1', null),
  ('BG_00304', 'Có chuyên trách đoàn đội', 'Là cán bộ/nhà giáo chịu trách nhiệm tổ chức, quản lý và triển khai các hoạt động của Đoàn hoặc Đội trong cơ sở giáo dục.', 'Thuộc tính đánh dấu có chuyên trách đoàn đội của tuyển dụng, vị trí việc làm của nhà giáo và cán bộ quản lý giáo dục (giá trị có/không).', array['MOET20']::text[], 'isChuyenTrachDoanDoi', 'Boolean', 'Đúng/Sai', '1', null),
  ('BG_00305', 'Được tuyển mới', 'Là cán bộ/nhà giáo vừa trúng tuyển và được ký hợp đồng làm việc lần đầu hoặc tiếp nhận vào các cơ sở giáo dục.', 'Thuộc tính đánh dấu cán bộ/nhà giáo vừa trúng tuyển và được ký hợp đồng làm việc lần đầu hoặc tiếp nhận vào các cơ sở giáo dục.', array['MOET20']::text[], 'isTuyenMoi', 'String', 'Chuỗi ký tự', '255', null),
  ('BG_00306', 'Ngày chuyển đến', 'Là ngày mà cán bộ/nhà giáo chính thức được điều động hoặc chuyển công tác đến đơn vị hiện tại theo quyết định của cơ quan có thẩm quyền.', 'Thuộc tính ghi nhận mốc thời gian ngày chuyển đến trong quá trình công tác của cán bộ/giáo viên.', array['MOET20']::text[], 'ngayChuyenDen', 'Date', 'Ngày tháng', '10', 'CDE-TG-001'),
  ('BG_00307', 'Năm vào trường', 'Là dùng để xác định thời điểm cán bộ/nhà giáo bắt đầu làm việc tại cơ sở giáo dục nào đó.', 'Thuộc tính ghi nhận mốc thời gian năm vào trường trong quá trình công tác của cán bộ/giáo viên.', array['MOET20']::text[], 'namVaoTruong', 'Date', 'Ngày tháng', '10', null),
  ('BG_00308', 'Loại nhiệm vụ kiêm nhiệm', 'Là tên nhiệm vụ kiêm nhiệm mà cán bộ/nhà giáo được giao thêm ngoài nhiệm vụ chính.', 'Thuộc tính mô tả tên nhiệm vụ kiêm nhiệm của cán bộ/nhà giáo.', array['MOET20']::text[], 'loaiNhiemVuKiemNhiem', 'Enumeration', 'Danh mục liệt kê', null, null),
  ('BG_00309', 'Số buổi dạy trên ngày', 'Là thông tin cho biết số lượng buổi dạy trên ngày của cán bộ/nhà giáo.', 'Thuộc tính mô tả số buổi dạy trên ngày của cán bộ/nhà giáo.', array['MOET20']::text[], 'soBuoiDayTrenNgay', 'String', 'Chuỗi ký tự', '255', null),
  ('BG_00310', 'Cấp dạy', 'Là tên cấp học mà cán bộ/nhà giáo đó đang tham gia giảng dạy đối với trường liên cấp.', 'Thuộc tính mô tả cấp dạy của cán bộ/nhà giáo.', array['MOET20']::text[], 'maCapDay', 'String', 'Chuỗi ký tự', '255', null),
  ('BG_00311', 'Giáo viên chủ nhiệm', 'Là nhà giáo được phân công chịu trách nhiệm quản lý, giáo dục toàn diện và điều hành các hoạt động của một lớp học cụ thể trong suốt một năm học.', 'Thuộc tính đánh đấu phân công giảng dạy của cán bộ/nhà giáo trong cở sở giáo dục.', array['MOET20']::text[], 'tenGiaoVienChuNhiem', 'String', 'Chuỗi ký tự', '150', null),
  ('BG_00312', 'Giáo viên bộ môn', 'Là nhà giáo được phân công giảng dạy và đánh giá học sinh trong một môn học cụ thể.', 'Thuộc tính đánh đấu phân công giảng dạy của cán bộ/nhà giáo trong cơ sở giáo dục.', array['MOET20']::text[], 'giaOVienBoMon', 'String', 'Chuỗi ký tự', '255', null),
  ('BG_00313', 'Giáo viên biệt phái', 'Là cán bộ/nhà giáo được điều động về công tác tại trung tâm.', 'Thuộc tính đánh dấu giáo viên được biệt phái.', array['MOET20']::text[], 'giaoVienBietPhai', 'String', 'Chuỗi ký tự', '255', null),
  ('BG_00314', 'Cộng tác viên dạy học', 'Là người dạy học không trong biên chế, ký hợp đồng ngắn hạn với trung tâm.', 'Thuộc tính đánh dấu cộng tác viên dạy học của tổ chức giảng dạy (giá trị có/không).', array['MOET20']::text[], 'isCongTacVien', 'Boolean', 'Đúng/Sai', '1', null),
  ('BG_00315', 'Dạy xóa mù chữ', 'Là các cơ sở giáo dục có tổ chức dạy xóa mù chữ.', 'Thuộc tính đánh dấu dạy xóa mù chữ của cơ sở giáo dục, trung tâm, cơ sở đào tạo (giá trị có/không).', array['MOET20']::text[], 'isXoaMuChu', 'Boolean', 'Đúng/Sai', '1', null),
  ('BG_00316', 'Giảng dạy các môn chung', 'Là cán bộ/nhà giáo được phân công giảng dạy các môn chung, môn đại cương.', 'Thuộc tính đánh dấu giảng dạy các môn chung của tổ chức giảng dạy (giá trị có/không).', array['MOET20']::text[], 'isGiangDayCacMonChung', 'Boolean', 'Đúng/Sai', '1', null),
  ('BG_00317', 'Vị trí làm việc', 'Là chức danh công việc hoặc vai trò chuyên môn mà cán bộ/nhà giáo đảm nhiệm tại cơ sở đào tạo.', 'Thuộc tính phân loại vị trí làm việc của đánh giá chuẩn nghề nghiệp nhà giáo, cán bộ quản lý giáo dục; chuẩn hóa danh mục, phục vụ thống kê và báo cáo trong quản lý giáo dục.', array['MOET20']::text[], 'viTriLamViec', 'Enumeration', 'Danh mục liệt kê', null, null),
  ('BG_00318', 'Ngành giảng dạy', 'Là lĩnh vực chuyên môn mà người dạy trực tiếp tham gia giảng dạy trong cơ sở đào tạo.', 'Thuộc tính phân loại lĩnh vực chuyên môn của cán bộ/nhà giáo trực tiếp tham gia giảng dạy trong cơ sở đào tạo.', array['MOET20']::text[], 'nganhGiangDay', 'Enumeration', 'Danh mục liệt kê', null, null),
  ('BG_00319', 'Là ngành chính', 'Là thông tin xác định ngành giảng dạy chính (chuyên môn chính) của cán bộ/nhà giáo trong trường hợp cá nhân tham gia giảng dạy nhiều ngành khác nhau.', 'Thuộc tính mô tả ngành chính của cán bộ/nhà giáo.', array['MOET20']::text[], 'isNganhChinh', 'Boolean', 'Đúng/Sai', '1', null),
  ('BG_00320', 'Đơn vị thỉnh giảng', 'Là cơ sở giáo dục nơi nhà giáo tham gia giảng dạy theo hình thức thỉnh giảng.', 'Trường dữ liệu dùng để nhận biết đơn vị mà nhà giáo đang tham gia dưới vai trò thỉnh giảng.', array['MOET20']::text[], 'donViThinhGiang', 'String', 'Chuỗi ký tự', '255', null),
  ('BG_00321', 'Chức danh của cán bộ/nhà giáo tại hội đồng', 'Là vai trò hoặc vị trí của cá nhân trong một hội đồng của cơ sở giáo dục.', 'Thuộc tính phân loại chức danh của cán bộ/nhà giáo tại hội đồng; thuộc nhóm dữ liệu về nhà giáo, cán bộ quản lý giáo dục; chuẩn hóa danh mục, phục vụ thống kê và báo cáo trong quản lý giáo dục.', array['MOET20']::text[], 'chucDanhDoiNguTaiHoiDong', 'Enumeration', 'Danh mục liệt kê', null, null),
  ('BG_00322', 'Lý do nghỉ việc', 'Là nguyên nhân hoặc căn cứ khiến cán bộ/nhà giáo chấm dứt công tác tại cơ sở giáo dục.', 'Thuộc tính mô tả lý do nghỉ việc của cán bộ/nhà giáo.', array['MOET21']::text[], 'lyDoNghiViec', 'String', 'Chuỗi ký tự', '255', null),
  ('BG_00323', 'Cán bộ/nhà giáo chuyển đến', 'Là trạng thái cho biết cán bộ/nhà giáo được điều động hoặc chuyển công tác từ một nơi khác đến làm việc tại cơ sở giáo dục này.', 'Thuộc tính mô tả trạng thái điều động hoặc chuyển đến của cán bộ/nhà giáo. sử dụng', array['MOET21']::text[], 'cbNgChuyenDen', 'String', 'Chuỗi ký tự', '255', null),
  ('BG_00324', 'Ngày chuyển trạng thái cán bộ/nhà giáo', 'Là ngày mà chuyển sang tình trạng công tác mới của cán bộ/nhà giáo.', 'Thuộc tính ghi nhận mốc thời gian ngày chuyển trạng thái của cán bộ/nhà giáo.', array['MOET21']::text[], 'ngayChuyenTtDn', 'Date', 'Ngày tháng', '10', 'CDE-TG-001'),
  ('BG_00325', 'Cơ quan công tác của cán bộ/nhà giáo', 'Là tên đơn vị, tổ chức nơi cán bộ/nhà giáo đang làm việc hoặc được phân công công tác.', 'Thuộc tính mô tả tên đơn vị, tổ chức nơi cán bộ/nhà giáo đang công tác.', array['MOET21']::text[], 'coQuanCongTac', 'String', 'Chuỗi ký tự', '100', null),
  ('BG_00326', 'Chức vụ tại cơ quan công tác của cán bộ/nhà giáo', 'Là chức vụ của cán bộ tại cơ quan công tác.', 'Thuộc tính mô tả tên chức vụ của cán bộ/nhà giáo tại cơ quản công tác.', array['MOET21']::text[], 'chucVuTaiCoQuanCongTac', 'Enumeration', 'Danh mục liệt kê', null, null),
  ('BG_00327', 'Cán bộ/nhà giáo thuộc ban, tiểu ban', 'Là cán bộ/nhà giáo làm công tác chuyên môn, quản lý hoặc giảng dạy được điều động tham gia một tổ chức, hội đồng để nhận nhiệm vụ công việc cụ thể của tiểu ban/ban đó.', 'Thuộc tính phân loại ban hoặc tiểu ban mà cán bộ/nhà giáo tham gia, nhận nhiệm vụ cụ thể.', array['MOET21']::text[], 'thuocTieuBan', 'String', 'Chuỗi ký tự', '100', null),
  ('BG_00328', 'Chức danh nghề nghiệp', 'Là tên gọi thể hiện trình độ và năng lực chuyên môn, nghiệp vụ của cán bộ/nhà giáo trong từng lĩnh vực nghề nghiệp.', 'Thuộc tính mô tả chức danh nghề nghiệp của cán bộ/nhà giáo.', array['MOET21']::text[], 'chucDanhNgheNghiep', 'Enumeration', 'Danh mục liệt kê', null, null),
  ('BG_00329', 'Có được tập huấn kỹ năng sống', 'Là hoạt động đào tạo hoặc bồi dưỡng nhằm trang bị kiến thức cho cán bộ/nhà giáo để có thể truyền đạt kỹ năng sống cho người học.', 'Thuộc tính đánh dấu cán bộ/nhà giáo được tập huấn kỹ năng sống để có khả năng truyên đạt cho người học (giá trị có/không).', array['MOET22']::text[], 'isTapHuanKyNangSong', 'Boolean', 'Đúng/Sai', '1', null),
  ('BG_00330', 'Có tham gia chương trình bồi dưỡng', 'Là cán bộ/nhà giáo được tham gia các chương trình bồi dưỡng kiến thức, kỹ năng theo yêu cầu của vị trí việc làm.', 'Thuộc tính đánh dấu cán bộ/nhà giáo có tham gia chương trình bồi dưỡng (giá trị có/không).', array['MOET22']::text[], 'isThamGiaCtBoiDuong', 'Boolean', 'Đúng/Sai', '1', null),
  ('BG_00331', 'Tên cơ sở đào tạo bồi dưỡng cán bộ/nhà giáo', 'Là tên cơ sở đào tạo mà cán bộ/nhà giáo tham gia học, bồi dưỡng.', 'Thuộc tính thể hiện tên cơ sở đào tạo bồi dưỡng mà cán bộ/nhà giáo đã tham gia.', array['MOET22']::text[], 'tenCoSoDaoTaoBoiDuong', 'String', 'Chuỗi ký tự', '200', null),
  ('BG_00332', 'Nhóm chuyên ngành đào tạo', 'Là nhóm chuyên ngành mà cán bộ/nhà giáo tham gia trong quá trình đào tạo bồi dưỡng.', 'Thuộc tính phân loại nhóm chuyên ngành đào tạo mà cán bộ/nhà giáo đã tham gia.', array['MOET22']::text[], 'nhomChuyenNganhDaoTao', 'Enumeration', 'Danh mục liệt kê', null, null),
  ('BG_00333', 'Ngày bắt đầu tham gia khóa bồi dưỡng', 'Là ngày cán bộ/nhà giáo bắt đầu tham gia khoá đào tạo, bồi dưỡng.', 'Thuộc tính ghi nhận mốc thời gian ngày bắt đầu tham gia khóa đào tạo, bồi dưỡng của cán bộ/nhà giáo.', array['MOET22']::text[], 'tuThangNam', 'Date', 'Ngày tháng', '10', 'CDE-TG-001'),
  ('BG_00334', 'Ngày kết thúc khóa bồi dưỡng', 'Là ngày cán bộ/nhà giáo kết thúc tham gia khoá đào tạo, bồi dưỡng.', 'Thuộc tính ghi nhận mốc thời gian ngày kết thúc tham gia khóa đào tạo, bồi dưỡng của cán bộ/nhà giáo.', array['MOET22']::text[], 'denThangNam', 'Date', 'Ngày tháng', '10', 'CDE-TG-001'),
  ('BG_00335', 'Hình thức đào tạo bồi dưỡng', 'Là hình thức đào tạo mà cán bộ/nhà giáo tham gia trong quá trình đào tạo bồi dưỡng.', 'Thuộc tính phân loại hình thức đào tạo, bồi dưỡng của cán bộ/nhà giáo; phục vụ thống kê và báo cáo trong quản lý giáo dục.', array['MOET22']::text[], 'hinhThucDaoTaoBoiDuong', 'Enumeration', 'Danh mục liệt kê', null, null),
  ('BG_00336', 'Tên văn bản chứng chỉ đào tạo bồi dưỡng', 'Là tên văn bản chứng chỉ mà cán bộ/nhà giáo nhận được sau quá trình đào tạo, bồi dưỡng.', 'Thuộc tính ghi nhận tên văn bản chứng chỉ đào tạo bồi dưỡng của cán bộ/nhà giáo.', array['MOET22']::text[], 'vanBanChungChi', 'String', 'Chuỗi ký tự', '100', null),
  ('BG_00337', 'Chuyên ngành đào tạo bồi dưỡng', 'Là tên chuyên ngành đào tạo mà cán bộ/nhà giáo nhận được sau quá trình đào tạo, bồi dưỡng.', 'Thuộc tính mô tả chuyên ngành đào tạo bồi dưỡng của cán bộ/nhà giáo.', array['MOET22']::text[], 'chuyenNganhDaoTao', 'String', 'Chuỗi ký tự', '100', null),
  ('BG_00338', 'Loại bồi dưỡng CBQL CSGDPT cốt cán', 'Là dùng để xác định việc cán bộ quản lý đã tham gia chương trình bồi dưỡng dành cho cán bộ quản lý cơ sở giáo dục phổ thông cốt cán.', 'Thuộc tính đánh dấu cán bộ/nhà giáo đã tham gia chương trình bồi dưỡng dành cho cán bộ quản lý cơ sở giáo dục phổ thông cốt cán. sử dụng', array['MOET22']::text[], 'loaiBoiDuongCbqlCsgdptCotCan', 'Enumeration', 'Danh mục liệt kê', null, null),
  ('BG_00339', 'Nước đào tạo', 'Là tên quốc gia cán bộ/nhà giáo đã tham gia đào tạo tại nước đó.', 'Thuộc tính thể hiện tên quốc gia mà cán bộ/ nhà giáo đã tham gia đào tạo.', array['MOET22']::text[], 'nuocDaoTao', 'String', 'Chuỗi ký tự', '255', null),
  ('BG_00340', 'Thời gian bắt đầu tham gia đào tạo của cán bộ/nhà giáo', 'Là thời gian bắt đầu tham gia khóa học đào tạo', 'Thuộc tính ghi nhận mốc thời gian bắt đầu tham gia khóa học đào tạo của cán bộ/nhà giáo.', array['MOET22']::text[], 'thoiGianBatDauThamGiaDt', 'String', 'Chuỗi ký tự', '255', null),
  ('BG_00341', 'Thời gian kết thúc đào tạo của cán bộ/nhà giáo', 'Là thời gian kết thúc khóa học đào tạo cụ thể.', 'Thuộc tính ghi nhận mốc thời gian kết thúc đào tạo của cán bộ/nhà giáo.', array['MOET22']::text[], 'thoiGianKetThucDt', 'String', 'Chuỗi ký tự', '255', null),
  ('BG_00342', 'Thời gian tốt nghiệp của cán bộ/nhà giáo', 'Là thời điểm cán bộ/nhà giáo hoàn thành khóa đào tạo và được công nhận tốt nghiệp.', 'Thuộc tính ghi nhận thời gian tốt nghiệp của cán bộ/nhà giáo.', array['MOET22']::text[], 'thoiGianTotNghiepDt', 'String', 'Chuỗi ký tự', '255', null),
  ('BG_00343', 'Tên luận văn/luận án trong khóa đào tạo của cán bộ/nhà giáo', 'Là tên luận văn/luận án mà cán bộ/nhà giáo đã xây dựng trong khóa đào tạo.', 'Thuộc tính ghi nhận tên luận văn/luận án trong khóa đào tạo của cán bộ/nhà giáo. sử dụng', array['MOET22']::text[], 'tenLuanAn', 'String', 'Chuỗi ký tự', '500', null),
  ('BG_00344', 'Ngày cấp văn bằng/chứng chỉ đào tạo cán bộ/nhà giáo', 'Là thời điểm văn bằng hoặc chứng chỉ được cơ sở giáo dục hoặc tổ chức có thẩm quyền cấp cho cá nhân sau khi hoàn thành chương trình đào tạo.', 'Thuộc tính ghi nhận mốc thời gian ngày cấp văn bằng/chứng chỉ đào tạo cán bộ/nhà giáo của nhà giáo.', array['MOET22']::text[], 'ngayCapBang', 'Date', 'Ngày tháng', '10', 'CDE-TG-001'),
  ('BG_00345', 'Vai trò tham gia trong khóa đào tạo của cán bộ/nhà giáo', 'Là vị trí hoặc chức năng của cán bộ/nhà giáo trong một khóa đào tạo cụ thể.', 'Thuộc tính phân loại vai trò tham gia trong khóa đào tạo của cán bộ/nhà giáo.', array['MOET22']::text[], 'vaiTroKhoaHoc', 'Enumeration', 'Danh mục liệt kê', null, null),
  ('BG_00346', 'Tên khóa bồi dưỡng tập huấn', 'Là tên khóa bồi dưỡng tập huấn cán bộ/nhà giáo đã tham gia.', 'Thuộc tính ghi nhận tên khóa bồi dưỡng tập huấn của cán bộ/nhà giáo.', array['MOET22']::text[], 'tenKhoaBoiDuongDn', 'String', 'Chuỗi ký tự', '500', null),
  ('BG_00347', 'Đơn vị tổ chức bồi dưỡng tập huấn', 'Là cơ quan, tổ chức hoặc cơ sở đào tạo chịu trách nhiệm tổ chức khóa bồi dưỡng, tập huấn cho cán bộ/nhà giáo', 'Thuộc tính mô tả đơn vị tổ chức bồi dưỡng tập huấn của cán bộ/nhà giáo.', array['MOET22']::text[], 'donViToChuc', 'String', 'Chuỗi ký tự', '200', null),
  ('BG_00348', 'Địa điểm tổ chức bồi dưỡng tập huấn', 'Là nơi diễn ra hoạt động bồi dưỡng, tập huấn cán bộ/nhà giáo.', 'Thuộc tính mô tả địa điểm tổ chức bồi dưỡng tập huấn của cán bộ/nhà giáo. sử dụng', array['MOET22']::text[], 'diaDiemToChuc', 'String', 'Chuỗi ký tự', '500', null),
  ('BG_00349', 'Nguồn kinh phí bồi dưỡng tập huấn', 'Là nguồn tài chính chi trả cho hoạt động bồi dưỡng, tập huấn', 'Thuộc tính thể hiện nguồn kinh phí bồi dưỡng tập huấn cho cán bộ/nhà giáo.', array['MOET22']::text[], 'nguonKinhPhi', 'String', 'Chuỗi ký tự', '200', null),
  ('BG_00350', 'Chứng chỉ được cấp sau bồi dưỡng tập huấn', 'Là loại chứng chỉ được cấp cho người tham gia sau khi hoàn thành khóa bồi dưỡng tập huấn', 'Thuộc tính ghi nhận chứng chỉ được cấp sau bồi dưỡng tập huấn của cán bộ/nhà giáo.', array['MOET22']::text[], 'chungChi', 'String', 'Chuỗi ký tự', '200', null),
  ('BG_00351', 'Ngày cấp chứng chỉ bồi dưỡng sau tập huấn', 'Là thời điểm chứng chỉ bồi dưỡng được cấp cho người tham gia sau khi hoàn thành khóa tập huấn', 'Thuộc tính ghi nhận mốc thời gian ngày cấp chứng chỉ bồi dưỡng sau tập huấn của cán bộ/nhà giáo.', array['MOET22']::text[], 'ngayCapCcBoiDuong', 'Date', 'Ngày tháng', '10', 'CDE-TG-001'),
  ('BG_00352', 'Vai trò cán bộ/nhà giáo trong sáng chế/giải pháp', 'Là chức năng hoặc nhiệm vụ cụ thể của từng cá nhân tham gia vào quá trình nghiên cứu, phát triển sáng chế/giải pháp.', 'Thuộc tính phân loại vai trò của cán bộ/nhà giáo trong sáng chế/giải pháp.', array['MOET22']::text[], 'vaiTroKhoaHoc', 'Enumeration', 'Danh mục liệt kê', null, null),
  ('BG_00353', 'Tên bài báo hướng dẫn thành công NCS/HV', 'Là tên công trình nghiên cứu khoa học, bài báo do nghiên cứu sinh hoặc học viên thực hiện trong quá trình đào tạo mà cán bộ/nhà giáo đã hướng dẫn.', 'Thuộc tính ghi nhận tên bài báo hướng dẫn thành công NCS/HV của cán bộ/nhà giáo.', array['MOET23']::text[], 'tenBaiBaoNcsHv', 'String', 'Chuỗi ký tự', '500', null),
  ('BG_00354', 'Trách nhiệm hướng dẫn', 'Là vai trò và mức độ tham gia của cán bộ/nhà giáo trong quá trình đào tạo.', 'Thuộc tính mô tả trách nhiệm hướng dẫn của cán bộ/nhà giáo.', array['MOET23']::text[], 'trachNhiemHuongDanNcsHv', 'String', 'Chuỗi ký tự', '100', null),
  ('BG_00355', 'Thời gian bắt đầu hướng dẫn NCS/HV', 'Là thời điểm cán bộ/nhà giáo bắt đầu hướng dẫn NCS/HV.', 'Thuộc tính ghi nhận mốc thời gian thời gian bắt đầu hướng dẫn NCS/HV của cán bộ/nhà giáo.', array['MOET23']::text[], 'tgBatDauHdNcsHv', 'Date', 'Ngày tháng', '10', null),
  ('BG_00356', 'Thời gian kết thúc hướng dẫn NCS/HV', 'Là thời điểm cán bộ/nhà giáo kết thúc hướng dẫn NCS/HV', 'Thuộc tính ghi nhận mốc thời gian thời gian kết thúc hướng dẫn NCS/HV của cán bộ/nhà giáo.', array['MOET23']::text[], 'tgKetThucHdNcsHv', 'Date', 'Ngày tháng', '10', null),
  ('BG_00357', 'Tên sách biên soạn', 'Là tên của tài liệu, giáo trình, sách chuyên khảo hoặc sách tham khảo do cán bộ/nhà giáo tham gia biên soạn', 'Thuộc tính ghi nhận tên sách biên soạn của cán bộ/nhà giáo.', array['MOET23']::text[], 'tenSach', 'String', 'Chuỗi ký tự', '500', null),
  ('BG_00358', 'Nhà xuất bản', 'Là tổ chức chịu trách nhiệm biên tập, kiểm duyệt nội dung và hoàn thiện bản thảo sách của cán bộ/nhà giao tham gia biên soạn để in ấn hoặc phát hành dưới dạng điện tử', 'Thuộc tính mô tả nhà xuất bản sách của cán bộ/nhà giáo.', array['MOET23']::text[], 'nhaXuatBan', 'String', 'Chuỗi ký tự', '200', null),
  ('BG_00359', 'Năm xuất bản', 'Là năm mà sách do cán bộ/nhà giáo viên biên soạn được biên tập, in ấn hoàn chỉnh và chính thức phát hành rộng rãi ra công chúng thông qua các nhà xuất bản.', 'Thuộc tính ghi nhận mốc thời gian năm xuất bản sách của cán bộ/nhà giáo.', array['MOET23']::text[], 'namXuatBan', 'Date', 'Ngày tháng', '10', null),
  ('BG_00360', 'Số tác giả', 'Là số lượng tác giả tham gia vào quá trình biên soạn sách.', 'Thuộc tính thể hiện số tác giả tham gia quá trình biên soạn sách.', array['MOET23']::text[], 'soTacGia', 'Integer', 'Số nguyên', null, null),
  ('BG_00361', 'Số văn bản xác nhận tham gia biên soạn sách', 'Là số của văn bản do cơ quan có thẩm quyền hoặc cơ sở đào tạo ban hành nhằm xác nhận việc tham gia biên soạn sách của cán bộ/nhà giáo.', 'Thuộc tính ghi nhận số văn bản xác nhận tham gia biên soạn sách của cán bộ/nhà giáo.', array['MOET23']::text[], 'soVbXacNhan', 'String', 'Chuỗi ký tự', '100', null),
  ('BG_00362', 'Loại sách', 'Là loại sách mà cán bộ/nhà giáo tham gia biên soạn.', 'Thuộc tính phân loại loại sách của cán bộ/nhà.', array['MOET23']::text[], 'loaiSach', 'Enumeration', 'Danh mục liệt kê', null, null),
  ('BG_00363', 'Cách thức viết', 'Là cách thức viết sách biên soạn.', 'Thuộc tính mô tả cách thức viết của sách của cán bộ/nhà giáo.', array['MOET23']::text[], 'cachThucViet', 'String', 'Chuỗi ký tự', '200', null),
  ('BG_00364', 'Tên đề tài khoa học', 'Là tên gọi chính thức của đề tài nghiên cứu khoa học, phản ánh nội dung và mục tiêu nghiên cứu.', 'Thuộc tính mô tả tên đề tài nghiên cứu khoa học.', array['MOET23']::text[], 'tenDeTaiNcDoiNgu', 'String', 'Chuỗi ký tự', '500', null),
  ('BG_00365', 'Loại đề tài khoa học', 'Là phân loại đề tài theo tính chất hoặc nguồn quản lý (ví dụ: cấp Nhà nước, cấp Bộ, cấp cơ sở).', 'Thuộc tính thể hiện loại hình hoặc phân loại đề tài khoa học.', array['MOET23']::text[], 'loaiDeTaiKhoaHoc', 'Enumeration', 'Danh mục liệt kê', null, null),
  ('BG_00366', 'Lĩnh vực đề tài', 'Là ngành hoặc lĩnh vực khoa học mà đề tài nghiên cứu thuộc về (ví dụ: công nghệ thông tin, y học, giáo dục…).', 'Thuộc tính ghi nhận lĩnh vực khoa học của đề tài nghiên cứu.', array['MOET23']::text[], 'linhVucDeTai', 'Enumeration', 'Danh mục liệt kê', null, null),
  ('BG_00367', 'Mã đề tài khoa học của cán bộ/nhà giáo', 'Là mã quản lý đề tài trong hệ thống quản lý khoa học và công nghệ.', 'Thuộc tính thể hiện mã quản lý đề tài khoa học của cán bộ, nhà giáo.', array['MOET23']::text[], 'maDeTaiNcDoiNgu', 'String', 'Chuỗi ký tự', '50', null),
  ('BG_00368', 'Cấp đề tài khoa học', 'Là cấp quản lý hoặc phê duyệt đề tài (Nhà nước, Bộ, tỉnh/thành, cơ sở).', 'Thuộc tính thể hiện cấp quản lý hoặc phê duyệt đề tài khoa học.', array['MOET23']::text[], 'capDeTai', 'String', 'Chuỗi ký tự', '200', null),
  ('BG_00369', 'Tổ chức chủ trì', 'Là cơ quan, tổ chức chịu trách nhiệm chính trong việc thực hiện đề tài khoa học.', 'Thuộc tính ghi nhận đơn vị chủ trì thực hiện đề tài khoa học.', array['MOET23']::text[], 'toChucChuTriDeTai', 'String', 'Chuỗi ký tự', '500', null),
  ('BG_00370', 'Chủ nhiệm đề tài khoa học', 'Là cá nhân chịu trách nhiệm chính về chuyên môn và kết quả của đề tài nghiên cứu.', 'Thuộc tính mô tả cá nhân chủ nhiệm đề tài khoa học.', array['MOET23']::text[], 'chuNhiemDeTai', 'String', 'Chuỗi ký tự', '50', null),
  ('BG_00371', 'Vai trò người tham gia', 'Là chức năng hoặc nhiệm vụ cụ thể của từng cá nhân trong nhóm nghiên cứu.', 'Thuộc tính thể hiện vai trò của cá nhân tham gia trong đề tài nghiên cứu.', array['MOET23']::text[], 'vaiTroNguoiThamGia', 'String', 'Chuỗi ký tự', '200', null),
  ('BG_00372', 'Cơ quan quản lý đề tài khoa học', 'Là cơ quan có thẩm quyền quản lý, phê duyệt và giám sát đề tài khoa học.', 'Thuộc tính ghi nhận cơ quan quản lý, phê duyệt và giám sát đề tài khoa học.', array['MOET23']::text[], 'coQuanQuanLyDeTai', 'String', 'Chuỗi ký tự', '500', null),
  ('BG_00373', 'Kinh phí thực hiện đề tài khoa học', 'Là nguồn tài chính chi trả cho hoạt động thực hiện đề tài khoa học', 'Thuộc tính thể hiện kinh phí thực hiện đề tài khoa học.', array['MOET23']::text[], 'kinhPhiThucHien', 'Decimal', 'Số thập phân', null, null),
  ('BG_00374', 'Thời gian bắt đầu đề tài khoa học', 'Là thời điểm chính thức triển khai thực hiện đề tài.', 'Thuộc tính ghi nhận thời điểm bắt đầu thực hiện đề tài khoa học.', array['MOET23']::text[], 'tgBatDauDeTaiNcDoiNgu', 'Date', 'Ngày tháng', '10', null),
  ('BG_00375', 'Thời gian kết thúc đề tài khoa học', 'Là thời điểm hoàn thành hoặc nghiệm thu đề tài.', 'Thuộc tính ghi nhận thời điểm kết thúc hoặc nghiệm thu đề tài khoa học.', array['MOET23']::text[], 'tgKetThucDeTaiNcDoiNgu', 'Date', 'Ngày tháng', '10', null),
  ('BG_00376', 'Kết quả đánh giá đề tài khoa học', 'Là kết quả hội đồng đã xem xét và đánh giá về đề tài.', 'Thuộc tính thể hiện kết quả đánh giá, nghiệm thu đề tài khoa học.', array['MOET23']::text[], 'ketQuaDanhGiaDeTai', 'String', 'Chuỗi ký tự', '200', null),
  ('BG_00377', 'Sản phẩm đề tài khoa học của cán bộ/nhà giáo', 'Là sản phẩm đề tài khoa học của cán bộ/nhà giáo', 'Thuộc tính ghi nhận sản phẩm của đề tài khoa học do cán bộ, nhà giáo thực hiện.', array['MOET23']::text[], 'sanPhamDeTaiNcDoiNgu', 'String', 'Chuỗi ký tự', '3000', null),
  ('BG_00378', 'Năm đề tài khoa học', 'Là năm được công bố kết quả đánh giá đề tài khoa học.', 'Thuộc tính thể hiện năm công bố hoặc đánh giá kết quả đề tài khoa học.', array['MOET23']::text[], 'namDeTai', 'Integer', 'Số nguyên', null, null),
  ('BG_00379', 'Tên bài báo khoa học', 'Là tên gọi chính thức của công trình nghiên cứu khoa học được công bố.', 'Thuộc tính mô tả tên bài báo khoa học.', array['MOET23']::text[], 'tenBaiBao', 'String', 'Chuỗi ký tự', '500', null),
  ('BG_00380', 'Tên tạp chí', 'Là tên của tạp chí khoa học hoặc ấn phẩm học thuật nơi bài báo được đăng tải', 'Thuộc tính ghi nhận tên tạp chí hoặc ấn phẩm học thuật đăng tải bài báo.', array['MOET23']::text[], 'tenTapChi', 'String', 'Chuỗi ký tự', '200', null),
  ('BG_00381', 'Vai trò tham gia trong bài báo', 'Là vai trò của cá nhân trong bài báo.', 'Thuộc tính thể hiện vai trò của cá nhân trong bài báo khoa học.', array['MOET23']::text[], 'vaiTroTrongBaiBao', 'Enumeration', 'Danh mục liệt kê', null, null),
  ('BG_00382', 'Tạp chí quốc tế', 'Là tên của tạp chí quốc tế nơi bài báo được đăng tải', 'Thuộc tính ghi nhận tạp chí quốc tế đăng tải bài báo khoa học.', array['MOET23']::text[], 'tapChiQuocTe', 'String', 'Chuỗi ký tự', '200', null),
  ('BG_00383', 'Số trích dẫn bài báo', 'Là tổng số lượng các bài báo, công trình nghiên cứu hoặc sách khác đã sử dụng và dẫn chiếu đến bài báo của cán bộ/nhà giáo trong danh mục tài liệu tham khảo.', 'Thuộc tính thể hiện số lượng trích dẫn của bài báo khoa học.', array['MOET23']::text[], 'soTrichDanBaiBao', 'String', 'Chuỗi ký tự', '200', null),
  ('BG_00384', 'Tập số', 'Là số của cuốn tạp chí, bài báo của cán bộ/nhà giáo.', 'Thuộc tính ghi nhận số tập của tạp chí chứa bài báo khoa học.', array['MOET23']::text[], 'tapSoBaiBao', 'Integer', 'Số nguyên', null, null),
  ('BG_00385', 'Trang', 'Là số trang trong tạp chí mà chứa bài báo của cán bộ/nhà giáo.', 'Thuộc tính ghi nhận số trang của bài báo khoa học trong tạp chí.', array['MOET23']::text[], 'trangBaiBao', 'Integer', 'Số nguyên', null, null),
  ('BG_00386', 'Tóm tắt bài báo khoa học', 'Là phần trình bày ngắn gọn mục tiêu, phương pháp, kết quả và kết luận chính của bài báo', 'Thuộc tính mô tả nội dung tóm tắt của bài báo khoa học.', array['MOET23']::text[], 'tomTatBaiBao', 'String', 'Chuỗi ký tự', '3000', null),
  ('BG_00387', 'Năm công bố', 'Là năm bài báo được đăng tải chính thức trên tạp chí khoa học.', 'Thuộc tính ghi nhận mốc thời gian năm công bố bài báo tên tạp chí khoa học.', array['MOET23']::text[], 'namCongBo', 'Date', 'Ngày tháng', '10', null),
  ('BG_00388', 'Chức danh khoa học của cán bộ/nhà giáo', 'Là danh hiệu chuyên môn học thuật được cơ quan có thẩm quyền công nhận cho cá nhân trong lĩnh vực nghiên cứu và giảng dạy.', 'Thuộc tính phân loại chức danh khoa học của cán bộ/nhà giáo.', array['MOET23']::text[], 'chucDanhKhoaHocDoiNgu', 'Enumeration', 'Danh mục liệt kê', null, null),
  ('BG_00389', 'Xếp loại đánh giá chuẩn nghề nghiệp', 'Là kết quả đánh giá chuẩn nghề nghiệp của cán bộ/nhà giáo sau khi được các cấp quản lý đánh giá và công bố.', 'Thuộc tính mô tả xếp loại đánh giá chuẩn nghề nghiệp của cán bộ/nhà giáo.', array['MOET24']::text[], 'loaiDanhGia', 'String', 'Chuỗi ký tự', '20', null),
  ('BG_00390', 'Ngày đánh giá xếp loại chuẩn nghề nghiệp', 'Là ngày mà cơ quan có thẩm quyền hoàn thành đánh giá xếp loại chuẩn nghề nghiệp cho cán bộ/nhà giáo.', 'Thuộc tính ghi nhận mốc thời gian ngày đánh giá xếp loại chuẩn nghề nghiệp của cán bộ/nhà giáo.', array['MOET24']::text[], 'ngayDanhGia', 'Date', 'Ngày tháng', '10', 'CDE-TG-001'),
  ('BG_00391', 'Cấp đánh giá chuẩn nghề nghiệp', 'Là cơ quan quản lý nhà nước có cơ sở giáo dục, UBND Xã/Phường/Đặc khu hay Sở giáo dục và đào tạo.', 'Thuộc tính thể hiện cấp đánh giá chuẩn nghề nghiệp.', array['MOET24']::text[], 'capDanhGia', 'String', 'Chuỗi ký tự', '100', null),
  ('BG_00392', 'Phụ cấp thu hút', 'Là khoản phụ cấp được Nhà nước chi trả thêm cho cán bộ, công chức, viên chức (trong đó có cán bộ/nhà giáo) khi công tác tại vùng có điều kiện kinh tế – xã hội đặc biệt khó khăn, nhằm khuyến khích họ đến làm việc và gắn bó lâu dài tại những khu vực này.', 'Thuộc tính mô tả khoản phụ cấp được chi trả thêm cho cán bộ/nhà giáo.', array['MOET25']::text[], 'pcThuHut', 'String', 'Chuỗi ký tự', '255', null),
  ('BG_00393', 'Phụ cấp thâm niên', 'Là nhà giáo là khoản tiền tính theo tỷ lệ phần trăm của mức lương hiện hưởng, áp dụng cho cán bộ/nhà giáo có thời gian giảng dạy đủ số năm theo quy định.', 'Thuộc tính mô tả phụ cấp thâm niên của cán bộ/nhà giáo.', array['MOET25']::text[], 'pcThamNien', 'String', 'Chuỗi ký tự', '255', null),
  ('BG_00394', 'Phụ cấp ưu đãi nghề', 'Là giáo là khoản tiền tính theo tỷ lệ phần trăm của mức lương hiện hưởng, áp dụng cho nhà giáo trực tiếp giảng dạy trong các cơ sở giáo dục.', 'Thuộc tính mô tả phụ cấp ưu đãi nghề của cán bộ/nhà giáo.', array['MOET25']::text[], 'pcUdNghe', 'String', 'Chuỗi ký tự', '255', null),
  ('BG_00395', 'Bậc lương', 'Là mã bậc lương là mã thể hiện vị trí bậc lương của cán bộ/nhà giáo trong thang bảng lương, tương ứng với hệ số lương và mức lương được hưởng.', 'Thuộc tính mô tả bậc lương của cán bộ/nhà giáo.', array['MOET25']::text[], 'maBacLuong', 'String', 'Chuỗi ký tự', '255', null),
  ('BG_00396', 'Phần trăm vượt khung', 'Là (hay phụ cấp thâm niên vượt khung) là tỷ lệ phần trăm tiền lương được cộng thêm cho cán bộ, công chức, viên chức khi đã ở bậc lương cao nhất của ngạch/hạng nhưng vẫn tiếp tục công tác.', 'Thuộc tính mô tả phần trăm vượt khung lương của cán bộ/nhà giáo.', array['MOET25']::text[], 'phanTramVuotKhung', 'String', 'Chuỗi ký tự', '255', null),
  ('BG_00397', 'Hệ số lương', 'Là thể hiện hệ số mức lương được hưởng của cán bộ/nhà giáo.', 'Thuộc tính mô tả hệ số lươn của cán bộ/nhà giáo.', array['MOET25']::text[], 'heSoLuong', 'String', 'Chuỗi ký tự', '255', null),
  ('BG_00398', 'Ngày hưởng lương', 'Là ngày bắt đầu được tính và hưởng mức lương theo ngạch, bậc hoặc hệ số lương của cán bộ/nhà giáo.', 'Thuộc tính ghi nhận mốc thời gian ngày hưởng lương của lương của cán bộ/nhà giáo. sử dụng', array['MOET25']::text[], 'ngayHuongLuong', 'Date', 'Ngày tháng', '10', 'CDE-TG-001'),
  ('BG_00399', 'Danh hiệu được phong tặng cao nhất', 'Là danh hiệu thi đua hoặc danh hiệu vinh dự cao nhất đã đạt được của cán bộ/nhà giáo.', 'Thuộc tính mô tả danh hiệu được phong tặng cao nhất của cán bộ/nhà giáo.', array['MOET27']::text[], 'danhHieuDuocPhongTangCaoNhat', 'String', 'Chuỗi ký tự', '255', null),
  ('BG_00400', 'Mã khen thưởng cán bộ/nhà giáo', 'Là mã danh mục dùng để xác định loại khen thưởng cán bộ/nhà giáo.', 'Thuộc tính mô tả mã khen thưởng cho cán bộ/nhà giáo.', array['MOET27']::text[], 'maKhenThuongDn', 'String', 'Chuỗi ký tự', '50', null),
  ('BG_00401', 'Loại khen thưởng cán bộ/nhà giáo', 'Là tên khen thưởng của cán bộ/nhà giáo.', 'Thuộc tính phân loại loại khen thưởng cho cán bộ/nhà giáo của nhà giáo.', array['MOET27']::text[], 'loaiKhenThuongDn', 'Enumeration', 'Danh mục liệt kê', null, null),
  ('BG_00402', 'Nội dung khen thưởng cán bộ/nhà giáo', 'Là thông tin liên quan đến nội dung khen thưởng của cán bộ/nhà giáo.', 'Thuộc tính mô tả nội dung khen thưởng của cán bộ/nhà giáo.', array['MOET27']::text[], 'noiDungKhenThuongDn', 'String', 'Chuỗi ký tự', '2000', null),
  ('BG_00403', 'Cấp khen thưởng cán bộ/nhà giáo', 'Là cấp quản lý có thẩm quyền ra quyết định khen thưởng cho cán bộ/nhà giáo.', 'Thuộc tính mô tả cấp khen thưởng của cán bộ/nhà giáo.', array['MOET27']::text[], 'capKhenThuongDn', 'String', 'Chuỗi ký tự', '255', null),
  ('BG_00404', 'Ngày khen thưởng cán bộ/nhà giáo', 'Là ngày ghi trên quyết định khen thưởng của cán bộ/nhà giáo.', 'Thuộc tính ghi nhận mốc thời gian ngày sử dụng khen thưởng của cán bộ/nhà giáo.', array['MOET27']::text[], 'ngayKhenThuongDn', 'Date', 'Ngày tháng', '10', 'CDE-TG-001'),
  ('BG_00405', 'Số quyết định khen thưởng cán bộ/nhà giáo', 'Là số trên văn bản quyết định khen thưởng của cán bộ/nhà giáo.', 'Thuộc tính ghi nhận số quyết định khen thưởng của cán bộ/nhà giáo.', array['MOET27']::text[], 'soQuyetDinhKhenThuongDn', 'String', 'Chuỗi ký tự', '255', null),
  ('BG_00406', 'Năm khen thưởng cán bộ/nhà giáo', 'Là năm mà cán bộ/nhà giáo được khen thưởng.', 'Thuộc tính ghi nhận mốc thời gian năm khen thưởng của cán bộ/nhà giáo.', array['MOET27']::text[], 'namKhenThuongDn', 'Date', 'Ngày tháng', '10', null),
  ('BG_00407', 'Mã kỷ luật cán bộ/nhà giáo', 'Là mã danh mục dùng để xác định loại kỷ luật cán bộ/nhà giáo.', 'Thuộc tính mô tả mã kỷ luật của cán bộ/nhà giáo.', array['MOET27']::text[], 'maKyLuatDn', 'String', 'Chuỗi ký tự', '50', null),
  ('BG_00408', 'Loại kỷ luật cán bộ/nhà giáo', 'Là tên kỷ luật của cán bộ/nhà giáo.', 'Thuộc tính phân loại loại kỷ luật của cán bộ/nhà giáo.', array['MOET27']::text[], 'loaiKyLuatDn', 'Enumeration', 'Danh mục liệt kê', null, null),
  ('BG_00409', 'Lý do kỷ luật cán bộ/nhà giáo', 'Là thông tin liên quan đến việc bị kỷ luật của cán bộ/nhà giáo.', 'Thuộc tính mô tả lý do kỷ luật của cán bộ/nhà giáo.', array['MOET27']::text[], 'lyDoKyLuatDn', 'String', 'Chuỗi ký tự', '255', null),
  ('BG_00410', 'Cấp kỷ luật cán bộ/nhà giáo', 'Là cấp quản lý có thẩm quyền ra quyết định kỷ luật cho cán bộ/nhà giáo.', 'Thuộc tính mô tả cấp kỷ luật của cán bộ/nhà giáo.', array['MOET27']::text[], 'capKyLuatDn', 'String', 'Chuỗi ký tự', '255', null),
  ('BG_00411', 'Ngày kỷ luật cán bộ/nhà giáo', 'Là ngày ghi trên quyết định kỷ luật của cán bộ/nhà giáo.', 'Thuộc tính ghi nhận mốc thời gian ngày kỷ luật của cán bộ/nhà giáo.', array['MOET27']::text[], 'ngayKyLuatNd', 'Date', 'Ngày tháng', '10', 'CDE-TG-001'),
  ('BG_00412', 'Năm kỷ luật cán bộ/nhà giáo', 'Là năm ban hành quyết định kỷ luật cán bộ', 'Thuộc tính ghi nhận mốc thời gian năm kỷ luật của cán bộ/nhà giáo.', array['MOET27']::text[], 'namKyLuatDn', 'Integer', 'Số nguyên', null, null),
  ('BG_00413', 'Số quyết định kỷ luật cán bộ/nhà giáo', 'Là số trên văn bản quyết định kỷ luật của cán bộ/nhà giáo.', 'Thuộc tính ghi nhận số quyết định kỷ luật của cán bộ/nhà giáo.', array['MOET27']::text[], 'soQuyetDinhKyLuatDn', 'String', 'Chuỗi ký tự', '255', null),
  ('BG_00414', 'Chủ nhiệm giỏi', 'Là nhà giáo được công nhận danh hiệu cán bộ/nhà giáo chủ nhiệm lớp giỏi trong các hội thi của ngành giáo dục.', 'Thuộc tính thể hiện danh hiệu chủ nhiệm giỏi của cán bộ/nhà giáo.', array['MOET27']::text[], 'chuNhiemGioi', 'String', 'Chuỗi ký tự', '255', null),
  ('BG_00415', 'Phụ trách đội giỏi', 'Là cán bộ/nhà giáo được cấp danh hiệu Tổng phụ trách Đội giỏi.', 'Thuộc tính thể hiện danh hiệu Tổng phụ trách Đội giỏi của cán bộ/nhà giáo.', array['MOET27']::text[], 'phuTrachDoiGioi', 'String', 'Chuỗi ký tự', '255', null),
  ('BG_00416', 'Thông tin ký số của cơ sở giáo dục', 'Là thông tin chữ ký số của cơ sở giáo dục hoặc cơ quan quản lý giáo dục được sử dụng để chính thức phát hành và xác nhận giá trị pháp lý của học bạ số, văn bằng số đối với người học theo thẩm quyền của cơ sở giáo dục hoặc cơ quan có thẩm quyền. Cấu trúc bao gồm: Chữ ký số (Signature): Thẻ gốc biểu diễn thông tin chữ ký. Signature/SignedInfo: Dữ liệu được ký số và thuật toán mã hóa (base64). Signature/SignatureValue: Giá trị của chữ ký số (mã hóa base64). Signature/KeyInfo/X509 Data/X509Certificate: Thông tin chứng thư chữ ký số (X.509) chứa khóa công khai để xác thực. SigningTime: Thời điểm thực hiện ký số, định dạng YYYY-MMDDThh:mm:ss', 'Đối tượng tham chiếu mô tả thông tin thông tin ký số của cơ sở giáo dục; dùng liên kết, tham chiếu trong các nghiệp vụ quản lý giáo dục và đào tạo.', array['MOET28']::text[], 'thongTinKySoCuaCsgd', 'Object', 'Đối tượng', null, null),
  ('BG_00417', 'Sở giáo dục và đào tạo', 'Là các cơ quan chuyên môn thuộc các Ủy ban nhân dân cấp tỉnh/thành phố. Cơ quan này chịu trách nhiệm quản lý nhà nước về giáo dục tại địa phương đó.', 'Thuộc tính phân loại sở giáo dục và đào tạo của cơ quan quản lý giáo dục.', array['MOET29']::text[], 'sgddt', 'Enumeration', 'Danh mục liệt kê', null, null),
  ('BG_00418', 'Cơ quan chủ quản cơ sở đào tạo', 'Là đơn vị đại diện Nhà nước thực hiện chức năng quản lý, chỉ đạo và giám sát cơ sở đào tạo', 'Thuộc tính mô tả cơ quan chủ quản cơ sở đào tạo.', array['MOET29']::text[], 'donViChuQuan', 'String', 'Chuỗi ký tự', '255', null),
  ('BG_00419', 'Mã định danh cơ sở giáo dục', 'Là mã định danh duy nhất của một cơ sở giáo dục trong hệ thống quản lý giáo dục, được cơ quan quản lý giáo dục ban hành hoặc cấp phát để phục vụ việc quản lý, trao đổi và liên thông dữ liệu về cơ sở giáo dục.', 'Trường dữ liệu định danh dùng để nhận diện duy nhất tổ chức; phục vụ tra cứu, tham chiếu và liên thông dữ liệu giữa các hệ thống quản lý giáo dục.', array['MOET30']::text[], 'truongId', 'String', 'Chuỗi ký tự', '15', null),
  ('BG_00420', 'Mã định danh tổ chức', 'Mã định danh duy nhất được cấp cho cơ quan nhà nước, tổ chức, doanh nghiệp trong Hệ thống thông tin định danh và xác thực điện tử quốc gia. Khác với mã số thuế ở chỗ áp dụng cho cả các tổ chức không hoạt động kinh doanh (cơ quan nhà nước, tổ chức chính trị-xã hội).', 'Trường dữ liệu định danh dùng để nhận diện duy nhất cơ quan, tổ chức do Bộ Công An cấp; phục vụ tra cứu, tham chiếu và liên thông dữ liệu giữa các CSDL quốc gia.', array['MOET30']::text[], 'maDinhDanhToChuc', 'String', 'Chuỗi ký tự', '35', 'CDE-TC-002'),
  ('BG_00421', 'Tên cơ sở giáo dục', 'Là tên chính thức của cơ sở giáo dục được xác định trong quyết định thành lập hoặc cho phép thành lập của cơ quan có thẩm quyền.', 'Thuộc tính ghi nhận tên cơ sở giáo dục.', array['MOET30']::text[], 'tenCsgd', 'String', 'Chuỗi ký tự', '200', null),
  ('BG_00422', 'Cấp học', 'Là các giai đoạn đào tạo trong hệ thống giáo dục quốc dân, được phân chia dựa trên độ tuổi, trình độ và mục tiêu giáo dục, bao gồm mầm non, tiểu học, trung học cơ sở, trung học phổ thông, giáo dục nghề nghiệp và đại học.', 'Thuộc tính phân loại cấp học của cơ sở giáo dục, trung tâm, cơ sở đào tạo.', array['MOET30']::text[], 'capHoc', 'Enumeration', 'Danh mục liệt kê', null, null),
  ('BG_00423', 'Nhóm cấp học', 'Là phân loại chi tiết cấp học của cơ sở giáo dục.', 'Thuộc tính phân loại nhóm cấp học của cơ sở giáo dục, trung tâm, cơ sở đào tạo.', array['MOET30']::text[], 'nhomCapHoc', 'Enumeration', 'Danh mục liệt kê', null, null),
  ('BG_00424', 'Số quyết định thành lập cơ sở giáo dục', 'Là số quyết định thành lập được xác định trong quyết định thành lập hoặc cho phép thành lập của cơ quan có thẩm quyền.', 'Thuộc tính ghi nhận số quyết định thành lập cơ sở giáo dục.', array['MOET30']::text[], 'soQdThanhLap', 'String', 'Chuỗi ký tự', '50', null),
  ('BG_00425', 'Ngày tháng năm thành lập cơ sở giáo dục', 'Là thời điểm cơ sở giáo dục được cơ quan có thẩm quyền ban hành quyết định thành lập hoặc cho phép thành lập.', 'Thuộc tính ghi nhận mốc thời gian ngày tháng năm thành lập cơ sở giáo dục của cơ sở giáo dục, trung tâm, cơ sở đào tạo.', array['MOET30']::text[], 'ngayThanhLapCsgd', 'Date', 'Ngày tháng', '10', 'CDE-TG-001'),
  ('BG_00426', 'Tỉnh/Thành phố cơ sở giáo dục', 'Là thông tin chỉ địa giới hành chính (tỉnh hoặc thành phố trực thuộc Trung ương) nơi cơ sở giáo dục đang đóng trụ sở và hoạt động.', 'Thuộc tính cho biết Tỉnh/Thành phố nơi cơ sở giáo dục đang đóng trụ sở và hoạt động.', array['MOET30']::text[], 'tinhThanhCsgd', 'Enumeration', 'Danh mục liệt kê', null, 'CDE-DC-001'),
  ('BG_00427', 'Xã/Phường/Đặc khu cơ sở giáo dục', 'Là thông tin chỉ địa giới hành chính (xã/phường) nơi cơ sở giáo dục đang đóng trụ sở và hoạt động.', 'Thuộc tính cho biết Xã/Phường/Đặc khu nơi cơ sở giáo dục đang đóng trụ sở và hoạt động.', array['MOET30']::text[], 'xaPhuongCsgd', 'Enumeration', 'Danh mục liệt kê', null, 'CDE-DC-003'),
  ('BG_00428', 'Địa chỉ chi tiết cơ sở giáo dục', 'Là thông tin chỉ địa giới hành chính (địa chỉ chi tiết số, tên đường) nơi cơ sở giáo dục đang đóng trụ sở và hoạt động.', 'Thuộc tính mô tả thông tin địa chỉ chi tiết nơi cơ sở giáo dục đang đóng trụ sở và hoạt động.', array['MOET30']::text[], 'diaChiCsgd', 'String', 'Chuỗi ký tự', '200', null),
  ('BG_00429', 'Loại hình cơ sở giáo dục', 'Là phân loại cơ sở giáo dục trong hệ thống giáo dục quốc dân, bao gồm: Công lập, dân lập, tư thục, trường có yếu tố nước ngoài.', 'Thuộc tính phân loại loại hình cơ sở giáo dục của cơ sở giáo dục.', array['MOET30']::text[], 'loaiHinhCsgd', 'Enumeration', 'Danh mục liệt kê', null, null),
  ('BG_00430', 'Loại cơ sở giáo dục', 'Là thông tin dùng để phân loại các cơ sở giáo dục theo cấp học, cách thức hoạt động như: loại trường phổ thông, phổ thông dân tộc bán trú, trường chuyên biệt.', 'Thuộc tính phân loại loại cơ sở giáo dục của cơ sở giáo dục.', array['MOET30']::text[], 'loaiCsgd', 'Enumeration', 'Danh mục liệt kê', null, null),
  ('BG_00431', 'Loại vùng khó khăn', 'Là thông tin của cơ sở giáo dục đang đóng trụ sở và hoạt động tại các vùng có điều kiện kinh tế - xã hội đặc biệt khó khăn theo quy định của Chính phủ.', 'Thuộc tính phân loại loại vùng khó khăn của cơ sở giáo dục.', array['MOET30']::text[], 'vungKhoKhan', 'Enumeration', 'Danh mục liệt kê', null, null),
  ('BG_00432', 'Khu vực', 'Là thông tin phân vùng địa lý (ví dụ: Khu vực 1, Khu vực 2, Khu vực 3, Nông thôn, Miền núi) nơi cơ sở giáo dục đặt trụ sở, làm căn cứ thực hiện các chính sách giáo dục.', 'Thuộc tính phân loại khu vực của cơ sở giáo dục.', array['MOET30']::text[], 'khuVuc', 'Enumeration', 'Danh mục liệt kê', null, null),
  ('BG_00433', 'Dự án', 'Là các cơ sở giáo dục triển khai Dự án "Chương trình Đảm bảo chất lượng giáo dục trường học" (SEQAP) hoặc Dự án “Mô hình Trường học mới Việt Nam” (GPEVNEN).', 'Thuộc tính phân loại dự án của cơ sở giáo dục.', array['MOET30']::text[], 'duAn', 'Enumeration', 'Danh mục liệt kê', null, null),
  ('BG_00434', 'Số điểm trường của cơ sở giáo dục', 'Là số điểm trường thuộc quản lý của một cơ sở giáo dục', 'Thuộc tính mô tả số điểm trường của cơ sở giáo dục.', array['MOET30']::text[], 'soDiemTruong', 'String', 'Chuỗi ký tự', '10', null),
  ('BG_00435', 'Số điện thoại cơ sở giáo dục', 'Là số điện thoại liên hệ của một cơ sở giáo dục', 'Thuộc tính mô tả số điện thoại liên hệ của cơ sở giáo dục.', array['MOET30']::text[], 'dienThoaiCsgd', 'String', 'Chuỗi ký tự', '20', 'CDE-LL-001'),
  ('BG_00436', 'Email cơ sở giáo dục', 'Là địa chỉ hòm thư điện tử của một cơ sở giáo dục', 'Thuộc tính mô tả email liên hệ của cơ sở giáo dục.', array['MOET30']::text[], 'emailCsgd', 'String', 'Chuỗi ký tự', '50', 'CDE-LL-002'),
  ('BG_00437', 'Fax cơ sở giáo dục', 'Là số fax của một cơ sở giáo dục', 'Thuộc tính mô tả fax liên hệ của cơ sở giáo dục.', array['MOET30']::text[], 'faxCsgd', 'String', 'Chuỗi ký tự', '20', null),
  ('BG_00438', 'Website cơ sở giáo dục', 'Là đường dẫn trang điện tử chính thức của các cơ sở giáo dục. Đây là cầu nối số giúp các cơ sở giáo dục cung cấp thông tin chính thống và hỗ trợ công tác quản lý trong nhà trường.', 'Thuộc tính mô tả website cơ sở giáo dục.', array['MOET30']::text[], 'websiteCsgd', 'String', 'Chuỗi ký tự', '50', null),
  ('BG_00439', 'Vị trí bản đồ cơ sở giáo dục', 'Là tọa độ của cơ sở giáo dục trên bản đồ số.', 'Thuộc tính mô tả vị trí bản đồ cơ sở giáo dục.', array['MOET30']::text[], 'viTriBanDo', 'String', 'Chuỗi ký tự', '50', null),
  ('BG_00440', 'Hiệu trưởng/Giám đốc', 'Là người đứng đầu cơ sở giáo dục, chịu trách nhiệm quản lý, điều hành các hoạt động của nhà trường, do cơ quan có thẩm quyền bổ nhiệm hoặc công nhận.', 'Thuộc tính mô tả tên Hiệu trưởng/Giám đốc của cơ sở giáo dục.', array['MOET30']::text[], 'hieuTruong', 'String', 'Chuỗi ký tự', '100', null),
  ('BG_00441', 'Điện thoại hiệu trưởng/giám đốc', 'Là số điện thoại của người đứng đầu tại cơ sở giáo dục', 'Thuộc tính mô tả điện thoại liên hệ của hiệu trưởng/giám đốc của cơ sở giáo dục.', array['MOET30']::text[], 'dtHieuTruong', 'String', 'Chuỗi ký tự', '10', null),
  ('BG_00442', 'Chi bộ Đảng cơ sở giáo dục', 'Là tổ chức cơ sở của Đảng Cộng sản Việt Nam được thành lập trong cơ sở giáo dục, có nhiệm vụ lãnh đạo đảng viên và tham gia định hướng các hoạt động chính trị, tư tưởng trong nhà trường theo quy định của Đảng.', 'Thuộc tính đánh dấu cơ sở giáo dục có thành lập chi bộ Đảng (giá trị có/không).', array['MOET30']::text[], 'isCoChiBoDang', 'Boolean', 'Đúng/Sai', '1', null),
  ('BG_00443', 'Cơ sở giáo dục quốc tế', 'Là cơ sở giáo dục có áp dụng chương trình giảng dạy xây dựng trên nền tảng giáo dục toàn cầu (như IB, Cambridge, Mỹ, Anh, Úc)', 'Thuộc tính đánh dấu cơ sở giáo dục quốc tế của cơ sở giáo dục, trung tâm, cơ sở đào tạo (giá trị có/không).', array['MOET30']::text[], 'isTruongQuocTe', 'Boolean', 'Đúng/Sai', '1', null),
  ('BG_00444', 'Có người học khuyết tật', 'Là thông tin xác nhận việc cơ sở giáo dục có đào tạo học sinh khuyết tật.', 'Thuộc tính đánh dấu có người học khuyết tật của người học (giá trị có/không).', array['MOET30']::text[], 'isHocSinhKhuyetTat', 'Boolean', 'Đúng/Sai', '1', null),
  ('BG_00445', 'Có người học bán trú', 'Là thông tin xác nhận việc cơ sở giáo dục có tổ chức ăn, nghỉ trong ngày tại cơ sở giáo dục theo chế độ bán trú, nhưng không ở lại qua đêm tại trường.', 'Thuộc tính đánh dấu có người học bán trú của người học (giá trị có/không).', array['MOET30']::text[], 'isHocSinhBanTru', 'Boolean', 'Đúng/Sai', '1', null),
  ('BG_00446', 'Có học kỹ năng sống', 'Là thông tin xác nhận việc cơ sở giáo dục có chương trình học kỹ năng sống nhằm trau dồi các hành vi, nhận thức và năng lực tâm lý xã hội để thích nghi, ứng phó hiệu quả với các thách thức cho học sinh trong cuộc sống hàng ngày.', 'Thuộc tính đánh dấu có học kỹ năng sống của cơ sở giáo dục, trung tâm, cơ sở đào tạo (giá trị có/không).', array['MOET30']::text[], 'isKyNangSongGdxh', 'Boolean', 'Đúng/Sai', '1', null),
  ('BG_00447', 'Có người học nội trú', 'Là thông tin xác nhận việc cơ sở giáo dục có tổ chức ăn, nghỉ trong ngày tại cơ sở giáo dục theo chế độ nội trú qua đêm tại trường.', 'Thuộc tính đánh dấu có người học nội trú của người học (giá trị có/không).', array['MOET30']::text[], 'isHocSinhNoiTru', 'Boolean', 'Đúng/Sai', '1', null),
  ('BG_00448', 'Vùng đặc biệt khó khăn', 'Là thông tin xác nhận việc cơ sở giáo dục có trụ sở hoạt động tại những vùng đặc biệt khó khăn theo quy định của pháp luật.', 'Thuộc tính đánh dấu vùng đặc biệt khó khăn của cơ sở giáo dục, trung tâm, cơ sở đào tạo (giá trị có/không).', array['MOET30']::text[], 'isVungDacBietKhoKhan', 'Boolean', 'Đúng/Sai', '1', null),
  ('BG_00449', 'Vùng', 'Là mã định danh được sử dụng để xác định một khu vực địa lý hoặc khu vực hành chính theo hệ thống phân loại của cơ quan quản lý.', 'Thuộc tính phân loại vùng của tổ chức; chuẩn hóa danh mục, phục vụ thống kê và báo cáo trong quản lý giáo dục.', array['MOET30']::text[], 'vung', 'Enumeration', 'Danh mục liệt kê', '20', null),
  ('BG_00450', 'Có học sinh học nghề', 'Là học sinh tham gia học các môn hoặc chương trình giáo dục nghề nghiệp nhằm trang bị kỹ năng nghề cơ bản trong quá trình học phổ thông.', 'Thuộc tính đánh dấu có học sinh học nghề của người học (giá trị có/không).', array['MOET30']::text[], 'coHsHocNghe', 'Boolean', 'Đúng/Sai', null, null),
  ('BG_00451', 'Mã điểm trường cơ sở giáo dục', 'Là mã định danh của một điểm trường trực thuộc cơ sở giáo dục dùng để quản lý và phân biệt giữa các địa điểm tổ chức dạy học của cơ sở giáo dục.', 'Trường dữ liệu định danh dùng để nhận diện duy nhất cơ sở giáo dục, trung tâm, cơ sở đào tạo; phục vụ tra cứu, tham chiếu và liên thông dữ liệu giữa các hệ thống quản lý giáo dục.', array['MOET30']::text[], 'diemTruongId', 'String', 'Chuỗi ký tự', '15', null),
  ('BG_00452', 'Tên điểm trường', 'Là tên chính thức của điểm trường được xác định trong quyết định thành lập hoặc cho phép thành lập của cơ quan có thẩm quyền.', 'Thuộc tính ghi nhận tên điểm trường; thuộc nhóm dữ liệu về cơ sở giáo dục, trung tâm, cơ sở đào tạo.', array['MOET30']::text[], 'tenDiemTruong', 'String', 'Chuỗi ký tự', '200', null),
  ('BG_00453', 'Địa chỉ chi tiết điểm trường', 'Là địa chỉ của điểm trường được xác định trong quyết định thành lập hoặc cho phép thành lập của cơ quan có thẩm quyền.', 'Thuộc tính mô tả thông tin địa chỉ, vị trí hành chính; thuộc nhóm dữ liệu về cơ sở giáo dục, trung tâm, cơ sở đào tạo.', array['MOET30']::text[], 'diaChi', 'String', 'Chuỗi ký tự', '250', null),
  ('BG_00454', 'Tỉnh/Thành phố điểm trường', 'Là địa chỉ hành chính (tỉnh/thành phố) của điểm trường được xác định trong quyết định thành lập hoặc cho phép thành lập của cơ quan có thẩm quyền.', 'Thuộc tính phân loại tỉnh/Thành phố điểm trường; thuộc nhóm dữ liệu về cơ sở giáo dục, trung tâm, cơ sở đào tạo; chuẩn hóa danh mục, phục vụ thống kê và báo cáo trong quản lý giáo dục.', array['MOET30']::text[], 'tinhTpDiemTruong', 'Enumeration', 'Danh mục liệt kê', null, 'CDE-DC-001'),
  ('BG_00455', 'Xã/Phường/Đặc khu điểm trường', 'Là địa chỉ hành chính (xã/phường/đặc khu) của điểm trường được xác định trong quyết định thành lập hoặc cho phép thành lập của cơ quan có thẩm quyền.', 'Thuộc tính phân loại xã/Phường/Đặc khu điểm trường; thuộc nhóm dữ liệu về cơ sở giáo dục, trung tâm, cơ sở đào tạo; chuẩn hóa danh mục, phục vụ thống kê và báo cáo trong quản lý giáo dục.', array['MOET30']::text[], 'xaPhuongDiemTruong', 'Enumeration', 'Danh mục liệt kê', null, 'CDE-DC-003'),
  ('BG_00456', 'Khoảng cách điểm trường chính', 'Là khoảng cách theo km từ điểm trường đến điểm trường chính.', 'Thuộc tính định lượng phản ánh khoảng cách điểm trường chính của cơ sở giáo dục, trung tâm, cơ sở đào tạo; phục vụ thống kê, tổng hợp và đánh giá.', array['MOET30']::text[], 'khoangCachDiemTruongChinh', 'Decimal', 'Số thập phân', null, null),
  ('BG_00457', 'Phương tiện có thể đi lại đến điểm trường', 'Là phương tiện có thể di chuyển từ điểm trường đến điểm trường chính.', 'Thuộc tính mô tả phương tiện có thể đi lại đến điểm trường; thuộc nhóm dữ liệu về cơ sở giáo dục, trung tâm, cơ sở đào tạo.', array['MOET30']::text[], 'phuongTienCoTheDiLai', 'String', 'Chuỗi ký tự', '50', null),
  ('BG_00458', 'Diện tích điểm trường', 'Là diện tích được tính dựa trên tổng diện tích khu đất xây dựng điểm trường.', 'Thuộc tính định lượng phản ánh diện tích điểm trường; thuộc nhóm dữ liệu về cơ sở giáo dục, trung tâm, cơ sở đào tạo; phục vụ thống kê, tổng hợp và đánh giá.', array['MOET30']::text[], 'dienTich', 'Decimal', 'Số thập phân', null, null),
  ('BG_00459', 'Giáo dục về giới tính, xâm hại, bạo lực', 'Là cơ sở giáo dục có nội dung giáo dục để trang bị kiến thức, thái độ và kỹ năng toàn diện cho người học về giới tính, xâm hại và bạo lực.', 'Thuộc tính đánh dấu giáo dục về giới tính, xâm hại, bạo lực của cơ sở giáo dục, trung tâm, cơ sở đào tạo (giá trị có/không).', array['MOET30']::text[], 'isGioiTinhXamHaiBaoLuc', 'Boolean', 'Đúng/Sai', '1', null),
  ('BG_00460', 'Trung tâm giáo dục nghề nghiệp - giáo dục thường xuyên', 'Là cơ sở giáo dục có chức năng kết hợp giáo dục nghề nghiệp và giáo dục thường xuyên', 'Thuộc tính đánh dấu cơ sở giáo dục là trung tâm giáo dục nghề nghiệp - giáo dục thường xuyên', array['MOET30']::text[], 'isTtGdtxHuongNghiepNghe', 'Boolean', 'Đúng/Sai', '1', null),
  ('BG_00461', 'Tên cơ sở đào tạo', 'Là tên chính thức của cơ sở đào tạo được xác định trong quyết định thành lập hoặc cho phép thành lập của cơ quan có thẩm quyền.', 'Thuộc tính ghi nhận tên cơ sở đào tạo của cơ sở giáo dục, trung tâm, cơ sở đào tạo.', array['MOET30']::text[], 'tenTruong', 'String', 'Chuỗi ký tự', '250', null),
  ('BG_00462', 'Tỉnh/Thành phố cơ sở đào tạo', 'Là Tỉnh/Thành phố của cơ sở đào tạo được xác định trong quyết định thành lập hoặc cho phép thành lập của cơ quan có thẩm quyền.', 'Thuộc tính mô tả tỉnh/Thành phố cơ sở đào tạo của cơ sở giáo dục, trung tâm, cơ sở đào tạo.', array['MOET30']::text[], 'diaDanhCapVbcc', 'String', 'Chuỗi ký tự', '50', null),
  ('BG_00463', 'Trình độ đào tạo', 'Là trình độ đào tạo của người học sau khi hoàn thành chương trình đào tạo theo khung trình độ quốc gia Việt Nam.', 'Thuộc tính mô tả trình độ đào tạo của chương trình giáo dục và đào tạo.', array['MOET30']::text[], 'trinhDoTheoKhung', 'String', 'Chuỗi ký tự', '150', null),
  ('BG_00464', 'Bậc trình độ', 'Là bậc trình độ đào tạo của người học sau khi hoàn thành chương trình đào tạo theo khung trình độ quốc gia Việt Nam.', 'Thuộc tính mô tả bậc trình độ của chương trình giáo dục và đào tạo.', array['MOET30']::text[], 'bacTrinhDoTheoKhung', 'String', 'Chuỗi ký tự', '150', null),
  ('BG_00465', 'Dạy kỹ năng ngoại ngữ', 'Là thông tin xác nhận việc cơ sở giáo dục có tổ chức dạy ngoại ngữ.', 'Thuộc tính đánh dấu dạy kỹ năng ngoại ngữ của cơ sở giáo dục (giá trị có/không).', array['MOET30']::text[], 'dayKyNangNgoaiNgu', 'Boolean', 'Đúng/Sai', '1', null),
  ('BG_00466', 'Dạy kỹ năng ứng dụng CNTT', 'Là thông tin xác nhận việc cơ sở giáo dục có tổ chức dạy kỹ năng ứng dụng CNTT.', 'Thuộc tính đánh dấu dạy kỹ năng ứng dụng CNTT của cơ sở giáo dục (giá trị có/không).', array['MOET30']::text[], 'dayUngDungCntt', 'Boolean', 'Đúng/Sai', '1', null),
  ('BG_00467', 'Có vốn đầu tư nước ngoài', 'Là thông tin xác nhận việc cơ sở giáo dục có vốn đầu tư nước ngoài.', 'Thuộc tính đánh dấu có vốn đầu tư nước ngoài của cơ sở giáo dục (giá trị có/không).', array['MOET30']::text[], 'isTtNnCoVonNuocNgoai', 'Boolean', 'Đúng/Sai', '1', null),
  ('BG_00468', 'Tên tiếng anh cơ sở đào tạo', 'Là tên của cơ sở đào tạo được thể hiện bằng tiếng Anh, dùng trong giao dịch quốc tế, hợp tác đào tạo, nghiên cứu khoa học và các hoạt động đối ngoại của cơ sở đào tạo', 'Thuộc tính ghi nhận tên tiếng anh cơ sở đào tạo của cơ sở giáo dục.', array['MOET30']::text[], 'tenTiengAnhCsgd', 'String', 'Chuỗi ký tự', '255', null),
  ('BG_00469', 'Hình thức thành lập', 'Là cách thức cơ sở đào tạo được thành lập theo quy định của pháp luật', 'Thuộc tính mô tả hình thức thành lập của cơ sở giáo dục.', array['MOET30']::text[], 'hinhThucThanhLap', 'String', 'Chuỗi ký tự', '255', null),
  ('BG_00470', 'Số quyết định chuyển đổi loại hình cơ sở đào tạo', 'Là số quyết định do cơ quan có thẩm quyền ban hành ghi nhận việc chuyển đổi loại hình hoạt động của cơ sở đào tạo.', 'Thuộc tính ghi nhận số quyết định chuyển đổi loại hình cơ sở đào tạo của cơ sở giáo dục.', array['MOET30']::text[], 'soQdChuyenDoiLoaiHinh', 'String', 'Chuỗi ký tự', '50', null),
  ('BG_00471', 'Ngày quyết định chuyển đổi loại hình cơ sở đào tạo', 'Là ngày quyết định do cơ quan có thẩm quyền ban hành ghi nhận việc chuyển đổi loại hình hoạt động của cơ sở đào tạo.', 'Thuộc tính ghi nhận mốc thời gian ngày quyết định chuyển đổi loại hình cơ sở đào tạo của cơ sở giáo dục.', array['MOET30']::text[], 'ngayQdChuyenDoi', 'Date', 'Ngày tháng', '10', 'CDE-TG-001'),
  ('BG_00472', 'Tên Đại học mà cơ sở là đơn vị trực thuộc', 'Là tên của đại học hoặc tổ chức quản lý cấp trên mà cơ sở đào tạo trực thuộc, chịu sự quản lý về tổ chức, chuyên môn và hoạt động theo quy định của pháp luật.', 'Thuộc tính ghi nhận tên Đại học mà cơ sở giáo dục là đơn vị trực thuộc.', array['MOET30']::text[], 'tenDonViCha', 'String', 'Chuỗi ký tự', '255', null),
  ('BG_00473', 'Có đào tạo Dự bị đại học', 'Là việc các cơ sở giáo dục có chương trình học dành cho học sinh đã tốt nghiệp THPT nhưng chưa đủ điều kiện (về điểm số hoặc kiến thức) để bước vào hệ đại học chính quy.', 'Thuộc tính đánh dấu có đào tạo Dự bị đại học của cơ sở giáo dục (giá trị có/không).', array['MOET30']::text[], 'isDuBiDaiHoc', 'Boolean', 'Đúng/Sai', '1', null),
  ('BG_00474', 'Có đào tạo GV trình độ trung cấp', 'Là việc các cơ sở giáo dục đại học/học viện mở ngành tuyển sinh và cấp bằng hệ trung cấp sư phạm hoặc trung cấp chuyên nghiệp', 'Thuộc tính đánh dấu có đào tạo GV trình độ trung cấp của cơ sở giáo dục (giá trị có/không).', array['MOET30']::text[], 'isGvTrungCap', 'Boolean', 'Đúng/Sai', '1', null),
  ('BG_00475', 'Có đào tạo GV trình độ cao đẳng', 'Là mô hình các cơ sở giáo dục (thường là các trường đại học sư phạm) được cấp phép tuyển sinh và đào tạo hệ Cao đẳng (chủ yếu là ngành Giáo dục Mầm non).', 'Thuộc tính đánh dấu có đào tạo GV trình độ cao đẳng của cơ sở giáo dục (giá trị có/không).', array['MOET30']::text[], 'isGvCaoDang', 'Boolean', 'Đúng/Sai', '1', null),
  ('BG_00476', 'Có đào tạo trình độ đại học', 'Là mô hình các cơ sở giáo dục có đào tạo trình độ đại học.', 'Thuộc tính đánh dấu có đào tạo trình độ đại học của cơ sở giáo dục (giá trị có/không).', array['MOET30']::text[], 'isDaiHoc', 'Boolean', 'Đúng/Sai', '1', null),
  ('BG_00477', 'Có đào tạo trình độ thạc sĩ', 'Là mô hình các cơ sở giáo dục có đào tạo trình độ thạc sĩ.', 'Thuộc tính đánh dấu có đào tạo trình độ thạc sĩ của cơ sở giáo dục (giá trị có/không).', array['MOET30']::text[], 'isThacSi', 'Boolean', 'Đúng/Sai', '1', null),
  ('BG_00478', 'Có đào tạo trình độ tiến sĩ', 'Là mô hình các cơ sở giáo dục có đào tạo trình độ tiến sĩ.', 'Thuộc tính đánh dấu có đào tạo trình độ tiến sĩ của cơ sở giáo dục (giá trị có/không).', array['MOET30']::text[], 'isTienSi', 'Boolean', 'Đúng/Sai', '1', null),
  ('BG_00479', 'Có hoạt động không lợi nhuận', 'Là mô hình mà mọi khoản thu (học phí, tài trợ, nghiên cứu) chỉ được dùng để duy trì và phát triển cơ sở giáo dục.', 'Thuộc tính đánh dấu có hoạt động không lợi nhuận của cơ sở giáo dục (giá trị có/không).', array['MOET30']::text[], 'isLoiNhuan', 'Boolean', 'Đúng/Sai', '1', null),
  ('BG_00480', 'Số quyết định cấp phép hoạt động cơ sở giáo dục', 'Là số quyết định được xác định trong văn bản cấp phép hoạt động cơ sở giáo dục do cơ quan có thẩm quyền ban hành.', 'Thuộc tính ghi nhận số quyết định cấp phép hoạt động cơ sở giáo dục.', array['MOET30']::text[], 'soQdCapPhepHoatDong', 'String', 'Chuỗi ký tự', '50', null),
  ('BG_00481', 'Ngày quyết định cấp phép hoạt động cơ sở giáo dục', 'Là ngày ghi trên số quyết định cấp phép hoạt động cơ sở đào tạo do cơ quan có thẩm quyền ban hành.', 'Thuộc tính ghi nhận mốc thời gian ngày quyết định cấp phép hoạt động cơ sở giáo dục của cơ sở giáo dục.', array['MOET30']::text[], 'ngayDuocCapPhepHoatDong', 'Date', 'Ngày tháng', '10', 'CDE-TG-001'),
  ('BG_00482', 'Có đào tạo theo tín chỉ', 'Là thông tin xác nhận việc cơ sở giáo dục có phương thức đào tạo theo tín chỉ.', 'Thuộc tính đánh dấu có đào tạo theo tín chỉ của cơ sở giáo dục (giá trị có/không).', array['MOET30']::text[], 'isTinChi', 'Boolean', 'Đúng/Sai', '1', null),
  ('BG_00483', 'Năm bắt đầu đào tạo theo tín chỉ', 'Là năm cơ sở đào tạo chính thức triển khai áp dụng phương thức đào tạo theo tín chỉ theo quy định và được cơ quan có thẩm quyền cho phép.', 'Thuộc tính ghi nhận mốc thời gian năm bắt đầu đào tạo theo tín chỉ của cơ sở giáo dục.', array['MOET30']::text[], 'namBatDauDaoTaoTheoTinChi', 'Date', 'Ngày tháng', '10', null),
  ('BG_00484', 'Tên cũ của cơ sở giáo dục', 'Là tên gọi trước đây của cơ sở giáo dục trước khi thực hiện đổi tên.', 'Thuộc tính ghi nhận tên cũ của cơ sở giáo dục.', array['MOET30']::text[], 'tenTruongCu', 'String', 'Chuỗi ký tự', '100', null),
  ('BG_00485', 'Tên tiếng anh cũ của cơ sở đào tạo', 'Là tên tiếng anh trước đây của cơ sở đào tạo trước khi thực hiện đổi tên.', 'Thuộc tính ghi nhận tên tiếng anh cũ của cơ sở giáo dục.', array['MOET30']::text[], 'tenTruongCuTiengAnh', 'String', 'Chuỗi ký tự', '100', null),
  ('BG_00486', 'Số quyết định đổi tên cơ sở giáo dục', 'Là số quyết định được xác định trong văn bản đổi tên cơ sở giáo dục do cơ quan có thẩm quyền ban hành.', 'Thuộc tính ghi nhận số quyết định đổi tên cơ sở giáo dục.', array['MOET30']::text[], 'soQdDoiTen', 'String', 'Chuỗi ký tự', '50', null),
  ('BG_00487', 'Ngày quyết định đổi tên cơ sở giáo dục', 'Là ngày ghi trên số quyết định cấp phép hoạt động cơ sở giáo dục do cơ quan có thẩm quyền ban hành.', 'Thuộc tính ghi nhận mốc thời gian ngày quyết định đổi tên cơ sở giáo dục.', array['MOET30']::text[], 'ngayQdDoiTen', 'Date', 'Ngày tháng', '10', 'CDE-TG-001'),
  ('BG_00488', 'Đầu mối liên hệ cơ sở đào tạo', 'Là về cá nhân, bộ phận hoặc đơn vị chịu trách nhiệm tiếp nhận và xử lý các thông tin liên hệ, trao đổi giữa cơ sở đào tạo với tổ chức, cá nhân bên ngoài.', 'Thuộc tính cung cấp thông tin đầu mối liên hệ của cơ sở giáo dục.', array['MOET30']::text[], 'dauMoiLienHeCsdt', 'Enumeration', 'Danh mục liệt kê', null, null),
  ('BG_00489', 'Tên cá nhân tổ chức góp vốn', 'Là tên của cá nhân hoặc tổ chức tham gia góp vốn vào cơ sở giáo dục theo quy định của pháp luật, được ghi nhận trong hồ sơ thành lập hoặc hoạt động của cơ sở giáo dục.', 'Thuộc tính ghi nhận tên cá nhân tổ chức góp vốn của cơ sở giáo dục.', array['MOET30']::text[], 'tenToChucCaNhan', 'String', 'Chuỗi ký tự', '100', null),
  ('BG_00490', 'Tỷ lệ góp vốn', 'Là tỷ lệ tính bằng % (phần trăm) của phần vốn mà từng chủ sở hữu đóng góp so với vốn điều lệ của cơ sở giáo dục.', 'Thuộc tính định lượng phản ánh tỷ lệ góp vốn của cơ sở giáo dục.', array['MOET30']::text[], 'tyLeGopVon', 'Decimal', 'Số thập phân', '-18.2', null),
  ('BG_00491', 'Ngày góp vốn', 'Là thời điểm cá nhân hoặc tổ chức thực hiện việc góp vốn vào cơ sở giáo dục.', 'Thuộc tính ghi nhận mốc thời gian ngày góp vốn của cá nhân, tổ chức góp vốn.', array['MOET30']::text[], 'ngayGopVon', 'Date', 'Ngày tháng', '10', 'CDE-TG-001'),
  ('BG_00492', 'Số quyết định hội đồng khoa học', 'Là số quyết định được xác định trong văn bản thành lập hội đồng khoa học do cơ quan có thẩm quyền ban hành.', 'Thuộc tính ghi nhận số quyết định hội đồng khoa học của cơ sở giáo dục.', array['MOET30']::text[], 'soQdThanhLapHdKhoaHoc', 'String', 'Chuỗi ký tự', '50', null),
  ('BG_00493', 'Ngày quyết định hội đồng khoa học', 'Là ngày ghi trên số quyết định thành lập hội đồng khoa học do cơ quan có thẩm quyền ban hành.', 'Thuộc tính ghi nhận mốc thời gian ngày quyết định hội đồng khoa học của cơ sở giáo dục.', array['MOET30']::text[], 'ngayQdThanhLapHdKhoaHoc', 'Date', 'Ngày tháng', '10', 'CDE-TG-001'),
  ('BG_00494', 'Số quyết định thành lập ban kiểm soát', 'Là số quyết định được xác định trong văn bản thành lập ban kiểm soát do cơ quan có thẩm quyền ban hành.', 'Thuộc tính ghi nhận số quyết định thành lập ban kiểm soát của cơ sở giáo dục.', array['MOET30']::text[], 'soQdThanhLapBanKiemSoat', 'String', 'Chuỗi ký tự', '50', null),
  ('BG_00495', 'Ngày quyết định thành lập ban kiểm soát', 'Là ngày ghi trên số quyết định thành lập ban kiểm soát do cơ quan có thẩm quyền ban hành.', 'Thuộc tính ghi nhận mốc thời gian ngày quyết định thành lập ban kiểm soát của cơ sở giáo dục.', array['MOET30']::text[], 'ngayQdThanhLapBanKiemSoat', 'Date', 'Ngày tháng', '10', 'CDE-TG-001'),
  ('BG_00496', 'Số quyết định thành lập hội đồng trường', 'Là số quyết định được xác định trong văn bản thành lập hội đồng trường do cơ quan có thẩm quyền ban hành.', 'Thuộc tính ghi nhận số quyết định thành lập hội đồng trường.', array['MOET30']::text[], 'soQdThanhLapHdTruong', 'String', 'Chuỗi ký tự', '50', null),
  ('BG_00497', 'Ngày quyết định thành lập hội đồng trường', 'Là ngày ghi trên số quyết định thành lập hội đồng trường do cơ quan có thẩm quyền ban hành.', 'Thuộc tính ghi nhận mốc thời gian ngày quyết định thành lập hội đồng trường của cơ sở giáo dục.', array['MOET30']::text[], 'ngayQdThanhLapHdTruong', 'Date', 'Ngày tháng', '10', 'CDE-TG-001'),
  ('BG_00498', 'Nhiệm kỳ hội đồng trường', 'Là khoảng thời gian hoạt động của hội đồng trường được xác định trong quyết định thành lập hoặc quy chế tổ chức và hoạt động của cơ sở giáo dục.', 'Thuộc tính mô tả nhiệm kỳ hội đồng trường của cơ sở giáo dục.', array['MOET30']::text[], 'nhiemKy', 'String', 'Chuỗi ký tự', '100', null),
  ('BG_00499', 'Nhiệm kỳ hội đồng trường từ ngày', 'Là ngày bắt đầu có hiệu lực của nhiệm kỳ hội đồng trường.', 'Thuộc tính ghi nhận mốc thời gian nhiệm kỳ hội đồng trường bắt đầu từ ngày nào của cơ sở giáo dục.', array['MOET30']::text[], 'nhiemKyTu', 'Date', 'Ngày tháng', '10', 'CDE-TG-001'),
  ('BG_00500', 'Nhiệm kỳ hội đồng trường đến ngày', 'Là ngày kết thúc nhiệm kỳ của hội đồng trường.', 'Thuộc tính ghi nhận mốc thời gian nhiệm kỳ hội đồng trường đến ngày nào của cơ sở giáo dục.', array['MOET30']::text[], 'nhiemKyDen', 'Date', 'Ngày tháng', '10', 'CDE-TG-001'),
  ('BG_00501', 'Số quyết định thành lập ban giám hiệu', 'Là số quyết định được xác định trong văn bản thành lập ban giám hiệu do cơ quan có thẩm quyền ban hành.', 'Thuộc tính ghi nhận số quyết định thành lập ban giám hiệu của cơ sở giáo dục.', array['MOET30']::text[], 'soQdThanhLapBanGiamHieu', 'String', 'Chuỗi ký tự', '50', null),
  ('BG_00502', 'Ngày quyết định thành lập ban giám hiệu', 'Là ngày ghi trên số quyết định thành lập ban giám hiệu do cơ quan có thẩm quyền ban hành.', 'Thuộc tính ghi nhận mốc thời gian ngày quyết định thành lập ban giám hiệu của cơ sở giáo dục.', array['MOET30']::text[], 'ngayQdThanhLapBanGiamHieu', 'Date', 'Ngày tháng', '10', 'CDE-TG-001'),
  ('BG_00503', 'Bộ phận công tác tư vấn học đường', 'Là thông tin xác nhận việc cơ sở giáo dục có thành lập đơn vị hoặc bố trí nhân sự chuyên trách thực hiện hoạt động tư vấn tâm lý, định hướng nghề nghiệp và hỗ trợ học sinh.', 'Thuộc tính đánh dấu bộ phận công tác tư vấn học đường của cơ quan quản lý giáo dục (giá trị có/không).', array['MOET30']::text[], 'isCongTacTuVanHocDuong', 'Boolean', 'Đúng/Sai', '1', null),
  ('BG_00504', 'Mã lớp', 'Là mã định danh duy nhất của một lớp học trong cơ sở giáo dục được sử dụng để quản lý, thống kê và liên kết dữ liệu về lớp học trong 1 năm học.', 'Thuộc tính mô tả mã lớp của cơ sở giáo dục dùng để tra cứu và phân biệt với các lớp khác trong một năm học.', array['MOET31']::text[], 'maLop', 'String', 'Chuỗi ký tự', '20', null),
  ('BG_00505', 'Tên lớp', 'Là tên gọi của lớp học được sử dụng trong nhà trường để phân biệt giữa các lớp theo khối, năm học hoặc chương trình đào tạo.', 'Thuộc tính ghi nhận tên lớp của cơ sở giáo dục trong một năm học.', array['MOET31']::text[], 'tenLop', 'String', 'Chuỗi ký tự', '20', null),
  ('BG_00506', 'Khối', 'Là tên khối lớp trong cơ sở giáo dục, dùng để phân loại các lớp học theo cấp hoặc năm học (ví dụ: khối 1, khối 6…).', 'Thuộc tính tên khối của cơ sở giáo dục để biết cơ sở giáo dục đào tạo có tổ chức đào tạo các khối nào.', array['MOET31']::text[], 'khoi', 'Enumeration', 'Danh mục liệt kê', null, null),
  ('BG_00507', 'Học 2 buổi/ngày', 'Là lớp học tổ chức học buổi sáng và chiều trong một ngày, một buổi học theo chương trình chính khóa và một buổi học phụ thêm.', 'Thuộc tính đánh dấu cơ sở giáo dục có tổ chức lớp học 2 buổi/ngày.', array['MOET31']::text[], 'isDay2BuoiNgay', 'Boolean', 'Đúng/Sai', '1', null),
  ('BG_00508', 'Lớp ghép', 'Là lớp học được tổ chức với học sinh thuộc nhiều trình độ hoặc khối lớp khác nhau học chung trong một lớp, thường áp dụng tại các khu vực có số lượng học sinh ít.', 'Thuộc tính đánh dấu cơ sở giáo dục có tổ chức lớp ghép.', array['MOET31']::text[], 'isLopGhep', 'Boolean', 'Đúng/Sai', '1', null),
  ('BG_00509', 'Lớp bán trú', 'Là lớp học trong đó học sinh học tập tại trường và được tổ chức ăn, nghỉ tại trường trong ngày nhưng không ở lại qua đêm.', 'Thuộc tính đánh dấu cơ sở giáo dục có tổ chức lớp bán trú.', array['MOET31']::text[], 'isBanTru', 'Boolean', 'Đúng/Sai', '1', null),
  ('BG_00510', 'Học 5 buổi/tuần', 'Là hình thức học sinh chỉ học 5 buổi/tuần để học sinh nghỉ 2 ngày cuối tuần.', 'Thuộc tính đánh dấu cơ sở giáo dục có tổ chức lớp học 5 buổi/tuần.', array['MOET31']::text[], 'isHoc5BuoiTuan', 'Boolean', 'Đúng/Sai', '1', null),
  ('BG_00511', 'Số buổi học trên tuần', 'Là số lượng buổi học trên tuần của lớp học đó.', 'Thuộc tính phân loại số buổi học trên tuần của lớp.', array['MOET31']::text[], 'soBuoiHocTrenTuan', 'Enumeration', 'Danh mục liệt kê', null, null),
  ('BG_00512', 'Loại lớp hướng nghiệp dạy nghề', 'Là dùng để xác định lớp hướng nghiệp dạy nghề mà người học theo học giúp hiểu rõ bản thân, chọn nghề phù hợp, và cung cấp kiến thức/kỹ năng thực tế.', 'Thuộc tính phân loại loại lớp hướng nghiệp dạy nghề.', array['MOET31']::text[], 'loaiLopHuongNghiepDayNghe', 'Enumeration', 'Danh mục liệt kê', null, null),
  ('BG_00513', 'Học sinh học tiếng dân tộc', 'Là việc học tiếng nói và chữ viết của các cộng đồng dân tộc thiểu số tại Việt Nam trong các cơ sở giáo dục phổ thông.', 'Thuộc tính đánh dấu học sinh học tiếng dân tộc của người học (giá trị có/không).', array['MOET31']::text[], 'isHocSinhTiengDanToc', 'Boolean', 'Đúng/Sai', '1', null),
  ('BG_00514', 'Học song ngữ', 'Là học sinh được học phương pháp giáo dục sử dụng đồng thời hai ngôn ngữ—thường là tiếng mẹ đẻ và một ngoại ngữ (như tiếng Anh), giúp học sinh phát triển tư duy, kiến thức và khả năng giao tiếp thành thạo cả hai ngôn ngữ.', 'Thuộc tính đánh dấu học song ngữ của người học (giá trị có/không).', array['MOET31']::text[], 'isHocSongNgu', 'Boolean', 'Đúng/Sai', '1', null),
  ('BG_00515', 'Học sinh lớp bán trú', 'Là học sinh thuộc các lớp được tổ chức ăn, nghỉ tại trường trong ngày nhưng không ở lại qua đêm.', 'Thuộc tính đánh dấu học sinh lớp bán trú của người học (giá trị có/không).', array['MOET31']::text[], 'isHocSinhLopBtru', 'Boolean', 'Đúng/Sai', '1', null),
  ('BG_00516', 'Nhóm tuổi mầm non của cơ sở giáo dục', 'Là thuật ngữ chỉ các trẻ trong độ tuổi từ 03 tháng đến 06 tuổi, được phân chia thành Nhà trẻ (03 tháng – 36 tháng) và Mẫu giáo (03 – 06 tuổi) a) Nhóm trẻ (Dành cho trẻ từ 03 tháng tuổi đến 36 tháng tuổi) - Nhóm trẻ từ 03 đến 12 tháng tuổi - Nhóm trẻ từ 13 đến 24 tháng tuổi - Nhóm trẻ từ 25 đến 36 tháng tuổi b) Lớp mẫu giáo (Dành cho trẻ từ 03 tuổi đến 06 tuổi) - Lớp mẫu giáo 3 - 4 tuổi - Lớp mẫu giáo 4 - 5 tuổi - Lớp mẫu giáo 5 - 6 tuổi.', 'Thuộc tính phân loại nhóm tuổi mầm non của cơ sở giáo dục.', array['MOET31']::text[], 'nhomTuoiMn', 'Enumeration', 'Danh mục liệt kê', null, null),
  ('BG_00517', 'Lớp ghép 2 tuổi', 'Là lớp ghép 2 nhóm tuổi mầm non', 'Thuộc tính đánh dấu cơ sở giáo dục có tổ chức lớp ghép 2 tuổi.', array['MOET31']::text[], 'isLopGhep2Tuoi', 'Boolean', 'Đúng/Sai', '1', null),
  ('BG_00518', 'Lớp ghép 3 tuổi', 'Là lớp ghép 3 nhóm tuổi mầm non', 'Thuộc tính đánh dấu cơ sở giáo dục có tổ chức lớp ghép 3 tuổi (giá trị có/không).', array['MOET31']::text[], 'isLopGhep3Tuoi', 'Boolean', 'Đúng/Sai', '1', null),
  ('BG_00519', 'Lớp ghép 4 tuổi', 'Là lớp ghép 4 nhóm tuổi mầm non', 'Thuộc tính đánh dấu cơ sở giáo dục có tổ chức lớp ghép 4 tuổi (giá trị có/không).', array['MOET31']::text[], 'isLopGhep4Tuoi', 'Boolean', 'Đúng/Sai', '1', null),
  ('BG_00520', 'Số tiết học/tuần', 'Là để quản lý số tiết mà người học thuộc lớp cấp tiểu học phải học trong 1 tuần.', 'Thuộc tính phân loại cơ sở giáo dục tổ chức học với số lượng tiết học/tuần.', array['MOET31']::text[], 'soTietHocTuan', 'Enumeration', 'Danh mục liệt kê', null, null),
  ('BG_00521', 'Số tiết ngoại ngữ', 'Là để quản lý số tiết mà người học thuộc lớp phải học ngoại ngữ trong 1 tuần.', 'Thuộc tính phân loại cơ sở giáo dục tổ chức học với số lượng tiết học ngoại ngữ.', array['MOET31']::text[], 'soTietNgoaiNgu', 'Enumeration', 'Danh mục liệt kê', null, null),
  ('BG_00522', 'Lớp chuyên biệt', 'Là các lớp học dành riêng cho học sinh khuyết tật. Các lớp này áp dụng phương thức giáo dục đặc thù, được tổ chức ngay trong các trường mầm non, phổ thông hoặc trung tâm giáo dục thường xuyên để hỗ trợ học sinh hòa nhập cộng đồng.', 'Thuộc tính đánh dấu cơ sở giáo dục tổ chức lớp chuyên biệt (giá trị có/không).', array['MOET31']::text[], 'isLopChuyenBiet', 'Boolean', 'Đúng/Sai', '1', null),
  ('BG_00523', 'Có dạy nghề phổ thông', 'Là thông tin xác nhận việc cơ sở giáo dục có các hoạt động hướng nghiệp và đào tạo các kỹ năng nghề cơ bản (tin học, may, nấu ăn, điện...) cho học sinh THCS và THPT', 'Thuộc tính đánh dấu cơ sở giáo dục tổ chức lớp dạy nghề phổ thông của cơ sở giáo dục (giá trị có/không).', array['MOET31']::text[], 'isDayNghePhoThong', 'Boolean', 'Đúng/Sai', '1', null),
  ('BG_00524', 'Có lớp không chuyên', 'Là thông tin xác nhận việc cơ sở giáo dục là loại trường chuyên nhưng có tổ chức các lớp học không thuộc hệ chuyên hoặc không đào tạo theo chương trình chuyên biệt.', 'Thuộc tính đánh dấu cơ sở giáo dục là trường chuyên nhưng có tổ chức lớp không chuyên để đào tạo (giá trị có/không).', array['MOET31']::text[], 'isCoLopKhongChuyen', 'Boolean', 'Đúng/Sai', '1', null),
  ('BG_00525', 'Phân ban', 'Là hình thức tổ chức dạy học thành các lớp học theo các ban hoặc định hướng học tập khác nhau tại cơ sở giáo dục (thường là cấp THPT) theo quy định.', 'Thuộc tính phân loại phân ban của cơ sở giáo dục; chuẩn hóa danh mục, phục vụ thống kê và báo cáo trong quản lý giáo dục.', array['MOET31']::text[], 'phanBan', 'Enumeration', 'Danh mục liệt kê', null, null),
  ('BG_00526', 'Hệ chuyên', 'Là hình thức đào tạo người học có năng khiếu hoặc năng lực nổi trội ở một số môn học, được tổ chức theo chương trình chuyên biệt.', 'Thuộc tính phân loại hệ chuyên của người học; chuẩn hóa danh mục, phục vụ thống kê và báo cáo trong quản lý giáo dục.', array['MOET31']::text[], 'heChuyen', 'Enumeration', 'Danh mục liệt kê', null, null),
  ('BG_00527', 'Lớp chuyên', 'Là lớp học thuộc hệ chuyên, được tổ chức để đào tạo chuyên sâu theo môn học hoặc lĩnh vực cụ thể.', 'Thuộc tính đánh dấu lớp chuyên của cơ quan quản lý giáo dục (giá trị có/không).', array['MOET31']::text[], 'isLopChuyen', 'Boolean', 'Đúng/Sai', '1', null),
  ('BG_00528', 'Kiểu lớp', 'Là phân loại lớp học theo hình thức tổ chức của cơ sở giáo dục thường xuyên: kiểu lớp phổ cập tiểu học, GDTX cấp THCS, GDTX cấp THPT', 'Thuộc tính phân loại cơ sở giáo dục có tổ chức kiểu lớp giảng dạy nào.', array['MOET31']::text[], 'kieuLop', 'Enumeration', 'Danh mục liệt kê', null, null),
  ('BG_00529', 'Loại lớp đào tạo bồi dưỡng', 'Là phân loại lớp bồi dưỡng theo mục tiêu: nghiệp vụ, nâng cao, chuyên đề,.', 'Thuộc tính phân loại loại lớp đào tạo bồi dưỡng của quá trình đào tạo, bồi dưỡng của cán bộ/nhà giáo; chuẩn hóa danh mục, phục vụ thống kê và báo cáo trong quản lý giáo dục.', array['MOET31']::text[], 'loaiLopDaoTaoBoiDuong', 'Enumeration', 'Danh mục liệt kê', null, null),
  ('BG_00530', 'Tiếng ngôn ngữ thứ nhất', 'Là ngôn ngữ mẹ đẻ hoặc ngôn ngữ sử dụng chính của cán bộ/giáo viên tham gia giảng dạy tại trung tâm khác.', 'Thuộc tính phân loại tiếng ngôn ngữ thứ nhất mà cán bộ/nhà giáo sử dụng để giảng dạy trong cơ sở giáo dục.', array['MOET31']::text[], 'tiengNgonNguThuNhat', 'Enumeration', 'Danh mục liệt kê', null, null),
  ('BG_00531', 'Hình thức học tập', 'Là việc phân loại hình thức tham gia học tập của người học.', 'Thuộc tính phân loại cơ sở giáo dục có tổ chức các hình thức học tập gì để người học tham gia học.', array['MOET31']::text[], 'hinhThucHocTap', 'Enumeration', 'Danh mục liệt kê', null, null),
  ('BG_00532', 'Chương trình giáo dục vệ sinh đôi tay', 'Là thông tin xác nhận việc cơ sở giáo dục có triển khai các hoạt động truyền thông, giáo dục nhằm nâng cao nhận thức và rèn luyện kỹ năng vệ sinh cá nhân cho người học.', 'Thuộc tính đánh dấu cơ sở giáo dục có tổ chức chương trình giáo dục vệ sinh đôi tay (giá trị có/không).', array['MOET31']::text[], 'isCtGdvsDoiTay', 'Boolean', 'Đúng/Sai', '1', null),
  ('BG_00533', 'Thiết bị dạy học tối thiểu', 'Là thông tin về tình trạng trang bị các phương tiện, dụng cụ và thiết bị dạy học thuộc danh mục tối thiểu bắt buộc theo quy định của Bộ Giáo dục và Đào tạo.', 'Thuộc tính mô tả thiết bị dạy học tối thiểu của cơ sở vật chất, thiết bị của cơ sở giáo dục.', array['MOET32']::text[], 'thietBiDayHocToiThieu', 'String', 'Chuỗi ký tự', '1', null),
  ('BG_00534', 'Máy vi tính phục vụ quản lý và giáo dục', 'Là thiết bị máy tính được trang bị tại cơ sở giáo dục nhằm hỗ trợ công tác quản lý, giảng dạy và tổ chức các hoạt động học tập cho trẻ hoặc học sinh', 'Thuộc tính đánh dấu máy vi tính phục vụ quản lý và giáo dục của cơ sở giáo dục (giá trị có/không).', array['MOET32']::text[], 'isSuDungMayTinhDayHoc', 'Boolean', 'Đúng/Sai', '1', null),
  ('BG_00535', 'Kết nối Internet', 'Là thông tin xác nhận việc cơ sở giáo dục đã được trang bị và kết nối hệ thống mạng Internet phục vụ công tác quản lý, giảng dạy và học tập.', 'Thuộc tính đánh dấu kết nối Internet trong quá trình quản lý, giảng dạy và học tập (giá trị có/không).', array['MOET32']::text[], 'isKhaiThacInterNetDayHoc', 'Boolean', 'Đúng/Sai', '1', null),
  ('BG_00536', 'Điện lưới', 'Là thông tin xác nhận việc cơ sở giáo dục đã được kết nối và sử dụng nguồn điện từ lưới điện quốc gia hoặc lưới điện địa phương.', 'Thuộc tính đánh dấu điện lưới của cơ sở giáo dục (giá trị có/không).', array['MOET32']::text[], 'isDienLuoi', 'Boolean', 'Đúng/Sai', '1', null),
  ('BG_00537', 'Nguồn nước sạch', 'Là thông tin xác nhận việc cơ sở giáo dục được cung cấp và sử dụng nguồn nước sinh hoạt đạt tiêu chuẩn vệ sinh, an toàn theo quy định.', 'Thuộc tính đánh dấu nguồn nước sạch của cơ sở giáo dục (giá trị có/không).', array['MOET32']::text[], 'isNguonNuocSach', 'Boolean', 'Đúng/Sai', '1', null),
  ('BG_00538', 'Công trình vệ sinh', 'Là thông tin về tình trạng trang bị và chất lượng của hệ thống công trình vệ sinh tại cơ sở giáo dục, đảm bảo điều kiện sức khỏe cho người học và cán bộ, nhà giáo.', 'Thuộc tính đánh dấu công trình vệ sinh của cơ sở giáo dục (giá trị có/không).', array['MOET32']::text[], 'isCongTrinhVeSinh', 'Boolean', 'Đúng/Sai', '1', null),
  ('BG_00539', 'Hạ tầng tiếp cận người học khuyết tật', 'Là hệ thống cơ sở vật chất và điều kiện hỗ trợ để người khuyết tật có thể tiếp cận và tham gia học tập bình đẳng.', 'Thuộc tính đánh dấu hạ tầng tiếp cận người học khuyết tật của người học (giá trị có/không).', array['MOET32']::text[], 'isCoHaTangTlhtPhuHopHskt', 'Boolean', 'Đúng/Sai', 'i', null),
  ('BG_00540', 'Đủ TBDH - Tiếng Việt', 'Là các lớp học (phổ biến nhất là bậc Tiểu học) được trang bị đầy đủ các trang thiết bị, đồ dùng học tập tối thiểu theo đúng quy định của Bộ Giáo dục và Đào tạo để giảng dạy môn Tiếng Việt.', 'Thuộc tính đánh dấu đủ TBDH - Tiếng Việt của cơ sở giáo dục (giá trị có/không).', array['MOET32']::text[], 'isTbdhTviet', 'Boolean', 'Đúng/Sai', '1', null),
  ('BG_00541', 'Đủ TBDH - Toán', 'Là các lớp học (phổ biến nhất là bậc Tiểu học) được trang bị đầy đủ các trang thiết bị, đồ dùng học tập tối thiểu theo đúng quy định của Bộ Giáo dục và Đào tạo để giảng dạy môn Toán.', 'Thuộc tính đánh dấu đủ TBDH - Toán của cơ sở giáo dục (giá trị có/không).', array['MOET32']::text[], 'isTbdhToan', 'Boolean', 'Đúng/Sai', '1', null),
  ('BG_00542', 'Diện tích xây dựng', 'Là diện tích sàn xây dựng các công trình trong khuôn viên trung tâm (đơn vị: m²)', 'Thuộc tính định lượng phản ánh diện tích xây dựng của cơ sở giáo dục.', array['MOET32']::text[], 'dienTichXayDung', 'Decimal', 'Số thập phân', null, null),
  ('BG_00543', 'Diện tích cơ sở giáo dục', 'Là diện tích được tính dựa trên tổng diện tích khu đất xây dựng cơ sở giáo dục.', 'Thuộc tính mô tả diện tích cơ sở giáo dục.', array['MOET32']::text[], 'dienTichCggd', 'String', 'Chuỗi ký tự', '10', null),
  ('BG_00544', 'Hình thức sở hữu đất đai', 'Là loại quyền sử dụng đất: nhà nước giao, thuê, mượn.', 'Thuộc tính phân loại hình thức sở hữu đất đai của cơ sở giáo dục.', array['MOET32']::text[], 'hinhThucSoHuu', 'Enumeration', 'Danh mục liệt kê', null, null),
  ('BG_00545', 'Tên người sở hữu đất đai', 'Là tên cá nhân hoặc tổ chức có quyền sử dụng đất hợp pháp', 'Thuộc tính ghi nhận tên người sở hữu đất đai của cơ sở giáo dục.', array['MOET32']::text[], 'tenNguoiSoHuu', 'String', 'Chuỗi ký tự', '50', null),
  ('BG_00546', 'Minh chứng quyền sở hữu đất đai', 'Là dữ liệu để chứng minh quyền sở hữu đất của trung tâm như giấy chứng nhận sở hữu đất, hợp đồng thuê đất...', 'Thuộc tính mô tả minh chứng quyền sở hữu đất đai của cơ sở giáo dục.', array['MOET32']::text[], 'minhChungQuyenSoHuu', 'String', 'Chuỗi ký tự', '255', null),
  ('BG_00547', 'Mục đích sử dụng đất đai', 'Là nội dung mô tả mục đích cơ sở giáo dục sử dụng đất.', 'Thuộc tính mô tả mục đích sử dụng đất đai của cơ sở giáo dục.', array['MOET32']::text[], 'mucDichSuDungDat', 'String', 'Chuỗi ký tự', '255', null),
  ('BG_00548', 'Công trình xây dựng', 'Là tên hoặc mô tả các hạng mục công trình xây dựng trong phạm vi sử dụng đất của trung tâm.', 'Thuộc tính mô tả công trình xây dựng của cơ sở giáo dục.', array['MOET32']::text[], 'congTrinhXayDung', 'String', 'Chuỗi ký tự', '100', null),
  ('BG_00549', 'Năm bắt đầu sử dụng đất đai', 'Là năm trung tâm bắt đầu khai thác sử dụng đất.', 'Thuộc tính định lượng phản ánh năm bắt đầu sử dụng đất đai của cơ sở giáo dục.', array['MOET32']::text[], 'namBatDauSuDung', 'Integer', 'Số nguyên', null, null),
  ('BG_00550', 'Thời gian sử dụng đất đai', 'Là thời hạn được phép sử dụng đất (đơn vị: năm).', 'Thuộc tính định lượng phản ánh thời gian được sử dụng đất đai của cơ sở giáo dục.', array['MOET32']::text[], 'thoiGianSuDung', 'Integer', 'Số nguyên', null, null),
  ('BG_00551', 'Tên phòng học', 'Là tên gọi của phòng học được đặt theo môn học hoặc chức năng sử dụng nhằm phục vụ hoạt động giảng dạy.', 'Thuộc tính ghi nhận tên phòng học của cơ sở giáo dục.', array['MOET32']::text[], 'tenPhongHoc', 'String', 'Chuỗi ký tự', '50', null),
  ('BG_00552', 'Số lượng phòng học', 'Là tổng số lượng phòng học của cơ sở đào tạo.', 'Thuộc tính định lượng phản ánh số lượng phòng học của cơ sở giáo dục.', array['MOET32']::text[], 'soLuongPhongHoc', 'Integer', 'Số nguyên', null, null),
  ('BG_00553', 'Tổng diện tích phòng học', 'Là tổng diện tích của phòng học (tính theo đơn vị m2)', 'Thuộc tính định lượng phản ánh tổng diện tích phòng học của cơ sở giáo dục.', array['MOET32']::text[], 'tongDienTichPhongHoc', 'Decimal', 'Số thập phân', null, null),
  ('BG_00554', 'Tình trạng sở hữu phòng học', 'Là trạng thái pháp lý về quyền sở hữu hoặc sử dụng phòng học của cơ sở đào tạo, ví dụ: sở hữu, thuê, mượn hoặc liên kết sử dụng.', 'Thuộc tính phân loại tình trạng sở hữu phòng học của cơ sở giáo dục.', array['MOET32']::text[], 'tinhTrangSoHuu', 'Enumeration', 'Danh mục liệt kê', null, null),
  ('BG_00555', 'Số chỗ ký túc xá', 'Là tổng sức chứa tối đa của ký túc xá của cơ sở giáo dục.', 'Thuộc tính định lượng phản ánh số chỗ ký túc xá của cơ sở giáo dục.', array['MOET32']::text[], 'soChoOKyTucXa', 'Integer', 'Số nguyên', null, null),
  ('BG_00556', 'Mã phòng thí nghiệm', 'Là mã quản lý của mỗi phòng thí nghiệm tại cơ sở giáo dục.', 'Thuộc tính phân biệt các phòng thí nghiệm trong cơ sở giáo dục.', array['MOET32']::text[], 'phongTnId', 'Enumeration', 'Chuỗi ký tự', '50', null),
  ('BG_00557', 'Tên phòng thí nghiệm', 'Là tên gọi của phòng thí nghiệm, thường gắn với lĩnh vực chuyên môn hoặc chức năng nghiên cứu.', 'Thuộc tính ghi nhận tên phòng thí nghiệm của cơ sở giáo dục.', array['MOET32']::text[], 'tenPhongTn', 'String', 'Chuỗi ký tự', '50', null),
  ('BG_00558', 'Loại phòng thí nghiệm', 'Là phân loại phòng thí nghiệm theo lĩnh vực hoặc mục đích sử dụng (ví dụ: hóa học, sinh học, công nghệ thông tin).', 'Thuộc tính phân loại loại phòng thí nghiệm của cơ sở giáo dục.', array['MOET32']::text[], 'loaiPhongTn', 'Enumeration', 'Danh mục liệt kê', null, null),
  ('BG_00559', 'Số lượng phòng thí nghiệm', 'Là tổng số lượng các phòng được trang bị chuyên dụng để thực hiện thí nghiệm.', 'Thuộc tính định lượng phản ánh số lượng phòng thí nghiệm của cơ sở giáo dục.', array['MOET32']::text[], 'soLuongPhongTn', 'Integer', 'Số nguyên', null, null),
  ('BG_00560', 'Mục đích sử dụng phòng thí nghiệm', 'Là chức năng chính của phòng thí nghiệm, phục vụ giảng dạy, thực hành hoặc nghiên cứu khoa học.', 'Thuộc tính mô tả mục đích sử dụng phòng thí nghiệm của cơ sở giáo dục.', array['MOET32']::text[], 'mucDichSdPhongTn', 'String', 'Chuỗi ký tự', '255', null),
  ('BG_00561', 'Đối tượng sử dụng phòng thí nghiệm', 'Là nhóm người được phép sử dụng phòng thí nghiệm', 'Thuộc tính mô tả ai được sử dụng phòng thí nghiệm.', array['MOET32']::text[], 'doiTuongSdPhongTn', 'String', 'Chuỗi ký tự', '255', null),
  ('BG_00562', 'Diện tích sàn phòng thí nghiệm', 'Là diện tích sàn phòng thí nghiệm, tính theo đơn vị m2.', 'Thuộc tính định lượng phản ánh diện tích sàn phòng thí nghiệm của cơ sở giáo dục.', array['MOET32']::text[], 'dienTichSanPhongTn', 'Decimal', 'Số thập phân', '-18.2', null),
  ('BG_00563', 'Vốn ban đầu phòng thí nghiệm', 'Là tổng giá trị đầu tư ban đầu để xây dựng và trang bị phòng thí nghiệm.', 'Thuộc tính định lượng phản ánh vốn ban đầu để đầu tư, xây dựng phòng thí nghiệm của cơ sở giáo dục.', array['MOET32']::text[], 'vonBanDauPhongTn', 'Decimal', 'Số thập phân', null, null),
  ('BG_00564', 'Vốn đầu tư phòng thí nghiệm', 'Là tổng giá trị nguồn vốn đầu tư cho phòng thí nghiệm tại thời điểm hiện tại, bao gồm đầu tư bổ sung.', 'Thuộc tính định lượng phản ánh vốn đầu tư phòng thí nghiệm của cơ sở giáo dục.', array['MOET32']::text[], 'vonDauTuPhongTn', 'Decimal', 'Số thập phân', null, null),
  ('BG_00565', 'Tình trạng sở hữu phòng thí nghiệm', 'Là trạng thái pháp lý về quyền sở hữu hoặc sử dụng phòng thí nghiệm.', 'Thuộc tính phân loại tình trạng sở hữu phòng thí nghiệm của cơ sở giáo dục.', array['MOET32']::text[], 'tinhTrangSoHuu', 'Enumeration', 'Danh mục liệt kê', null, null),
  ('BG_00566', 'Hình thức sở hữu phòng thí nghiệm', 'Là hình thức xác định quyền sở hữu phòng thí nghiệm (ví dụ: sở hữu nhà nước, tư nhân, liên doanh).', 'Thuộc tính phân loại hình thức sở hữu phòng thí nghiệm của cơ sở giáo dục.', array['MOET32']::text[], 'hinhThucSoHuu', 'Enumeration', 'Danh mục liệt kê', null, null),
  ('BG_00567', 'Địa điểm phòng thí nghiệm', 'Là vị trí cụ thể nơi phòng thí nghiệm được đặt trong cơ sở đào tạo.', 'Thuộc tính mô tả địa điểm phòng thí nghiệm của cơ sở giáo dục.', array['MOET32']::text[], 'diaDiemPhongTn', 'String', 'Chuỗi ký tự', '100', null),
  ('BG_00568', 'Tên thiết bị trong phòng thí nghiệm', 'Là tên gọi của thiết bị phục vụ hoạt động thí nghiệm, nghiên cứu và giảng dạy.', 'Thuộc tính ghi nhận tên thiết bị trong phòng thí nghiệm của cơ sở giáo dục.', array['MOET32']::text[], 'tenThietBiPhongTn', 'String', 'Chuỗi ký tự', '100', null),
  ('BG_00569', 'Năm sản xuất thiết bị trong phòng thí nghiệm', 'Là năm thiết bị được sản xuất bởi nhà sản xuất.', 'Thuộc tính định lượng phản ánh năm sản xuất thiết bị trong phòng thí nghiệm của cơ sở giáo dục.', array['MOET32']::text[], 'namSanXuatThietBiPhongTn', 'Integer', 'Số nguyên', '4', null),
  ('BG_00570', 'Nơi sản xuất thiết bị trong phòng thí nghiệm', 'Là quốc gia hoặc đơn vị sản xuất thiết bị.', 'Thuộc tính mô tả nơi sản xuất thiết bị trong phòng thí nghiệm của cơ sở giáo dục.', array['MOET32']::text[], 'noiSanXuatThietBiPhongTn', 'String', 'Chuỗi ký tự', '100', null),
  ('BG_00571', 'Hãng sản xuất thiết bị trong phòng thí nghiệm', 'Là tên hãng sản xuất ra thiết bị trong phòng thí nghiệm.', 'Thuộc tính mô tả hãng sản xuất thiết bị trong phòng thí nghiệm của cơ sở giáo dục.', array['MOET32']::text[], 'hangSanXuatThietBiPhongTn', 'String', 'Chuỗi ký tự', '100', null),
  ('BG_00572', 'Tính năng sử dụng thiết bị trong phòng thí nghiệm', 'Là chức năng, công dụng của thiết bị trong hoạt động giảng dạy hoặc nghiên cứu.', 'Thuộc tính mô tả tính năng sử dụng thiết bị trong phòng thí nghiệm của cơ sở giáo dục.', array['MOET32']::text[], 'tinhNangSuDungThietBiPhongTn', 'String', 'Chuỗi ký tự', '1000', null),
  ('BG_00573', 'Số lượng thiết bị trong phòng thí nghiệm', 'Là số lượng thiết bị có trong phòng thí nghiệm', 'Thuộc tính định lượng phản ánh số lượng thiết bị trong phòng thí nghiệm của cơ sở giáo dục.', array['MOET32']::text[], 'soLuongThietBiPhongTn', 'Integer', 'Số nguyên', null, null),
  ('BG_00574', 'Nguyên giá thiết bị trong phòng thí nghiệm', 'Là giá trị ban đầu của thiết bị tại thời điểm mua sắm hoặc ghi nhận tài sản.', 'Thuộc tính định lượng phản ánh nguyên giá thiết bị trong phòng thí nghiệm của cơ sở giáo dục.', array['MOET32']::text[], 'nguyenGiaThietBiPhongTn', 'Decimal', 'Số thập phân', null, null),
  ('BG_00575', 'Tên phòng/xưởng thực hành', 'Là tên gọi của không gian phục vụ hoạt động thực hành nghề nghiệp hoặc kỹ thuật.', 'Thuộc tính ghi nhận tên phòng/xưởng thực hành của cơ sở giáo dục.', array['MOET32']::text[], 'tenPhongXuongTh', 'String', 'Chuỗi ký tự', '50', null),
  ('BG_00576', 'Địa điểm phòng/xưởng thực hành', 'Là vị trí nơi phòng hoặc xưởng thực hành', 'Thuộc tính mô tả địa điểm phòng/xưởng thực hành của cơ sở giáo dục.', array['MOET32']::text[], 'diaDiemPhongXuongTh', 'String', 'Chuỗi ký tự', '100', null),
  ('BG_00577', 'Mục đích sử dụng phòng/xưởng thực hành', 'Là chức năng phục vụ đào tạo thực hành, rèn luyện kỹ năng nghề nghiệp cho người học.', 'Thuộc tính mô tả mục đích sử dụng phòng/xưởng thực sử dụng hành của cơ sở giáo dục.', array['MOET32']::text[], 'mucDichSuDungPhongXuongTh', 'String', 'Chuỗi ký tự', '255', null),
  ('BG_00578', 'Đối tượng sử dụng phòng/xưởng thực hành', 'Là đối tượng được sử dụng phòng/xưởng thực hành', 'Thuộc tính mô tả sử dụng phòng/xưởng thực hành của cơ sở giáo dục.', array['MOET32']::text[], 'doiTuongSuDungPhongXuongTh', 'String', 'Chuỗi ký tự', '255', null),
  ('BG_00579', 'Diện tích sàn xây dựng phòng/xưởng thực hành', 'Là diện tích sử dụng của phòng/xưởng, tính theo mét vuông (m²).', 'Thuộc tính định lượng phản ánh diện tích sàn xây dựng phòng/xưởng thực hành của cơ sở giáo dục.', array['MOET32']::text[], 'dienTichSanXayDungPhongXuongTh', 'Integer', 'Số nguyên', null, null),
  ('BG_00580', 'Vốn đầu tư ban đầu phòng/xưởng thực hành', 'Là chi phí đầu tư ban đầu để xây dựng và trang bị phòng/xưởng thực hành.', 'Thuộc tính định lượng phản ánh vốn đầu tư ban đầu phòng/xưởng thực hành của cơ sở giáo dục.', array['MOET32']::text[], 'vonDauTuBanDauPhongXuongTh', 'Decimal', 'Số thập phân', null, null),
  ('BG_00581', 'Nguồn vốn đầu tư phòng/xưởng thực hành', 'Là nguồn tài chính đầu tư (ngân sách nhà nước, xã hội hóa, tài trợ…).', 'Thuộc tính định lượng phản ánh nguồn vốn đầu tư phòng/xưởng thực hành của cơ sở giáo dục. sử dụng', array['MOET32']::text[], 'nguonVonDauTuPhongXuongTh', 'Decimal', 'Số thập phân', null, null),
  ('BG_00582', 'Tình trạng sở hữu phòng/xưởng thực hành', 'Là trạng thái pháp lý về quyền sở hữu hoặc sử dụng.', 'Thuộc tính phân loại tình trạng sở hữu phòng/xưởng thực hành của cơ sở giáo dục.', array['MOET32']::text[], 'tinhTrangSoHuu', 'Enumeration', 'Danh mục liệt kê', null, null),
  ('BG_00583', 'Hình thức sở hữu phòng/xưởng thực hành', 'Là hình thức sở hữu (nhà nước, tư nhân, liên kết…).', 'Thuộc tính phân loại hình thức sở hữu phòng/xưởng thực hành của cơ sở giáo dục.', array['MOET32']::text[], 'hinhThucSoHuu', 'Enumeration', 'Danh mục liệt kê', null, null),
  ('BG_00584', 'Tên thiết bị trong phòng/xưởng thực hành', 'Là danh mục thiết bị phục vụ thực hành.', 'Thuộc tính ghi nhận tên thiết bị trong phòng/ xưởng thực hành của cơ sở giáo dục.', array['MOET32']::text[], 'tenThietBiPhongXuongTh', 'String', 'Chuỗi ký tự', '50', null),
  ('BG_00585', 'Số lượng thiết bị trong phòng/xưởng thực hành', 'Là tổng số lượng các thiết bị trong phòng/ xưởng thực hành', 'Thuộc tính định lượng phản ánh số lượng thiết bị trong phòng/ xưởng thực hành của cơ sở giáo dục.', array['MOET32']::text[], 'soLuongThietBiPhongXuongTh', 'Integer', 'Số nguyên', null, null),
  ('BG_00586', 'Năm sản xuất thiết bị trong phòng/xưởng thực hành', 'Là năm thiết bị được sản xuất.', 'Thuộc tính định lượng phản ánh năm sản xuất thiết bị trong phòng/ xưởng thực hành của cơ sở giáo dục.', array['MOET32']::text[], 'namSanXuatThietBiPhongXuongTh', 'Integer', 'Số nguyên', null, null),
