  ('BG_00588', 'Hãng sản xuất thiết bị trong phòng/xưởng thực hành', 'Là hãng sản xuất của thiết bị phòng/ xưởng thực hành', 'Thuộc tính mô tả hãng sản xuất thiết bị trong phòng/ xưởng thực hành của cơ sở giáo dục.', array['MOET32']::text[], 'hangSanXuatThietBiPhongXuongTh', 'String', 'Chuỗi ký tự', '100', null),
  ('BG_00589', 'Tên thư viện, trung tâm học liệu', 'Là tên của thư viện hoặc trung tâm học liệu phục vụ học tập, nghiên cứu của người học.', 'Thuộc tính ghi nhận tên thư viện, trung tâm học liệu của cơ sở giáo dục.', array['MOET32']::text[], 'tenTvTtHocLieu', 'String', 'Chuỗi ký tự', '255', null),
