  ('BG_00591', 'Năm đưa vào sử dụng thư viện', 'Là năm thư viện chính thức được đưa vào vận hành phục vụ người học.', 'Thuộc tính định lượng phản ánh năm đưa vào sử dụng thư viện của cơ sở giáo dục.', array['MOET32']::text[], 'namDuaVaoSuDungTvTtHocLieu', 'Integer', 'Số nguyên', null, null),
  ('BG_00592', 'Tổng diện tích thư viện, trung tâm học liệu', 'Là tổng diện tích thư viện, trung tâm học liệu, tính theo đơn vị m2.', 'Thuộc tính định lượng phản ánh tổng diện tích thư viện, trung tâm học liệu của cơ sở giáo dục.', array['MOET32']::text[], 'tongDienTichTvTtHocLieu', 'Decimal', 'Số thập phân', null, null),
  ('BG_00593', 'Tống diện tích phòng đọc', 'Là tống diện tích phòng đọc, tính theo đơn vị m2.', 'Thuộc tính định lượng phản ánh tống diện tích phòng đọc của cơ sở giáo dục.', array['MOET32']::text[], 'tongDienTichPhongDoc', 'Decimal', 'Số thập phân', null, null),
