  ('BG_00596', 'Số lượng chỗ ngồi đọc sách thư viện, trung tâm học liệu', 'Là số lượng chỗ ngồi đọc sách của thư viện, trung tâm học liệu', 'Thuộc tính định lượng phản ánh số lượng chỗ ngồi đọc sách thư viện, trung tâm học liệu của cơ sở giáo dục.', array['MOET32']::text[], 'soLuongChoNgoiDocSachTvTtHocLieu', 'Integer', 'Số nguyên', null, null),
