  ('BG_00598', 'Số lượng tạp chí thư viện, trung tâm học liệu', 'Là số lượng tạp chí của thư viện, trung tâm học liệu', 'Thuộc tính định lượng phản ánh số lượng tạp chí thư viện, trung tâm học liệu của cơ sở giáo dục.', array['MOET32']::text[], 'soLuongTapChiTvTtHocLieu', 'Integer', 'Số nguyên', null, null),
