  ('BG_00607', 'Tổng diện tích sàn sử dụng công trình khác', 'Tổng diện tích sàn sử dụng công trình khác (tính theo đơn vị m2)', 'Thuộc tính định lượng phản ánh tổng diện tích sàn sử dụng công trình khác của cơ sở giáo dục.', array['MOET32']::text[], 'tongDtSanSuDungCongTrinhKhac', 'Decimal', 'Số thập phân', null, null),
  ('BG_00608', 'Năm đưa vào sử dụng công trình khác', 'Là năm công trình được hoàn thành và đưa vào khai thác.', 'Thuộc tính định lượng phản ánh năm đưa vào sử dụng công trình khác của cơ sở giáo dục.', array['MOET32']::text[], 'namDuaVaoSuDungCongTrinhKhac', 'Integer', 'Số nguyên', null, null),
  ('BG_00609', 'Tình trạng sở hữu công trình khác', 'Là trạng thái pháp lý về quyền sở hữu hoặc sử dụng công trình.', 'Thuộc tính phân loại tình trạng sở hữu công trình khác của cơ sở giáo dục.', array['MOET32']::text[], 'tinhTrangSoHuu', 'Enumeration', 'Danh mục liệt kê', null, null),
  ('BG_00610', 'Vốn đầu tư công trình khác', 'Là tổng chi phí đầu tư xây dựng công trình.', 'Thuộc tính định lượng phản ánh vốn đầu tư công trình khác của cơ sở giáo dục.', array['MOET32']::text[], 'vonDauTuCongTrinhKhac', 'Decimal', 'Số thập phân', null, null),
  ('BG_00611', 'Đơn vị hợp tác đầu tư công trình khác', 'Là tổ chức hoặc đối tác cùng tham gia đầu tư xây dựng công trình', 'Thuộc tính mô tả đơn vị hợp tác đầu tư công trình khác của cơ sở giáo dục.', array['MOET32']::text[], 'donViHopTacDauTu', 'String', 'Chuỗi ký tự', '100', null),
  ('BG_00612', 'Hình thức sử dụng công trình khác', 'Là cách thức khai thác và sử dụng công trình', 'Thuộc tính mô tả hình thức sử dụng công trình khác của cơ sở giáo dục.', array['MOET32']::text[], 'hinhThucSuDungCongTrinhKhac', 'String', 'Chuỗi ký tự', '100', null),
  ('BG_00613', 'Tên loại tài sản', 'Là tên gọi của nhóm tài sản theo phân loại', 'Thuộc tính ghi nhận tên loại tài sản của cơ sở giáo dục.', array['MOET32']::text[], 'tenLoaiTaiSan', 'String', 'Chuỗi ký tự', '50', null),
  ('BG_00614', 'Mã loại tài sản', 'Là mã định danh của loại tài sản trong hệ thống quản lý tài sản', 'Thuộc tính mô tả mã loại tài sản của cơ sở giáo dục.', array['MOET32']::text[], 'maLoaiTaiSan', 'String', 'Chuỗi ký tự', '50', null),
  ('BG_00615', 'Tên tài sản', 'Là tên cụ thể của tài sản thuộc sở hữu hoặc quản lý của cơ sở đào tạo', 'Thuộc tính ghi nhận tên tài sản của cơ sở giáo dục.', array['MOET32']::text[], 'tenTaiSan', 'String', 'Chuỗi ký tự', '100', null),
  ('BG_00616', 'Nguyên giá tài sản', 'Là giá trị ban đầu của tài sản tại thời điểm ghi nhận', 'Thuộc tính định lượng phản ánh nguyên giá tài sản của cơ sở giáo dục.', array['MOET32']::text[], 'nguyenGiaTaiSan', 'Decimal', 'Số thập phân', null, null),
  ('BG_00617', 'Chủ sở hữu tài sản', 'Là tổ chức hoặc cá nhân có quyền sở hữu hợp pháp đối với tài sản', 'Thuộc tính mô tả chủ sở hữu tài sản của cơ sở giáo dục.', array['MOET32']::text[], 'chuSoHuuTaiSan', 'String', 'Chuỗi ký tự', '100', null),
  ('BG_00618', 'Năm báo cáo tài sản', 'Năm thực hiện báo cáo tài sản', 'Thuộc tính định lượng phản ánh năm báo cáo tài sản của cơ sở giáo dục.', array['MOET32']::text[], 'namBaoCaoTaiSan', 'Integer', 'Số nguyên', null, null),
  ('BG_00619', 'Chuẩn đánh giá chất lượng giáo dục', 'Là hệ thống các tiêu chuẩn, tiêu chí do cơ quan quản lý nhà nước ban hành nhằm đánh giá và công nhận mức độ đáp ứng điều kiện đảm bảo chất lượng của các cơ sở giáo dục.', 'Thuộc tính phân loại chuẩn đánh giá chất lượng giáo dục của các cơ sở giáo dục.', array['MOET33']::text[], 'datChuanDanhGiaClgd', 'Enumeration', 'Danh mục liệt kê', null, null),
  ('BG_00620', 'Đạt chuẩn quốc gia', 'Là thông tin xác nhận việc cơ sở giáo dục được cơ quan có thẩm quyền công nhận đạt chuẩn quốc gia khi đáp ứng các tiêu chuẩn về tổ chức, đội ngũ, cơ sở vật chất và chất lượng giáo dục.', 'Thuộc tính phân loại cơ sở giáo dục đạt chuẩn quốc gia.', array['MOET33']::text[], 'isDatChuanQg', 'Boolean', 'Đúng/Sai', '1', null),
  ('BG_00621', 'Chất lượng tối thiểu', 'Là mức độ cơ sở giáo dục đáp ứng được các tiêu chuẩn cơ bản, bắt buộc do cơ quan có thẩm quyền ban hành.', 'Thuộc tính đánh dấu cơ sở giáo dục có đạt chất lượng tối thiểu.', array['MOET33']::text[], 'isDatChatLuongToiThieu', 'Boolean', 'Đúng/Sai', '1', null),
  ('BG_00622', 'Hạng cơ sở giáo dục', 'Là phân loại hạng của cơ sở giáo dục (ví dụ: Hạng I, Hạng II, Hạng III) được cơ quan nhà nước có thẩm quyền quyết định công nhận dựa trên quy mô và chất lượng hoạt động.', 'Thuộc tính phân loại hạng cơ sở giáo dục.', array['MOET33']::text[], 'hangTruong', 'String', 'Chuỗi ký tự', '10', null),
  ('BG_00623', 'Cấp độ kiểm định chất lượng', 'Là mức độ chất lượng của cơ sở giáo dục được công bố rộng rãi sau quá trình đánh giá của Sở giáo dục và đào tạo về mức đáp ứng mục tiêu giáo dục trong từng giai đoạn.', 'Thuộc tính định lượng phản ánh cấp độ kiểm định chất lượng của kiểm định chất lượng cơ sở giáo dục.', array['MOET33']::text[], 'kiemDinhCapDo', 'Integer', 'Số nguyên', null, null),
  ('BG_00624', 'Tổ chức kiểm định cơ sở giáo dục', 'Là các đơn vị độc lập, được Bộ Giáo dục và Đào tạo cấp phép thực hiện đánh giá và công nhận chất lượng cơ sở giáo dục theo tiêu chuẩn do cơ quan có thẩm quyền ban hành.', 'Thuộc tính thông tin tổ chức kiểm định thực hiện đánh giá chất lượng cơ sở giáo dục.', array['MOET33']::text[], 'toChucKiemDinhCsgd', 'String', 'Chuỗi ký tự', '255', null),
  ('BG_00625', 'Kết quả kiểm định cơ sở giáo dục', 'Là kết luận của tổ chức kiểm định về mức độ đạt tiêu chuẩn chất lượng giáo dục của cơ sở đào tạo', 'Thuộc tính mô tả kết quả kiểm định chất lượng cơ sở giáo dục.', array['MOET33']::text[], 'ketQuaKiemDinhCsgd', 'String', 'Chuỗi ký tự', '500', null),
  ('BG_00626', 'Ngày cấp chứng nhận kiểm định chất lượng cơ sở giáo dục', 'Là thời điểm tổ chức kiểm định ban hành văn bản chứng nhận cơ sở đào tạo đạt tiêu chuẩn chất lượng giáo dục.', 'Thuộc tính ghi nhận mốc thời gian ngày cấp chứng nhận kiểm định chất lượng của cơ sở giáo dục.', array['MOET33']::text[], 'ngayCapChungNhanKdclCsgd', 'Date', 'Ngày tháng', '10', 'CDE-TG-001'),
  ('BG_00627', 'Thời hạn kiểm định chất lượng cơ sở giáo dục', 'Là khoảng thời gian có hiệu lực của giấy chứng nhận kiểm định chất lượng giáo dục.', 'Thuộc tính ghi nhận mốc thời gian thời hạn kiểm định chất lượng có hiệu lực của cơ sở giáo dục.', array['MOET33']::text[], 'thoiHanKdclCsgd', 'String', 'Chuỗi ký tự', '255', null),
  ('BG_00628', 'Loại báo cáo', 'Là tên báo cáo mà các cơ sở giáo dục cần gửi lên cho các cơ quan quản lý nhà nước về giáo dục nhằm mục đích tổng hợp, quản lý và điều hành.', 'Thuộc tính mô tả loại báo cáo của cơ sở giáo dục.', array['MOET34']::text[], 'maBaoCao', 'String', 'Chuỗi ký tự', '50', null),
  ('BG_00629', 'Tổng số cán bộ/nhà giáo', 'Là tổng cộng số lượng nhân sự sư phạm (bao gồm viên chức biên chế và hợp đồng lao động) làm việc tại một cơ sở giáo dục, khu vực hoặc toàn quốc', 'Thuộc tính định lượng phản ánh tổng sử dụng số cán bộ/nhà giáo của cơ sở giáo dục; phục vụ thống kê, tổng hợp và đánh giá.', array['MOET34']::text[], 'tongSoDn', 'Integer', 'Số nguyên', null, null),
  ('BG_00630', 'Số cán bộ/nhà giáo đạt trình độ đào tạo trên đại học', 'Là số cán bộ/nhà giáo đạt trình độ trên đại học (thạc sĩ, tiến sĩ, giáo sư, phó giáo sư) là đội ngũ giảng viên đáp ứng tiêu chuẩn cao hơn mức cơ bản (đại học) tại các cơ sở giáo dục', 'Thuộc tính định lượng số cán bộ/nhà giáo đạt trình độ đào tạo trên đại học của cơ sở giáo dục.', array['MOET34']::text[], 'soCbNgDatTrinhDoDaoTaoTrenDh', 'String', 'Chuỗi ký tự', '255', null),
  ('BG_00631', 'Số cán bộ/nhà giáo đạt trình độ đào tạo đại học', 'Là những người có bằng đại học trở lên (đại học, thạc sĩ, tiến sĩ) giảng dạy tại các cơ sở giáo dục', 'Thuộc tính định lượng số cán bộ/nhà giáo đạt trình độ đào tạo đại học của cơ sở giáo dục.', array['MOET34']::text[], 'soCbNgDatTrinhDoDaoTaoDh', 'String', 'Chuỗi ký tự', '255', null),
  ('BG_00632', 'Số cán bộ/nhà giáo đạt trình độ đào tạo cao đẳng', 'Là (chuẩn nghề nghiệp) thường đề cập đến những người tốt nghiệp các trường cao đẳng sư phạm, chuyên ngành đào tạo cán bộ/nhà giáo hoặc các lĩnh vực đặc thù.', 'Thuộc tính định lượng số cán bộ/nhà giáo đạt trình độ đào tạo cao đẳng của cơ sở giáo dục.', array['MOET34']::text[], 'soCbNgDatTrinhDoDaoTaoCaoDang', 'String', 'Chuỗi ký tự', '255', null),
  ('BG_00633', 'Số cán bộ/nhà giáo đạt trình độ đào tạo TH12 + 2', 'Là số cán bộ/nhà giáo đạt trình độ đào tạo TH12+2 (hoặc 12/12+2) là số lượng cán bộ/nhà giáo tốt nghiệp THPT (hệ 12 năm) và hoàn thành thêm 2 năm đào tạo sư phạm, tương đương trình độ Cao đẳng sư phạm.', 'Thuộc tính định lượng số cán bộ/nhà giáo đạt trình độ đào tạo TH12 + 2 của cơ sở giáo dục.', array['MOET34']::text[], 'soCbNgDatTrinhDoDaoTaoTh122', 'String', 'Chuỗi ký tự', '255', null),
  ('BG_00634', 'Số cán bộ/nhà giáo đạt trình độ đào tạo TH9 + 3', 'Là cán bộ/nhà giáo có trình độ Trung cấp sư phạm hệ 9+3 là người tốt nghiệp THCS (lớp 9) và học 3 năm tại trường sư phạm theo chương trình đào tạo cũ. Hệ này tích hợp đào tạo nghề sư phạm và văn hóa, sau 3 năm nhận bằng trung cấp chính quy', 'Thuộc tính định lượng số cán bộ/nhà giáo đạt trình độ đào tạo TH9 + 3 của cơ sở giáo dục.', array['MOET34']::text[], 'soCbNgDatTrinhDoDaoTaoTh93', 'String', 'Chuỗi ký tự', '255', null),
  ('BG_00635', 'Số cán bộ/nhà giáo đạt trình độ đào tạo dưới THSP', 'Là những cán bộ/nhà giáo mầm non, tiểu học, trung học cơ sở chưa đáp ứng yêu cầu bằng cấp mới theo Luật Giáo dục 2019', 'Thuộc tính định lượng số cán bộ/nhà giáo đạt trình độ đào tạo dưới THSP của cơ sở giáo dục.', array['MOET34']::text[], 'soCbNgDatTrinhDoDaoTaoDuoiThsp', 'String', 'Chuỗi ký tự', '255', null),
  ('BG_00636', 'Số cán bộ/nhà giáo biên chế', 'Là số lượng viên chức giảng dạy được tuyển dụng, bổ nhiệm vào vị trí việc làm ổn định trong các cơ sở giáo dục công lập, hưởng lương từ ngân sách nhà nước. Đây là hình thức hợp đồng làm việc không xác định thời hạn, mang lại quyền lợi ổn định cao, khác với cán bộ/nhà giáo hợp đồng thời vụ.', 'Thuộc tính định lượng số cán bộ/nhà giáo biên chế của cơ sở giáo dục.', array['MOET34']::text[], 'soCbNgBienChe', 'String', 'Chuỗi ký tự', '255', null),
  ('BG_00637', 'Số cán bộ/nhà giáo hợp đồng', 'Là những cán bộ/nhà giáo làm việc tại các cơ sở giáo dục theo hợp đồng lao động (thường là hợp đồng 111 theo Nghị định 111/2022/NĐ-CP), không thuộc biên chế nhà nước, không phải là viên chức. Họ được tuyển dụng tạm thời khi thiếu cán bộ/nhà giáo hoặc cần người thực hiện các nhiệm vụ đặc thù.', 'Thuộc tính định lượng số cán bộ/nhà giáo hợp đồng của cơ sở giáo dục.', array['MOET34']::text[], 'soCbNgHopDong', 'String', 'Chuỗi ký tự', '255', null),
  ('BG_00638', 'Số cán bộ/nhà giáo thỉnh giảng', 'Là cán bộ/nhà giáo thỉnh giảng là nhà giáo hoặc người có đủ tiêu chuẩn giảng dạy được cơ sở giáo dục mời đến giảng dạy môn học/chuyên đề, hướng dẫn thực tập, hoặc tham gia hội đồng thi tốt nghiệp theo hợp đồng, không phải là viên chức cơ hữu. Họ giúp nhà trường giải quyết thiếu hụt nhân sự, nâng cao chất lượng.', 'Thuộc tính định lượng số cán bộ/nhà giáo thỉnh giảng của cơ sở giáo dục.', array['MOET34']::text[], 'soCbNgThinhGiang', 'String', 'Chuỗi ký tự', '255', null),
  ('BG_00639', 'Tổng số cán bộ/nhà giáo nữ', 'Là tổng lượng nhân sự nữ giới đang trực tiếp giảng dạy tại các cơ sở giáo dục, thường được dùng để thống kê cơ cấu nhân sự, tỷ lệ giới tính, hoặc tính toán định mức lao động nữ', 'Thuộc tính định lượng phản ánh tổng số cán bộ/nhà giáo nữ của cơ sở giáo dục; phục vụ thống kê, tổng hợp và đánh giá. sử dụng', array['MOET34']::text[], 'tongSoCbNgNu', 'Integer', 'Số nguyên', null, null),
  ('BG_00640', 'Tổng số cán bộ/nhà giáo dân tộc', 'Là chỉ số thống kê tổng lượng nhà giáo người dân tộc thiểu số (DTTS) đang giảng dạy.', 'Thuộc tính định lượng phản ánh tổng số cán bộ/nhà giáo dân tộc của cơ sở giáo dục; phục vụ thống kê, tổng hợp và đánh giá.', array['MOET34']::text[], 'tongSoCbNgDanToc', 'Integer', 'Số nguyên', null, null),
  ('BG_00641', 'Tổng số cán bộ/nhà giáo dân tộc nữ', 'Là chỉ số thống kê tổng lượng nữ nhà giáo, bao gồm cả cán bộ/nhà giáo giảng dạy và quản lý, là người dân tộc thiểu số đang công tác tại các cơ sở giáo dục.', 'Thuộc tính định lượng phản ánh tổng số cán bộ/nhà giáo dân tộc nữ của cơ sở giáo dục; phục vụ thống kê, tổng hợp và đánh giá.', array['MOET34']::text[], 'tongSoCbNgDanTocNu', 'Integer', 'Số nguyên', null, null),
  ('BG_00642', 'Số cán bộ/nhà giáo đạt trình độ tiếng anh C2', 'Là số lượng cán bộ/nhà giáo có năng lực tiếng Anh đạt mức C2 theo Khung tham chiếu trình độ ngôn ngữ chung châu Âu (CEFR).', 'Thuộc tính định lượng số cán bộ/nhà giáo đạt trình độ tiếng anh C2 của cơ sở giáo dục.', array['MOET34']::text[], 'soCbNgDatTrinhDoTiengAnhC2', 'String', 'Chuỗi ký tự', '255', null),
  ('BG_00643', 'Số cán bộ/nhà giáo đạt trình độ tiếng anh C1', 'Là số lượng cán bộ/nhà giáo có năng lực tiếng Anh đạt mức C1 theo Khung tham chiếu trình độ ngôn ngữ chung châu Âu (CEFR).', 'Thuộc tính định lượng số cán bộ/nhà giáo đạt trình độ tiếng anh C1 của cơ sở giáo dục.', array['MOET34']::text[], 'soCbNgDatTrinhDoTiengAnhC1', 'String', 'Chuỗi ký tự', '255', null),
  ('BG_00644', 'Số cán bộ/nhà giáo đạt trình độ tiếng anh B2', 'Là số lượng cán bộ/nhà giáo có năng lực tiếng Anh đạt mức B2 theo Khung tham chiếu trình độ ngôn ngữ chung châu Âu (CEFR).', 'Thuộc tính định lượng số cán bộ/nhà giáo đạt trình độ tiếng anh B2 của cơ sở giáo dục.', array['MOET34']::text[], 'soCbNgDatTrinhDoTiengAnhB2', 'String', 'Chuỗi ký tự', '255', null),
  ('BG_00645', 'Số cán bộ/nhà giáo đạt trình độ tiếng anh B1', 'Là số lượng cán bộ/nhà giáo có năng lực tiếng Anh đạt mức B1 theo Khung CEFR.', 'Thuộc tính định lượng số cán bộ/nhà giáo đạt trình độ tiếng anh B1 của cơ sở giáo dục.', array['MOET34']::text[], 'soCbNgDatTrinhDoTiengAnhB1', 'String', 'Chuỗi ký tự', '255', null),
  ('BG_00646', 'Số cán bộ/nhà giáo đạt trình độ tiếng anh dưới B1', 'Là số lượng cán bộ/nhà giáo có trình độ tiếng Anh dưới mức B1 (A1, A2 hoặc chưa đạt chuẩn) theo Khung CEFR.', 'Thuộc tính định lượng số cán bộ/nhà giáo đạt trình độ tiếng anh dưới B1 của cơ sở giáo dục.', array['MOET34']::text[], 'soCbNgDatTrinhDoTiengAnhDuoiB1', 'String', 'Chuỗi ký tự', '255', null),
  ('BG_00647', 'Số cán bộ/nhà giáo có chứng chỉ sư phạm', 'Là những người giảng dạy đã hoàn thành khóa bồi dưỡng nghiệp vụ sư phạm, dành cho người có bằng cử nhân chuyên ngành phù hợp nhưng không tốt nghiệp ngành sư phạm.', 'Thuộc tính định lượng số cán bộ/nhà giáo có chứng chỉ sư phạm của cơ sở giáo dục.', array['MOET34']::text[], 'soCbNgCoChungChiSuPham', 'String', 'Chuỗi ký tự', '255', null),
  ('BG_00648', 'Diện tích sân chơi bãi tập', 'Là không gian ngoài trời trong khuôn viên trường học, được thiết kế phẳng, an toàn, dùng cho các hoạt động thể dục, thể thao, vui chơi và giải trí của học sinh.', 'Thuộc tính định lượng phản ánh diện tích sân chơi bãi tập của cơ sở giáo dục.', array['MOET34']::text[], 'dienTichSanChoiBaiTap', 'Decimal', 'Số thập phân', null, null),
  ('BG_00649', 'Số lượng phòng học theo cấp xây dựng trên cấp 4', 'Là tổng số phòng học được xây dựng kiên cố, có cấp công trình từ cấp III trở lên (cấp III, cấp II, cấp I), không bao gồm phòng học cấp IV và phòng học tạm.', 'Thuộc tính định lượng phản ánh số lượng phòng học theo cấp xây dựng sử dụng trên cấp 4 của cơ sở giáo dục.', array['MOET34']::text[], 'phongHocCapxdTrenCap4Sl', 'Integer', 'Số nguyên', null, null),
  ('BG_00650', 'Diện tích Phòng học theo cấp xây dựng trên cấp 4', 'Là tổng diện tích các phòng học được xây dựng kiên cố, có cấp công trình từ cấp III trở lên (cấp III, cấp II, cấp I), không bao gồm phòng học cấp IV và phòng học tạm.', 'Thuộc tính định lượng phản ánh diện tích Phòng học theo cấp xây dựng trên cấp 4 của cơ sở giáo dục.', array['MOET34']::text[], 'phongHocCapxdTrenCap4Idt', 'Decimal', 'Số thập phân', null, null),
  ('BG_00651', 'Số lượng phòng học theo cấp xây dựng cấp 4', 'Là tổng số phòng học được xây dựng theo tiêu chuẩn công trình cấp IV theo quy định về phân cấp công trình xây dựng, thường là phòng học bán kiên cố hoặc kiên cố mức cơ bản.', 'Thuộc tính định lượng phản ánh số lượng phòng học theo cấp xây dựng cấp 4 của cơ sở giáo dục.', array['MOET34']::text[], 'phongHocCapxdCap4Sl', 'Integer', 'Số nguyên', null, null),
  ('BG_00652', 'Diện tích phòng học theo cấp xây dựng cấp 4', 'Là tổng diện tích các phòng học được xây dựng theo tiêu chuẩn công trình cấp IV theo quy định về phân cấp công trình xây dựng.', 'Thuộc tính định lượng phản ánh diện tích phòng học theo cấp xây dựng cấp 4 của cơ sở giáo dục.', array['MOET34']::text[], 'dienTichPhongHocTheoCapXayDungCap4', 'Decimal', 'Số thập phân', null, null),
  ('BG_00653', 'Diện tích phòng học theo cấp xây dựng tạm', 'Là tổng diện tích các phòng học được xây dựng tạm thời, không kiên cố, có thời gian sử dụng ngắn, thường làm bằng vật liệu đơn giản như tôn, gỗ, tre, nứa hoặc vật liệu nhẹ khác. Chỉ số này dùng để đánh giá hiện trạng cơ sở vật chất tạm thời của trường học.', 'Thuộc tính định lượng phản ánh diện tích phòng học theo cấp xây dựng tạm của cơ sở giáo dục. sử dụng', array['MOET34']::text[], 'phongHocCapxdTamSl', 'Integer', 'Số nguyên', null, null),
  ('BG_00654', 'Số lượng phòng học theo cấp xây dựng tạm', 'Là tổng số phòng học được xây dựng tạm thời, chưa đảm bảo tiêu chuẩn phòng học kiên cố hoặc bán kiên cố. Chỉ số này phục vụ đánh giá nhu cầu đầu tư nâng cấp cơ sở vật chất.', 'Thuộc tính định lượng phản ánh số lượng phòng học theo cấp xây dựng tạm của cơ sở giáo dục.', array['MOET34']::text[], 'soLuongPhongHocTheoCapXayDungTam', 'Integer', 'Số nguyên', null, null),
  ('BG_00655', 'Số lượng phòng học theo cấp xây dựng tạm mượn', 'Là tổng số phòng học tạm thời được nhà trường mượn từ các đơn vị khác hoặc sử dụng tạm các công trình không phải phòng học (nhà văn hóa, hội trường, phòng chức năng...) để tổ chức dạy học.', 'Thuộc tính định lượng phản ánh số lượng phòng học theo cấp xây dựng tạm mượn của cơ sở giáo dục.', array['MOET34']::text[], 'phongHocCapxdMuonSl', 'Integer', 'Số nguyên', null, null),
  ('BG_00656', 'Diện tích phòng học theo cấp xây dựng tạm mượn', 'Là tổng diện tích các phòng học tạm mượn từ các đơn vị khác hoặc sử dụng tạm thời các công trình không chuyên dụng để tổ chức dạy học.', 'Thuộc tính định lượng phản ánh diện tích phòng học theo cấp xây dựng tạm mượn của cơ sở giáo dục.', array['MOET34']::text[], 'phongHocCapxdMuonDt', 'Decimal', 'Số thập phân', null, null),
  ('BG_00657', 'Số lượng phòng học đủ điều kiện tổ chức học nhóm - Đủ diện tích và bàn ghế', 'Là tổng số phòng học đảm bảo đủ diện tích theo quy định và được trang bị đầy đủ bàn ghế để tổ chức hoạt động học nhóm cho học sinh.', 'Thuộc tính định lượng phản ánh số lượng phòng học đủ điều kiện tổ chức học nhóm - Đủ diện tích và bàn ghế củacơ sở giáo dục. sử dụng', array['MOET34']::text[], 'phongHocDuDkTcHocNhomDuDtVaBanGhe', 'Integer', 'Số nguyên', null, null),
  ('BG_00658', 'Số lượng phòng học đủ điều kiện tổ chức học nhóm - Đủ diện tích - thiếu bàn ghế', 'Là tổng số phòng học có diện tích đảm bảo theo quy định nhưng chưa được trang bị đầy đủ bàn ghế phục vụ hoạt động học nhóm.', 'Thuộc tính định lượng phản ánh số lượng phòng học đủ điều kiện tổ chức học nhóm - Đủ diện tích - thiếu bàn ghế của cơ sở giáo dục.', array['MOET34']::text[], 'phongHocDuDkTcHocNhomDuDtThieuBanGhe', 'Integer', 'Số nguyên', null, null),
  ('BG_00659', 'Số lượng phòng học đủ điều kiện tổ chức học nhóm - Đủ bàn ghế - thiếu diện tích', 'Là tổng số phòng học đã được trang bị đủ bàn ghế phục vụ học nhóm nhưng diện tích phòng học chưa đáp ứng theo quy định để tổ chức hoạt động học nhóm hiệu quả.', 'Thuộc tính định lượng phản ánh số lượng phòng học đủ điều kiện tổ chức học nhóm - Đủ bàn ghế - thiếu diện tích của cơ sở giáo dục.', array['MOET34']::text[], 'phongHocDuDkTcHocNhomDuBanGheThieuDt', 'Integer', 'Số nguyên', null, null),
  ('BG_00660', 'Số lượng khu vệ sinh đạt chuẩn cho cán bộ/nhà giáo Nam', 'Là tổng số khu vệ sinh dành cho cán bộ/nhà giáo nam đáp ứng các tiêu chuẩn theo quy định về cơ sở vật chất trường học, đảm bảo yêu cầu về diện tích, trang thiết bị, vệ sinh và điều kiện sử dụng.', 'Thuộc tính định lượng phản ánh số lượng khu vệ sinh đạt chuẩn cho cán bộ/nhà giáo Nam của cơ sở giáo dục.', array['MOET34']::text[], 'soLuongKhuVeSinhDatChuanChoCbNgNam', 'Integer', 'Số nguyên', null, null),
  ('BG_00661', 'Diện tích khu vệ sinh đạt chuẩn cho cán bộ/nhà giáo Nam', 'Là tổng diện tích các khu vệ sinh dành cho cán bộ/nhà giáo nam đáp ứng tiêu chuẩn theo quy định về cơ sở vật chất trường học.', 'Thuộc tính định lượng phản ánh diện tích khu vệ sinh đạt chuẩn cho cán bộ/nhà sử dụng giáo Nam của cơ sở giáo dục.', array['MOET34']::text[], 'dienTichKhuVeSinhDatChuanChoCbNgNam', 'Integer', 'Số nguyên', null, null),
  ('BG_00662', 'Diện tích khu vệ sinh đạt chuẩn cho cán bộ/nhà giáo Nữ', 'Là tổng diện tích các khu vệ sinh dành cho cán bộ/nhà giáo nữ đáp ứng tiêu chuẩn theo quy định về cơ sở vật chất trường học.', 'Thuộc tính định lượng phản ánh diện tích khu vệ sinh đạt chuẩn cho cán bộ/nhà giáo Nữ của cơ sở giáo dục.', array['MOET34']::text[], 'dienTichKhuVeSinhDatChuanChoCbNgNu', 'Integer', 'Số nguyên', null, null),
  ('BG_00663', 'Số lượng khu vệ sinh đạt chuẩn cho cán bộ/nhà giáo Nữ', 'Là tổng số khu vệ sinh dành cho cán bộ/nhà giáo nữ đáp ứng các tiêu chuẩn theo quy định về cơ sở vật chất trường học.', 'Thuộc tính định lượng phản ánh số lượng khu vệ sinh đạt chuẩn cho cán bộ/nhà giáo Nữ của cơ sở giáo dục.', array['MOET34']::text[], 'soLuongKhuVeSinhDatChuanChoCbNgNu', 'Integer', 'Số nguyên', null, null),
  ('BG_00664', 'Diện tích khu vệ sinh đạt chuẩn cho học sinh Nam', 'Là tổng diện tích các khu vệ sinh dành cho học sinh nam đáp ứng tiêu chuẩn theo quy định về cơ sở vật chất trường học.', 'Thuộc tính định lượng phản ánh diện tích khu vệ sinh đạt chuẩn cho học sinh Nam của cơ sở giáo dục.', array['MOET34']::text[], 'khuVsDatChuanVsHsNamSl', 'Integer', 'Số nguyên', null, null),
  ('BG_00665', 'Số lượng khu vệ sinh đạt chuẩn cho học sinh Nam', 'Là tổng số khu vệ sinh dành cho học sinh nam đáp ứng các tiêu chuẩn theo quy định về cơ sở vật chất trường học.', 'Thuộc tính định lượng phản ánh số lượng khu vệ sinh đạt chuẩn cho học sinh Nam của cơ sở giáo dục.', array['MOET34']::text[], 'khuVsDatChuanVsHsNamDt', 'Decimal', 'Số thập phân', null, null),
  ('BG_00666', 'Diện tích khu vệ sinh đạt chuẩn cho học sinh Nữ', 'Là tổng diện tích các khu vệ sinh dành cho học sinh nữ đáp ứng tiêu chuẩn theo quy định về cơ sở vật chất trường học.', 'Thuộc tính định lượng phản ánh diện tích khu vệ sinh đạt chuẩn cho học sinh Nữ của cơ sở giáo dục.', array['MOET34']::text[], 'khuVsDatChuanVsHsNuSl', 'Integer', 'Số nguyên', null, null),
  ('BG_00667', 'Số lượng khu vệ sinh đạt chuẩn cho học sinh Nữ', 'Là tổng số khu vệ sinh dành cho học sinh nữ đáp ứng các tiêu chuẩn theo quy định về cơ sở vật chất trường học, đảm bảo đủ số lượng, diện tích và điều kiện vệ sinh theo quy định ngành giáo dục.', 'Thuộc tính định lượng phản ánh số lượng khu vệ sinh đạt chuẩn cho học sinh Nữ của cơ sở giáo dục.', array['MOET34']::text[], 'khuVsDatChuanVsHsNuDt', 'Decimal', 'Số thập phân', null, null),
  ('BG_00668', 'Diện tích nhà xe cán bộ/nhà giáo', 'Là tổng diện tích khu vực nhà xe được bố trí dành riêng cho cán bộ/nhà giáo trong khuôn viên cơ sở giáo dục, dùng để phục vụ nhu cầu gửi xe của cán bộ/nhà giáo.', 'Thuộc tính định lượng phản ánh diện tích nhà xe cán bộ/nhà giáo của cơ sở giáo dục.', array['MOET34']::text[], 'dienTichNhaXeCbNg', 'Integer', 'Số nguyên', null, null),
  ('BG_00669', 'Số lượng nhà xe cán bộ/nhà giáo', 'Là tổng số khu vực nhà xe được bố trí dành riêng cho cán bộ/nhà giáo trong khuôn viên cơ sở giáo dục, phục vụ nhu cầu gửi phương tiện của cán bộ/nhà giáo.', 'Thuộc tính định lượng phản ánh số lượng nhà xe cán bộ/nhà giáo của cơ sở giáo dục.', array['MOET34']::text[], 'soLuongNhaXeCbNg', 'Integer', 'Số nguyên', null, null),
  ('BG_00670', 'Diện tích nhà xe học sinh', 'Là tổng diện tích khu vực nhà xe được bố trí dành cho học sinh trong khuôn viên cơ sở giáo dục, phục vụ nhu cầu gửi phương tiện của học sinh và đảm bảo điều kiện an toàn, thuận tiện trong quá trình học tập.', 'Thuộc tính định lượng phản ánh diện tích nhà xe học sinh của cơ sở giáo dục.', array['MOET34']::text[], 'nhaXeHsDt', 'Integer', 'Số nguyên', null, null),
  ('BG_00671', 'Số lượng nhà xe học sinh', 'Là tổng số khu vực nhà xe được bố trí dành riêng cho học sinh trong khuôn viên cơ sở giáo dục, phục vụ nhu cầu gửi phương tiện của học sinh.', 'Thuộc tính định lượng phản ánh số lượng nhà xe học sinh của cơ sở giáo dục.', array['MOET34']::text[], 'nhaXeHsSl', 'Decimal', 'Số thập phân', null, null),
  ('BG_00672', 'Số Lớp Ghép của điểm trường', 'Là tổng số lớp học tại một cơ sở phụ (điểm trường) nơi một cán bộ/nhà giáo giảng dạy cùng lúc nhiều trình độ (lớp) khác nhau.', 'Thuộc tính định lượng phản ánh số Lớp Ghép của điểm trường của cơ sở giáo dục.', array['MOET34']::text[], 'lopGhepDiemTruong', 'Integer', 'Số nguyên', null, null),
  ('BG_00673', 'Số lớp lớp 1 của điểm trường', 'Là tổng số lớp học khối lớp 1 được tổ chức tại một điểm trường trong năm học.', 'Thuộc tính định lượng phản ánh số lớp lớp 1 của điểm trường', array['MOET34']::text[], 'lop1SoLopDiemTruong', 'Integer', 'Số nguyên', null, null),
  ('BG_00674', 'Tổng số học sinh lớp 1 của điểm trường', 'Là tổng số học sinh đang theo học khối lớp 1 tại một điểm trường trong năm học, bao gồm tất cả học sinh nam, nữ, học sinh dân tộc và học sinh khuyết tật (nếu có).', 'Thuộc tính định lượng phản ánh tổng số học sinh lớp 1 của điểm trường.', array['MOET34']::text[], 'lop1HsTongSoDiemTruong', 'Integer', 'Số nguyên', null, null),
