  ('BG_00716', 'Số lớp lớp 4', 'Là tổng số lớp học khối lớp 4 được tổ chức trong cơ sở giáo dục trong năm học.', 'Thuộc tính định lượng phản ánh số lớp lớp 4 của cơ sở giáo dục', array['MOET34']::text[], 'lop4SoLop', 'Integer', 'Số nguyên', null, null),
  ('BG_00717', 'Số học sinh lớp 4', 'Là tổng số học sinh đang theo học lớp 4 trong cơ sở giáo dục hoặc phạm vi thống kê trong năm học.', 'Thuộc tính định lượng phản ánh số học sinh lớp 4 của cơ sở giáo dục.', array['MOET34']::text[], 'lop4SoHs', 'Integer', 'Số nguyên', null, null),
  ('BG_00718', 'Số lớp lớp 5', 'Là tổng số lớp học khối lớp 5 được tổ chức trong cơ sở giáo dục trong năm học.', 'Thuộc tính định lượng phản ánh số lớp lớp 5 của cơ sở giáo dục', array['MOET34']::text[], 'lop5SoLop', 'Integer', 'Số nguyên', null, null),
  ('BG_00719', 'Số học sinh lớp 5', 'Là tổng số học sinh đang theo học lớp 5 trong cơ sở giáo dục hoặc phạm vi thống kê trong năm học.', 'Thuộc tính định lượng phản ánh số học sinh lớp 5 của cơ sở giáo dục.', array['MOET34']::text[], 'lop5SoHs', 'Integer', 'Số nguyên', null, null),
  ('BG_00720', 'Số lớp trong tổng số lớp ghép', 'Là tổng số nhóm trình độ (trình độ lớp) khác nhau được gộp lại và giảng dạy cùng một lúc bởi một cán bộ/nhà giáo, thường là 2-3 trình độ.', 'Thuộc tính định lượng phản ánh số lớp trong tổng số lớp ghép.', array['MOET34']::text[], 'trongTongSoLopGhepSoLop', 'Integer', 'Số nguyên', null, null),
  ('BG_00721', 'Số học sinh trong tổng số lớp ghép', 'Là sĩ số học sinh tối đa được phép trong một lớp học gồm nhiều trình độ, thường quy định là không quá 15 học sinh/lớp (đối với lớp ghép 2-3 trình độ)', 'Thuộc tính định lượng phản ánh số học sinh trong tổng số lớp ghép của cơ sở giáo dục.', array['MOET34']::text[], 'trongTongSoLopGhepSoHs', 'Integer', 'Số nguyên', null, null),
  ('BG_00722', 'Số lượng cơ sở vật chất phòng học trên cấp 4', 'Là tổng số phòng học được xây dựng theo tiêu chuẩn kiên cố trên cấp IV (cấp III, cấp II, cấp I) trong cơ sở giáo dục.', 'Thuộc tính định lượng phản ánh số lượng cơ sở vật chất phòng học trên cấp 4 của cơ sở giáo dục.', array['MOET34']::text[], 'trenCap4SoLuong', 'Integer', 'Số nguyên', null, null),
  ('BG_00723', 'Diện tích cơ sở vật chất phòng học trên cấp 4', 'Là tổng diện tích các phòng học được xây dựng kiên cố trên cấp IV (cấp III, cấp II, cấp I) trong cơ sở giáo dục.', 'Thuộc tính định lượng phản ánh diện tích cơ sở vật chất phòng học trên cấp 4 của cơ sở giáo dục.', array['MOET34']::text[], 'trenCap4DienTich', 'Decimal', 'Số thập phân', null, null),
  ('BG_00724', 'Số lượng cơ sở vật chất phòng học cấp 4', 'Là tổng số phòng học được xây dựng theo tiêu chuẩn công trình cấp IV trong cơ sở giáo dục.', 'Thuộc tính định lượng phản ánh số lượng cơ sở vật chất phòng học cấp 4 của cơ sở giáo dục.', array['MOET34']::text[], 'cap4SoLuong', 'Integer', 'Số nguyên', null, null),
  ('BG_00725', 'Diện tích cơ sở vật chất phòng học cấp 4', 'Là tổng diện tích các phòng học được xây dựng theo tiêu chuẩn công trình cấp IV trong cơ sở giáo dục.', 'Thuộc tính định lượng phản ánh diện tích cơ sở vật chất phòng học cấp 4 của cơ sở giáo dục.', array['MOET34']::text[], 'cap4DienTich', 'Decimal', 'Số thập phân', null, null),
  ('BG_00726', 'Số lượng cơ sở vật chất phòng học dưới cấp 4', 'Là tổng số phòng học có cấp xây dựng tạm, bán kiên cố hoặc chưa đạt tiêu chuẩn cấp IV trong cơ sở giáo dục.', 'Thuộc tính định lượng phản ánh số lượng cơ sở vật chất phòng học dưới cấp 4 của cơ sở giáo dục.', array['MOET34']::text[], 'duoiCap4SoLuong', 'Integer', 'Số nguyên', null, null),
  ('BG_00727', 'Diện tích cơ sở vật chất phòng học dưới cấp 4', 'Là tổng diện tích các phòng học có cấp xây dựng tạm, bán kiên cố hoặc chưa đạt tiêu chuẩn cấp IV trong cơ sở giáo dục.', 'Thuộc tính định lượng phản ánh diện tích cơ sở vật chất phòng học dưới cấp 4 của cơ sở giáo dục.', array['MOET34']::text[], 'duoiCap4DienTich', 'Decimal', 'Số thập phân', null, null),
  ('BG_00728', 'Số lượng phòng học mượn', 'Là tổng số phòng học được cơ sở giáo dục mượn từ đơn vị khác để phục vụ hoạt động giảng dạy.', 'Thuộc tính định lượng phản ánh số lượng phòng học mượn của cơ sở giáo dục', array['MOET34']::text[], 'muonSoLuong', 'Integer', 'Số nguyên', null, null),
  ('BG_00729', 'Diện tích phòng học mượn', 'Là tổng diện tích các phòng học được cơ sở giáo dục mượn từ đơn vị khác để phục vụ hoạt động giảng dạy.', 'Thuộc tính định lượng phản ánh diện tích phòng học mượn của cơ sở giáo dục', array['MOET34']::text[], 'muonDienTich', 'Decimal', 'Số thập phân', null, null),
  ('BG_00730', 'Số lượng nhà vệ sinh cho cán bộ/nhà giáo nam', 'Là tổng số khu vệ sinh được bố trí dành riêng cho cán bộ/nhà giáo nam trong cơ sở giáo dục.', 'Thuộc tính định lượng phản ánh số lượng nhà vệ sinh cho cán bộ/nhà giáo nam của cơ sở giáo dục. sử dụng', array['MOET34']::text[], 'slNvsCbna', 'Integer', 'Số nguyên', null, null),
  ('BG_00731', 'Diện tích nhà vệ sinh cho cán bộ/nhà giáo nam', 'Là tổng diện tích các khu vệ sinh được bố trí dành riêng cho cán bộ/nhà giáo nam trong cơ sở giáo dục.', 'Thuộc tính định lượng phản ánh diện tích nhà vệ sinh cho cán bộ/nhà giáo nam của cơ sở giáo dục.', array['MOET34']::text[], 'dtNvsCbna', 'Integer', 'Số nguyên', null, null),
