  ('BG_00757', 'Tổng số nữ lớp 4', 'Là tổng số học sinh nữ đang theo học lớp 4 trong cơ sở giáo dục hoặc phạm vi thống kê trong năm học.', 'Thuộc tính định lượng phản ánh tổng số học sinh nữ lớp 4 của cơ sở giáo dục', array['MOET34']::text[], 'lop4Nu', 'Integer', 'Số nguyên', null, null),
  ('BG_00758', 'Tổng số dân tộc lớp 4', 'Là tổng số học sinh dân tộc thiểu số đang theo học lớp 4 trong cơ sở giáo dục hoặc phạm vi thống kê trong năm học.', 'Thuộc tính định lượng phản ánh tổng số học sinh dân tộc lớp 4 của cơ sở giáo dục', array['MOET34']::text[], 'lop4DanToc', 'Integer', 'Số nguyên', null, null),
  ('BG_00759', 'Tổng số nữ dân tộc lớp 4', 'Là tổng số học sinh nữ dân tộc thiểu số đang theo học lớp 4 trong cơ sở giáo dục hoặc phạm vi thống kê trong năm học.', 'Thuộc tính định lượng phản ánh tổng số học sinh nữ dân tộc lớp 4 của cơ sở giáo dục', array['MOET34']::text[], 'lop4NuDanToc', 'Integer', 'Số nguyên', null, null),
  ('BG_00760', 'Tổng số lớp ghép lớp 4', 'Là tổng số lớp 4 được tổ chức theo hình thức lớp ghép trong cơ sở giáo dục.', 'Thuộc tính định lượng phản ánh tổng số lớp ghép lớp 4 của cơ sở giáo dục', array['MOET34']::text[], 'lop4LopGhep', 'Integer', 'Số nguyên', null, null),
  ('BG_00761', 'Tổng số khuyết tật lớp 4', 'Là tổng số học sinh khuyết tật đang theo học lớp 4 trong cơ sở giáo dục hoặc phạm vi thống kê trong năm học.', 'Thuộc tính định lượng phản ánh tổng số học sinh khuyết tật lớp 4 của cơ sở giáo dục', array['MOET34']::text[], 'lop4KhuyetTat', 'Integer', 'Số nguyên', null, null),
  ('BG_00762', 'Tổng số lớp 5', 'Là tổng số lớp học khối lớp 5 được tổ chức trong cơ sở giáo dục hoặc phạm vi thống kê trong năm học.', 'Thuộc tính định lượng phản ánh tổng số lớp 5 của cơ sở giáo dục', array['MOET34']::text[], 'lop5TongSo', 'Integer', 'Số nguyên', null, null),
  ('BG_00763', 'Tổng số nữ lớp 5', 'Là tổng số học sinh nữ đang theo học lớp 5 trong cơ sở giáo dục hoặc phạm vi thống kê trong năm học.', 'Thuộc tính định lượng phản ánh tổng số học sinh nữ lớp 5 của cơ sở giáo dục', array['MOET34']::text[], 'lop5Nu', 'Integer', 'Số nguyên', null, null),
  ('BG_00764', 'Tổng số dân tộc lớp 5', 'Là tổng số học sinh dân tộc thiểu số đang theo học lớp 5 trong cơ sở giáo dục hoặc phạm vi thống kê trong năm học.', 'Thuộc tính định lượng phản ánh tổng số học sinh dân tộc lớp 5 của cơ sở giáo dục', array['MOET34']::text[], 'lop5DanToc', 'Integer', 'Số nguyên', null, null),
  ('BG_00765', 'Tổng số nữ dân tộc lớp 5', 'Là tổng số học sinh nữ dân tộc thiểu số đang theo học lớp 5 trong cơ sở giáo dục hoặc phạm vi thống kê trong năm học.', 'Thuộc tính định lượng phản ánh tổng số học sinh nữ dân tộc lớp 5 của cơ sở giáo dục', array['MOET34']::text[], 'lop5NuDanToc', 'Integer', 'Số nguyên', null, null),
  ('BG_00766', 'Tổng số lớp ghép lớp 5', 'Là tổng số lớp 5 được tổ chức theo hình thức lớp ghép trong cơ sở giáo dục.', 'Thuộc tính định lượng phản ánh tổng số lớp ghép lớp 5 của cơ sở giáo dục', array['MOET34']::text[], 'lop5LopGhep', 'Integer', 'Số nguyên', null, null),
  ('BG_00767', 'Tổng số khuyết tật lớp 5', 'Là tổng số học sinh khuyết tật đang theo học lớp 5 trong cơ sở giáo dục hoặc phạm vi thống kê trong năm học.', 'Thuộc tính định lượng phản ánh tổng số học sinh khuyết tật lớp 5 của cơ sở giáo dục', array['MOET34']::text[], 'lop5KhuyetTat', 'Integer', 'Số nguyên', null, null),
  ('BG_00768', 'Tổng số điểm kiểm tra định kỳ', 'Là tổng các điểm số của bài kiểm tra giữa kỳ và cuối kỳ trong một học kỳ hoặc năm học, được dùng để đánh giá kết quả học tập sau từng giai đoạn.', 'Thuộc tính định lượng phản ánh tổng số điểm kiểm tra định kỳ của hoạt động thanh tra, kiểm tra chuyên ngành giáo dục.', array['MOET34']::text[], 'tongSo', 'Integer', 'Số nguyên', null, null),
  ('BG_00769', 'Tổng số cán bộ/nhà giáo hoàn thành tập huấn', 'Là tổng hợp dữ liệu các cán bộ/nhà giáo đã tham gia, nghiên cứu tài liệu, và vượt qua các yêu cầu/sản phẩm cuối khóa trong các chương trình bồi dưỡng chuyên môn, nghiệp vụ hoặc chương trình mới', 'Thuộc tính định lượng phản ánh tổng sử dụng số cán bộ/nhà giáo hoàn thành tập huấn của cơ sở giáo dục.', array['MOET34']::text[], 'tongSoCbNgHoanThanhTapHuan', 'Integer', 'Số nguyên', null, null),
  ('BG_00770', 'Tổng số cán bộ/nhà giáo nữ hoàn thành tập huấn', 'Là tổng số cán bộ/nhà giáo nữ đã tham gia và hoàn thành đầy đủ nội dung các chương trình tập huấn theo quy định trong kỳ báo cáo.', 'Thuộc tính định lượng phản ánh tổng số cán bộ/nhà giáo nữ hoàn thành tập huấn của cơ sở giáo dục.', array['MOET34']::text[], 'tongSoCbNgNuHoanThanhTapHuan', 'Integer', 'Số nguyên', null, null),
  ('BG_00771', 'Tổng số cán bộ/nhà giáo dân tộc hoàn thành tập huấn', 'Là số liệu thống kê báo cáo về đội ngũ nhà giáo người dân tộc thiểu số đã hoàn tất các khóa bồi dưỡng, nâng cao năng lực chuyên môn hoặc chương trình mới', 'Thuộc tính định lượng phản ánh tổng số cán bộ/nhà giáo dân tộc hoàn thành tập huấn của cơ sở giáo dục.', array['MOET34']::text[], 'tongSoCbNgDanTocHoanThanhTapHuan', 'Integer', 'Số nguyên', null, null),
  ('BG_00772', 'Tổng số HT và phó HT hoàn thành tập huấn', 'Tổng số HT (Hiệu trưởng) và phó HT (Phó Hiệu trưởng) hoàn thành tập huấn là chỉ số thống kê tổng hợp số lượng HT (Hiệu trưởng) và phó HT (Phó Hiệu trưởng) đã tham gia và đạt yêu cầu các chương trình bồi dưỡng, nâng cao năng lực chuyên môn, nghiệp vụ quản lý, hoặc tập huấn về chương trình giáo dục phổ thông mới do cơ quan quản lý giáo dục tổ chức', 'Thuộc tính định lượng phản ánh tổng số HT và phó HT hoàn thành tập huấn của cơ sở giáo dục.', array['MOET34']::text[], 'htvaphtHtthTongSo', 'Integer', 'Số nguyên', null, null),
  ('BG_00773', 'Tổng số HT và phó HT nữ hoàn thành tập huấn', 'Là chỉ số thống kê tổng lượng hiệu trưởng (HT) và phó hiệu trưởng nữ đã hoàn thành các khóa đào tạo, bồi dưỡng về chuyên môn hoặc quản lý. Đây là dữ liệu dùng để đánh giá năng lực lãnh đạo nữ và thực hiện bình đẳng giới trong ngành giáo dục', 'Thuộc tính định lượng phản ánh tổng số HT và phó HT nữ hoàn thành tập huấn của cơ sở giáo dục.', array['MOET34']::text[], 'htvaphtHtthNu', 'Integer', 'Số nguyên', null, null),
  ('BG_00774', 'Tổng số HT và phó HT dân tộc hoàn thành tập huấn', 'Tổng số HT (hiệu trưởng) và phó HT ( Phó Hiệu trưởng) dân tộc hoàn thành tập huấn là số liệu thống kê tổng cộng các lãnh đạo trường (hiệu trưởng, phó hiệu trưởng) là người dân tộc thiểu số đã tham gia và đạt yêu cầu các khóa bồi dưỡng, nâng cao năng lực quản lý, chuyên môn, hoặc kỹ năng sư phạm theo quy định của ngành giáo dục.', 'Thuộc tính định lượng phản ánh tổng số HT và phó HT dân tộc hoàn thành tập huấn của cơ sở giáo dục.', array['MOET34']::text[], 'htvaphtHtthDanToc', 'Integer', 'Số nguyên', null, null),
  ('BG_00775', 'Số lượng Người học tại trung tâm/ năm', 'Là thông tin thống kê số lượng người học tại trung tâm/năm', 'Thuộc tính đánh dấu số lượng Người học tại trung tâm/ năm của cơ sở giáo dục.', array['MOET34']::text[], 'isNh', 'Boolean', 'Đúng/Sai', '1', null),
  ('BG_00776', 'Tên sáng chế, giải pháp', 'Là tên gọi của sáng chế hoặc giải pháp hữu ích, phản ánh nội dung kỹ thuật hoặc mục đích sử dụng của giải pháp được đăng ký bảo hộ.', 'Thuộc tính ghi nhận tên sáng chế, giải pháp', array['MOET35']::text[], 'tenScGp', 'String', 'Chuỗi ký tự', '1000', null),
  ('BG_00777', 'Tên tổ chức', 'Là tên tổ chức thực hiện sáng chế, giải pháp', 'Thuộc tính ghi nhận tên tổ chức thực hiện sáng chế,giải pháp.', array['MOET35']::text[], 'tenToChucScGp', 'String', 'Chuỗi ký tự', '100', null),
  ('BG_00778', 'Loại sáng chế, giải pháp', 'Là phân loại các sáng chế, giải pháp.', 'Thuộc tính phân loại loại sáng chế, giải pháp.', array['MOET35']::text[], 'loaiScGp', 'Enumeration', 'Danh mục liệt kê', null, null),
  ('BG_00779', 'Năm được cấp bằng sáng chế, giải pháp', 'Là năm mà cơ quan có thẩm quyền cấp văn bằng bảo hộ sáng chế hoặc giải pháp hữu ích.', 'Thuộc tính ghi nhận mốc thời gian được cấp bằng sáng chế,giải pháp.', array['MOET35']::text[], 'namDuocCapBangScGp', 'Integer', 'Số nguyên', null, null),
  ('BG_00780', 'Tổ chức cấp bằng sáng chế, giải pháp', 'Là cơ quan nhà nước hoặc tổ chức có thẩm quyền cấp văn bằng bảo hộ sáng chế hoặc giải pháp hữu ích (ví dụ: Cục Sở hữu trí tuệ).', 'Thuộc tính mô tả tổ chức cấp bằng sáng chế, giải pháp', array['MOET35']::text[], 'toChucCapBangScGp', 'String', 'Chuỗi ký tự', '100', null),
  ('BG_00781', 'Số bằng sáng chế, giải pháp', 'Là mã quản lý số bằng sáng chế, giải pháp do cơ quan có thẩm quyền cấp.', 'Thuộc tính thể hiện số bằng sáng chế, giải pháp của cơ sở giáo dục đại học.', array['MOET35']::text[], 'soBangScGp', 'String', 'Chuỗi ký tự', '50', null),
  ('BG_00782', 'Ngày cấp bằng sáng chế, giải pháp', 'Là ngày văn bằng bảo hộ sáng chế hoặc giải pháp hữu ích được cấp chính thức.', 'Thuộc tính ghi nhận mốc thời gian ngày cấp bằng sáng chế, giải pháp của cơ sở giáo dục đại học.', array['MOET35']::text[], 'ngayCapScGp', 'Date', 'Ngày tháng', '10', 'CDE-TG-001'),
  ('BG_00783', 'Số đơn sáng chế, giải pháp', 'Là mã đơn đăng ký sáng chế hoặc giải pháp hữu ích do tổ chức/cá nhân nộp tại cơ quan có thẩm quyền.', 'Thuộc tính thể hiện số đơn sáng chế, giải pháp của cơ sở giáo dục đại học.', array['MOET35']::text[], 'soDonScGp', 'String', 'Chuỗi ký tự', '50', null),
  ('BG_00784', 'Công bố bằng sáng chế, giải pháp', 'Là thông tin về việc công bố sáng chế hoặc giải pháp hữu ích trên công báo sở hữu công nghiệp hoặc hệ thống thông tin chính thức.', 'Thuộc tính mô tả công bố bằng sáng chế, giải pháp của cơ sở giáo dục đại học.', array['MOET35']::text[], 'congBoBangScGp', 'String', 'Chuỗi ký tự', '50', null),
  ('BG_00785', 'IPC', 'Là mã Phân loại Sáng chế Quốc tế (International Patent Classification) áp dụng cho sáng chế hoặc giải pháp hữu ích.', 'Thuộc tính thể hiện mã phân loại sáng chế Quốc Tế.', array['MOET35']::text[], 'ipc', 'String', 'Chuỗi ký tự', '50', null),
  ('BG_00786', 'Chủ bằng sáng chế, giải pháp', 'Là tổ chức hoặc cá nhân sở hữu quyền đối với sáng chế hoặc giải pháp hữu ích được cấp văn bằng bảo hộ.', 'Thuộc tính ghi nhận chủ bằng sáng chế, giải pháp.', array['MOET35']::text[], 'chuBangScGp', 'String', 'Chuỗi ký tự', '100', null),
  ('BG_00787', 'Tác giả sáng chế/giải pháp', 'Là cá nhân trực tiếp tạo ra sáng chế hoặc giải pháp hữu ích bằng hoạt động nghiên cứu, sáng tạo.', 'Thuộc tính mô tả tác giả sáng chế/giải pháp.', array['MOET35']::text[], 'tacGiaSc', 'String', 'Chuỗi ký tự', '300', null),
  ('BG_00788', 'Tóm tắt sáng chế/giải pháp', 'Là phần mô tả ngắn gọn nội dung kỹ thuật, nguyên lý hoạt động và mục đích của sáng chế hoặc giải pháp hữu ích.', 'Thuộc tính mô tả tóm tắt sáng chế/giải pháp.', array['MOET35']::text[], 'tomTatSc', 'String', 'Chuỗi ký tự', '3000', null),
  ('BG_00789', 'Người chủ trì sáng chế, giải pháp', 'Là cá nhân chịu trách nhiệm chính trong việc nghiên cứu, phát triển hoặc triển khai sáng chế/giải pháp.', 'Thuộc tính mô tả người chủ trì sáng chế, giải pháp. sử dụng', array['MOET35']::text[], 'nguoiChuTriScGp', 'String', 'Chuỗi ký tự', '50', null),
  ('BG_00790', 'Tên chuyển giao công nghệ', 'Là tên gọi của hoạt động hoặc hợp đồng chuyển giao công nghệ giữa các bên.', 'Thuộc tính mô tả tên hoạt động hoặc hợp đồng chuyển giao công nghệ.', array['MOET35']::text[], 'tenChuyenGiaoCongNghe', 'String', 'Chuỗi ký tự', '1000', null),
  ('BG_00791', 'Tổng chi phí thực hiện chuyển giao công nghệ', 'Là toàn bộ các khoản ngân sách, bao gồm phí mua quyền sở hữu hoặc sử dụng công nghệ cộng với các chi phí triển khai thực tế (đào tạo, lắp đặt, vận hành, tư vấn kỹ thuật) mà bên nhận phải chi trả để chính thức làm chủ và ứng dụng công nghệ thành công', 'Thuộc tính thể hiện tổng kinh phí thực hiện chuyển giao công nghệ.', array['MOET35']::text[], 'tongChiPhiThucHienChuyenGiaoCongNghe', 'String', 'Chuỗi ký tự', '100', null),
  ('BG_00792', 'Tổng thời gian thực hiện chuyển giao công nghệ', 'Là khoảng thời gian được các bên thỏa thuận trong hợp đồng, bắt đầu từ ngày hợp đồng có hiệu lực cho đến khi các bên hoàn thành toàn bộ nghĩa vụ theo cam kết, bao gồm việc bàn giao, lắp đặt, vận hành thử nghiệm, và chuyển giao bí quyết kỹ thuật', 'Thuộc tính mô tả thời hạn thực hiện hoạt động chuyển giao công nghệ.', array['MOET35']::text[], 'thoiGianThucHienChuyenGiaoCongNghe', 'String', 'Chuỗi ký tự', '100', null),
  ('BG_00793', 'Hình thức chuyển giao công nghệ', 'Là các hình thức chuyển nhượng quyền sở hữu hoặc quyền sử dụng công nghệ từ bên có quyền chuyển giao sang bên nhận công nghệ.', 'Thuộc tính thể hiện hình thức chuyển giao công nghệ.', array['MOET35']::text[], 'hinhThucChuyenGiaoCongNghe', 'String', 'Chuỗi ký tự', '255', null),
  ('BG_00794', 'Phương thức chuyển giao công nghệ', 'Là cách các bên phối hợp để chuyển giao công nghệ.', 'Thuộc tính mô tả phương thức thực hiện chuyển giao công nghệ.', array['MOET35']::text[], 'phuongThucChuyenGiaoCongNghe', 'String', 'Chuỗi ký tự', '255', null),
  ('BG_00795', 'Chủ sở hữu chuyển giao công nghệ', 'Là tổ chức hoặc cá nhân nắm quyền sở hữu công nghệ được chuyển giao.', 'Thuộc tính ghi nhận chủ sở hữu công nghệ được chuyển giao.', array['MOET35']::text[], 'chuSoHuuChuyenGiaoCongNghe', 'String', 'Chuỗi ký tự', '100', null),
  ('BG_00796', 'Đơn vị chủ trì chuyển giao công nghệ', 'Là tổ chức chịu trách nhiệm chính trong việc tổ chức và triển khai hoạt động chuyển giao công nghệ.', 'Thuộc tính mô tả đơn vị chủ trì hoạt động chuyển giao công nghệ.', array['MOET35']::text[], 'donViChuTriChuyenGiaoCongNghe', 'String', 'Chuỗi ký tự', '100', null),
  ('BG_00797', 'Đơn vị phối hợp chuyển giao công nghệ', 'Là các tổ chức tham gia hỗ trợ, phối hợp thực hiện quá trình chuyển giao công nghệ.', 'Thuộc tính ghi nhận các đơn vị phối hợp thực hiện chuyển giao công nghệ.', array['MOET35']::text[], 'donViPhoiHopChuyenGiaoCongNghe', 'String', 'Chuỗi ký tự', '100', null),
  ('BG_00798', 'Đơn vị nhận chuyển giao công nghệ', 'Là các tổ chức tiếp nhận quá trình chuyển giao công nghệ.', 'Thuộc tính ghi nhận đơn vị tiếp nhận công nghệ được chuyển giao.', array['MOET35']::text[], 'donViNhanChuyenGiaoCongNghe', 'String', 'Chuỗi ký tự', '100', null),
  ('BG_00799', 'Vai trò cán bộ/nhà giáo trong chuyển giao công nghệ', 'Là vai trò cán bộ/nhà giáo trong chuyển giao công nghê.', 'Thuộc tính thể hiện vai trò của cán bộ, nhà giáo trong hoạt động chuyển giao công nghệ.', array['MOET35']::text[], 'vaiTroChuyenGiaoCongNghe', 'Enumeration', 'Danh mục liệt kê', null, null),
  ('BG_00800', 'Tên tổ chức sáng chế/giải pháp', 'Là tên tổ chức đứng tên hoặc có liên quan đến quyền sở hữu, đăng ký hoặc quản lý sáng chế/giải pháp.', 'Thuộc tính ghi nhận tổ chức liên quan đến quyền sở hữu, đăng ký hoặc quản lý sáng chế, giải pháp.', array['MOET35']::text[], 'tenToChucScGp', 'String', 'Chuỗi ký tự', '200', null),
  ('BG_00801', 'Năm chuyển giao công nghệ', 'Là năm diễn ra hoặc hoàn thành hoạt động chuyển giao công nghệ.', 'Thuộc tính thể hiện năm thực hiện hoặc hoàn thành hoạt động chuyển giao công nghệ.', array['MOET35']::text[], 'namChuyenGiaoCongNghe', 'Integer', 'Số nguyên', null, null),
  ('BG_00802', 'Tên hợp tác quốc tế', 'Là tên chương trình, dự án hoặc thỏa thuận hợp tác giữa các tổ chức trong nước và nước ngoài.', 'Thuộc tính ghi nhận tên hợp tác quốc tế.', array['MOET36']::text[], 'tenHtqt', 'String', 'Chuỗi ký tự', '100', null),
  ('BG_00803', 'Nội dung hợp tác quốc tế', 'Là mô tả các hoạt động hợp tác như nghiên cứu, đào tạo, chuyển giao công nghệ hoặc trao đổi chuyên gia.', 'Thuộc tính mô tả nội dung hợp tác quốc tế.', array['MOET36']::text[], 'noiDungHtqt', 'String', 'Chuỗi ký tự', 'Max', null),
  ('BG_00804', 'Ngày ký kết hợp tác quốc tế', 'Là ngày các bên chính thức ký kết thỏa thuận hợp tác.', 'Thuộc tính ghi nhận mốc thời gian ngày ký kết hợp tác quốc tế.', array['MOET36']::text[], 'ngayKyKetHtqt', 'Date', 'Ngày tháng', '10', 'CDE-TG-001'),
  ('BG_00805', 'Kết quả hợp tác quốc tế', 'Là các sản phẩm, kết quả hoặc lợi ích đạt được từ hoạt động hợp tác.', 'Thuộc tính mô tả kết quả hợp tác quốc tế.', array['MOET36']::text[], 'ketQuaHtqt', 'String', 'Chuỗi ký tự', '2000', null),
  ('BG_00806', 'Loại tổ chức hợp tác quốc tế', 'Là phân loại tổ chức đối tác nước ngoài.', 'Thuộc tính mô tả loại tổ chức hợp tác quốc tế.', array['MOET36']::text[], 'loaiToChucHtqt', 'String', 'Chuỗi ký tự', '100', null),
  ('BG_00807', 'Tên hợp tác doanh nghiệp', 'Là tên chương trình hoặc thỏa thuận hợp tác giữa tổ chức nghiên cứu/đào tạo với doanh nghiệp.', 'Thuộc tính ghi nhận tên hợp tác doanh nghiệp.', array['MOET36']::text[], 'tenHopTacDn', 'String', 'Chuỗi ký tự', '100', null),
  ('BG_00808', 'Nội dung hợp tác doanh nghiệp', 'Là mô tả các hoạt động hợp tác như nghiên cứu ứng dụng, chuyển giao công nghệ, đào tạo nhân lực...', 'Thuộc tính mô tả nội dung hợp tác doanh nghiệp.', array['MOET36']::text[], 'noiDungHopTacDn', 'String', 'Chuỗi ký tự', 'Max', null),
  ('BG_00809', 'Ngày ký kết hợp tác doanh nghiệp', 'Là ngày ký kết thỏa thuận hợp tác doanh nghiệp giữa các bên.', 'Thuộc tính ghi nhận mốc thời gian ký kết thỏa thuận hợp tác doanh nghiệp.', array['MOET36']::text[], 'ngayKyKetHopTacDn', 'Date', 'Ngày tháng', '10', 'CDE-TG-001'),
  ('BG_00810', 'Kết quả hợp tác doanh nghiệp', 'Là các sản phẩm, giá trị hoặc hiệu quả đạt được từ hợp tác.', 'Thuộc tính mô tả kết quả hợp tác doanh nghiệp.', array['MOET36']::text[], 'ketQuaHopTacDn', 'String', 'Chuỗi ký tự', '2000', null),
  ('BG_00811', 'Loại tổ chức hợp tác doanh nghiệp', 'Là phân loại doanh nghiệp tham gia hợp tác.', 'Thuộc tính phân loại loại tổ chức hợp tác doanh nghiệp.', array['MOET36']::text[], 'loaiToChucHopTacDn', 'String', 'Chuỗi ký tự', '100', null),
  ('BG_00812', 'Thông tư phát hành văn bằng số, chứng chỉ số', 'Là thông tư quy định về việc cấp văn bằng số, chứng chỉ số.', 'Thuộc tính mô tả thông tư phát hành văn bằng số, chứng chỉ số của người học.', array['MOET39']::text[], 'thongTuPhatHanhVanBangChungChiSo', 'String', 'Chuỗi ký tự', '255', null),
  ('BG_00813', 'Chương trình giáo dục cơ bản', 'Chương trình giáo dục cơ bản (hay giai đoạn giáo dục cơ bản) tại Việt Nam là giai đoạn từ lớp 1 đến lớp 9 (bao gồm tiểu học và trung học cơ sở), thuộc chương trình giáo dục phổ thông. Mục tiêu là trang bị nền tảng kiến thức, kỹ năng thiết yếu, phát triển phẩm chất và năng lực toàn diện cho học sinh trước khi phân luồng định hướng nghề nghiệp.', 'Thuộc tính đánh dấu chương trình giáo dục cơ bản của chương trình giáo dục và đào tạo (giá trị có/không).', array['MOET39']::text[], 'isChuongTrinhGiaoDucCoBan', 'Boolean', 'Đúng/Sai', '1', null),
  ('BG_00814', 'Danh mục ngoại ngữ 1', 'Là các môn ngoại ngữ 1 (ngoại ngữ bắt buộc) thường bao gồm các ngôn ngữ phổ biến được giảng dạy trong hệ thống giáo dục Việt Nam, chủ yếu là tiếng Anh (thường được mã hóa ưu tiên), cùng tiếng Nga, Pháp, Trung Quốc, Đức, Nhật, Hàn.', 'Thuộc tính phân loại danh mục ngoại ngữ 1 mà cơ sở giáo dục lựa chọn đào tạo cho các học sinh thuộc 1 lớp học nào đó.', array['MOET39']::text[], 'ngoaiNgu1', 'Enumeration', 'Danh mục liệt kê', null, null),
  ('BG_00815', 'Danh mục ngoại ngữ 2', 'Là các môn ngoại ngữ 2 (NN2) là môn học tự chọn, không bắt buộc, được giảng dạy theo nhu cầu học sinh và điều kiện của các nhà trường, nhằm bổ trợ cho ngoại ngữ 1.', 'Thuộc tính phân loại danh mục ngoại ngữ 2 mà cơ sở giáo dục lựa chọn đào tạo cho các học sinh thuộc 1 lớp học nào đó.', array['MOET39']::text[], 'ngoaiNgu2', 'Enumeration', 'Danh mục liệt kê', null, null),
  ('BG_00816', 'Học chương trình GD của bộ', 'là việc học theo khung chuẩn quốc gia do Bộ giáo dục và đào tạo ban hành, tập trung phát triển phẩm chất và năng lực người học thay vì chỉ truyền thụ kiến thức.', 'Thuộc tính đánh dấu học chương trình giáo dục của bộ.', array['MOET39']::text[], 'isHocCtgdCuaBo', 'Boolean', 'Đúng/Sai', '1', null),
  ('BG_00817', 'Học kỳ', 'là một giai đoạn, một phân đoạn thời gian cụ thể trong năm học.', 'Thuộc tính mô tả học kỳ cụ thể như học kỳ 1, học kỳ 2.', array['MOET39']::text[], 'hocKy', 'String', 'Chuỗi ký tự', '1', null),
  ('BG_00818', 'Môn học', 'Là môn học được quy định trong các chương trình giáo dục thuộc hệ thống giáo dục quốc dân.', 'Thuộc tính tên môn học dùng để quản lý trong chương trình giáo dục và đào tạo.', array['MOET39']::text[], 'monHoc', 'Enumeration', 'Danh mục liệt kê', null, null),
  ('BG_00819', 'Có chương trình mầm non mới', 'Là thông tin xác nhận việc cơ sở giáo dục có thí điểm triển khai thực hiện Chương trình giáo dục Mầm non mới.', 'Thuộc tính đánh dấu có chương trình mầm non mới của cơ sở giáo dục (giá trị có/không).', array['MOET39']::text[], 'isCtgdmnMoi', 'Boolean', 'Đúng/Sai', '1', null),
  ('BG_00820', 'Có chương trình chăm sóc giáo dục', 'Là thông tin xác nhận việc cơ sở giáo dục có triển khai kế hoạch chương trình chăm sóc giáo dục mầm non.', 'Thuộc tính đánh dấu có chương trình chăm sóc giáo dục của cơ sở giáo dục (giá trị có/không).', array['MOET39']::text[], 'isCtCsgd', 'Boolean', 'Đúng/Sai', '1', null),
  ('BG_00821', 'Năm học', 'Là khoảng thời gian quy định (thường kéo dài khoảng 9-10 tháng, từ tháng 9 đến tháng 5 năm sau) để học sinh hoàn thành chương trình học tập của một lớp hoặc một cấp học.', 'Thuộc tính mô tả năm học cụ thể như 2025-2026', array['MOET39']::text[], 'tenNamHoc', 'String', 'Chuỗi ký tự', '30', null),
  ('BG_00822', 'Hình thức đào tạo', 'Là phương thức tổ chức, quản lý và thực hiện chương trình giảng dạy nhằm cung cấp kiến thức, kỹ năng chuyên môn cho người học tại các cơ sở giáo dục đại học.', 'Thuộc tính mô tả hình thức đào tạo của cơ sở giáo dục.', array['MOET39']::text[], 'hinhThucDaoTao', 'String', 'Chuỗi ký tự', '150', null),
  ('BG_00823', 'Mã ngành đào tạo', 'Là chuỗi ký tự do Bộ Giáo dục và Đào tạo quy định, dùng để phân loại, định danh các ngành học cụ thể trong tuyển sinh đại học và sau đại học.', 'Thuộc tính mô tả mã ngành đào tạo của cơ sở giáo dục.', array['MOET39']::text[], 'maNganhDaoTao', 'String', 'Chuỗi ký tự', '12', null),
  ('BG_00824', 'Chuyên ngành đào tạo của cơ sở giáo dục', 'Là một phần kiến thức và kỹ năng chuyên môn sâu có tính độc lập trong một ngành, do cơ sở giáo dục quyết định.', 'Thuộc tính mô tả chuyên ngành đào tạo của cơ sở giáo dục.', array['MOET39']::text[], 'chuyenNganhDaoTao', 'String', 'Chuỗi ký tự', '150', null),
  ('BG_00825', 'Ngôn ngữ đào tạo', 'Là ngôn ngữ giảng dạy trong chương trình đào tạo.', 'Thuộc tính mô tả ngôn ngữ đào tạo của chương trình đào tạo.', array['MOET39']::text[], 'ngonNguDaoTao', 'String', 'Chuỗi ký tự', '150', null),
  ('BG_00826', 'Thời gian khóa đào tạo', 'Là tổng thời gian bao gồm học tập, thi, kiểm tra và các hoạt động chung để người học hoàn thành chương trình đào tạo.', 'Thuộc tính mô tả thời gian khóa đào tạo của chương trình đào tạo.', array['MOET39']::text[], 'thoiGianDaoTao', 'String', 'Chuỗi ký tự', '150', null),
  ('BG_00827', 'Khối ngành đào tạo', 'Là tên gọi chính thức của khối ngành đào tạo.', 'Thuộc tính phân loại khối ngành đào tạo của cơ sở giáo dục.', array['MOET39']::text[], 'khoiNganhDaoTao', 'Enumeration', 'Danh mục liệt kê', null, null),
  ('BG_00828', 'Tên lĩnh vực đào tạo', 'Là tên gọi chính thức của lĩnh vực đào tạo.', 'Thuộc tính phân loại tên lĩnh vực đào tạo của cơ sở giáo dục.', array['MOET39']::text[], 'tenLinhVucDaoTao', 'Enumeration', 'Danh mục liệt kê', null, null),
  ('BG_00829', 'Nhóm ngành đào tạo', 'Là tập hợp các ngành đào tạo có nội dung chuyên môn gần nhau, được phân loại trong hệ thống giáo dục nhằm phục vụ quản lý và tổ chức đào tạo.', 'Thuộc tính phân loại nhóm ngành đào tạo của cơ sở giáo dục.', array['MOET39']::text[], 'nhomNganhDaoTao', 'Enumeration', 'Danh mục liệt kê', null, null),
  ('BG_00830', 'Tên ngành đào tạo', 'Là tên gọi cụ thể của một ngành đào tạo trong hệ thống giáo dục, xác định lĩnh vực chuyên môn mà người học được đào tạo và cấp bằng sau khi hoàn thành chương trình.', 'Thuộc tính phân loại tên ngành đào tạo của cơ sở giáo dục.', array['MOET39']::text[], 'tenNganhDaoTao', 'Enumeration', 'Danh mục liệt kê', null, null),
  ('BG_00831', 'Số quyết định cho phép mở ngành', 'Là số quyết định được xác định trong văn bản cho phép mở ngành do cơ quan có thẩm quyền ban hành.', 'Thuộc tính ghi nhận số quyết định cho phép mở ngành của cơ sở giáo dục.', array['MOET39']::text[], 'soQdMoNganh', 'String', 'Chuỗi ký tự', '50', null),
  ('BG_00832', 'Ngày quyết định cho phép mở ngành', 'Là ngày ghi trên số quyết định cho phép mở ngành do cơ quan có thẩm quyền ban hành.', 'Thuộc tính ghi nhận mốc thời gian ngày quyết định cho phép mở ngành của cơ sở giáo dục.', array['MOET39']::text[], 'ngayQdMoNganh', 'Date', 'Ngày tháng', '10', 'CDE-TG-001'),
  ('BG_00833', 'Số quyết định cho phép đổi tên ngành', 'Là số quyết định được xác định trong văn bản thành cho phép đổi tên ngành do cơ quan có thẩm quyền ban hành.', 'Thuộc tính ghi nhận số quyết định cho phép đổi tên ngành của cơ sở giáo dục.', array['MOET39']::text[], 'soQdDoiTenNganh', 'String', 'Chuỗi ký tự', '50', null),
  ('BG_00834', 'Ngày quyết định cho phép đổi tên ngành', 'Là ngày ghi trên số quyết định cho phép đổi tên ngành do cơ quan có thẩm quyền ban hành.', 'Thuộc tính ghi nhận mốc thời gian ngày quyết định cho phép đổi tên ngành của cơ sở giáo dục.', array['MOET39']::text[], 'ngayQdDoiTenNganh', 'Date', 'Ngày tháng', '10', 'CDE-TG-001'),
  ('BG_00835', 'Số quyết định cho phép đào tạo từ xa', 'Là số quyết định được xác định trong văn bản cho phép đào tạo từ xa do cơ quan có thẩm quyền ban hành.', 'Thuộc tính ghi nhận số quyết định cho phép đào tạo từ xa của cơ sở giáo dục.', array['MOET39']::text[], 'soQdDaoTaoTuXa', 'String', 'Chuỗi ký tự', '50', null),
  ('BG_00836', 'Ngày quyết định cho phép đào tạo từ xa', 'Là ngày ghi trên số quyết định cho phép đào tạo từ xa do cơ quan có thẩm quyền ban hành.', 'Thuộc tính ghi nhận mốc thời gian ngày quyết định cho phép đào tạo từ xa của cơ sở giáo dục.', array['MOET39']::text[], 'ngayQdDaoTaoTuXa', 'Date', 'Ngày tháng', '10', 'CDE-TG-001'),
  ('BG_00837', 'Có hình thức đào tạo theo chuyên ngữ', 'Là hình thức giảng dạy các chương trình, học phần, hoặc toàn bộ khối kiến thức chuyên ngành bằng một ngôn ngữ khác hoàn toàn Tiếng Việt.', 'Thuộc tính đánh dấu có hình thức đào tạo theo chuyên ngữ của chương trình giáo dục và đào tạo. sử dụng', array['MOET39']::text[], 'isChuyenNgu', 'Boolean', 'Đúng/Sai', '1', null),
  ('BG_00838', 'Số quyết định/văn bản cho phép mở ngành của loại hình đào tạo khác', 'Là số quyết định được xác định trong văn bản cho phép mở ngành của loại hình đào tạo khác do cơ quan có thẩm quyền ban hành.', 'Thuộc tính ghi nhận số quyết định/văn bản cho phép mở ngành của loại hình đào tạo khác của cơ sở giáo dục.', array['MOET39']::text[], 'soQdPheDuyetMoNganhDtKhac', 'String', 'Chuỗi ký tự', '50', null),
  ('BG_00839', 'Ngày quyết định/văn bản cho phép mở ngành của loại hình đào tạo khác', 'Là ngày ghi trên số quyết định cho phép mở ngành của loại hình đào tạo khác do cơ quan có thẩm quyền ban hành.', 'Thuộc tính ghi nhận mốc thời gian ngày quyết định/văn bản cho phép mở ngành của loại hình đào tạo khác.', array['MOET39']::text[], 'ngayQdMoNganhDtKhac', 'Date', 'Ngày tháng', '10', 'CDE-TG-001'),
  ('BG_00840', 'Tên ngành đào tạo liên kết', 'Là tên ngành đào tạo được liên kết.', 'Thuộc tính tên ngành đào tạo mà cơ sở giáo dục liên kết với các cơ sở, tổ chức khác để đào tạo.', array['MOET39']::text[], 'tenNganhDtLienKet', 'String', 'Chuỗi ký tự', '255', null),
  ('BG_00841', 'Số quyết định/văn bản cho phép liên kết đào tạo', 'Là số quyết định được xác định trong văn bản cho phép liên kết đào tạo do cơ quan có thẩm quyền ban hành.', 'Thuộc tính ghi nhận số quyết định/văn bản cho phép liên kết đào tạo của cơ sở giáo dục.', array['MOET39']::text[], 'soQdPheDuyetDtLk', 'String', 'Chuỗi ký tự', '50', null),
  ('BG_00842', 'Ngày quyết định/văn bản cho phép liên kết đào tạo', 'Là ngày ghi trên số quyết định cho phép liên kết đào tạo do cơ quan có thẩm quyền ban hành.', 'Thuộc tính ghi nhận mốc thời gian ngày quyết định/văn bản cho phép liên kết đào tạo của cơ sở giáo dục.', array['MOET39']::text[], 'ngayQdPheDuyetDtLk', 'Date', 'Ngày tháng', '10', 'CDE-TG-001'),
  ('BG_00843', 'Địa điểm liên kết đào tạo', 'Là địa điểm cụ thể nơi tổ chức triển khai chương trình đào tạo liên kết', 'Thuộc tính mô tả địa điểm liên kết đào tạo của cơ sở giáo dục.', array['MOET39']::text[], 'diaDiemDtLk', 'String', 'Chuỗi ký tự', '255', null),
  ('BG_00844', 'Số quyết định phê duyệt chương trình đào tạo', 'Là số quyết định được xác định trong văn bản phê duyệt chương trình đào tạo do cơ quan có thẩm quyền ban hành.', 'Thuộc tính ghi nhận số quyết định phê duyệt chương trình đào tạo của cơ sở giáo dục.', array['MOET39']::text[], 'soQdPheDuyetCtdt', 'String', 'Chuỗi ký tự', '50', null),
  ('BG_00845', 'Ngày quyết định phê duyệt chương trình đào tạo', 'Là ngày ghi trên số quyết định phê duyệt chương trình đào tạo do cơ quan có thẩm quyền ban hành.', 'Thuộc tính ghi nhận mốc thời gian ngày quyết định phê duyệt chương trình đào tạo của cơ sở giáo dục.', array['MOET39']::text[], 'ngayQdPheDuyetCtdt', 'Date', 'Ngày tháng', '10', 'CDE-TG-001'),
  ('BG_00846', 'Năm bắt đầu tuyển sinh', 'Là năm bắt đầu tuyển sinh của chương trình đào tạo.', 'Thuộc tính định lượng phản ánh năm bắt đầu tuyển sinh của chương trình đào tạo đã được phê duyệt.', array['MOET39']::text[], 'namTuyenSinhCtdt', 'Integer', 'Số nguyên', '4', null),
  ('BG_00847', 'Quy mô học viên đang theo học chương trình đào tạo', 'Là tổng số người học hiện đang tham gia các chương trình đào tạo tại cơ sở đào tạo.', 'Thuộc tính mô tả quy mô học viên đang theo học chương trình đào tạo.', array['MOET39']::text[], 'quyMoHocVienDangTheoHocCtdt', 'String', 'Chuỗi ký tự', '100', null),
  ('BG_00848', 'Loại hình chương trình đào tạo', 'Là cách phân loại chương trình đào tạo theo đặc điểm tổ chức và triển khai.', 'Thuộc tính phân loại loại hình chương trình đào tạo.', array['MOET39']::text[], 'loaiHinhCtdt', 'Enumeration', 'Danh mục liệt kê', null, null),
  ('BG_00849', 'Loại chương trình đào tạo', 'Là phân loại chương trình đào tạo theo mục tiêu và nội dung đào tạo cụ thể.', 'Thuộc tính phân loại loại chương trình đào tạo.', array['MOET39']::text[], 'loaiCtdt', 'Enumeration', 'Danh mục liệt kê', null, null),
  ('BG_00850', 'Loại hình đào tạo', 'Là hình thức tổ chức hoạt động đào tạo trong một chương trình đào tạo, phản ánh cách thức người học tham gia học tập.', 'Thuộc tính phân loại loại hình đào tạo của chương trình đào tạo.', array['MOET39']::text[], 'loaiHinhDaoTao', 'Enumeration', 'Danh mục liệt kê', null, null),
  ('BG_00851', 'Phương thức đào tạo', 'Là cách thức triển khai hoạt động giảng dạy và học tập, bao gồm phương pháp tổ chức lớp học, hình thức học tập và tương tác của chương trình đào tạo.', 'Thuộc tính mô tả phương thức đào tạo của chương trình đào tạo.', array['MOET39']::text[], 'phuongThucDaoTao', 'String', 'Chuỗi ký tự', '100', null),
  ('BG_00852', 'Địa điểm đào tạo', 'Là địa điểm cụ thể nơi tổ chức triển khai chương trình đào tạo.', 'Thuộc tính mô tả địa điểm đào tạo của chương trình đào tạo.', array['MOET39']::text[], 'diaDiemDaoTao', 'String', 'Chuỗi ký tự', '100', null),
  ('BG_00853', 'Học chế đào tạo', 'Là cách thức tổ chức, quản lý quá trình dạy và học tại các cơ sở giáo dục.', 'Thuộc tính mô tả học chế đào tạo của chương trình đào tạo.', array['MOET39']::text[], 'hocCheDaoTao', 'String', 'Chuỗi ký tự', '50', null),
  ('BG_00854', 'Tổng số tín chỉ/đơn vị học trình', 'Là tổng số tín chỉ/ đơn vị học trình của chương trình đào tạo.', 'Thuộc tính định lượng phản ánh tổng số tín chỉ/đơn vị học trình của chương trình đào tạo. sử dụng', array['MOET39']::text[], 'tongSoTinChi', 'Integer', 'Số nguyên', '3', null),
  ('BG_00855', 'Khung năng lực ngoại ngữ của chương trình đào tạo', 'Là chuẩn đầu ra về ngoại ngữ mà người học bắt buộc phải đạt được để đủ điều kiện tốt nghiệp.', 'Thuộc tính phân loại khung năng lực ngoại ngữ của chương trình đào tạo.', array['MOET39']::text[], 'khungNangLucNgoaiNguCuaCtdt', 'Enumeration', 'Danh mục liệt kê', null, null),
  ('BG_00856', 'Chuẩn đầu ra chương trình đào tạo', 'Là hệ thống các yêu cầu về kiến thức, kỹ năng, năng lực và phẩm chất mà người học phải đạt được sau khi hoàn thành chương trình đào tạo.', 'Thuộc tính mô tả chuẩn đầu ra chương trình đào tạo.', array['MOET39']::text[], 'chuanDauRa', 'String', 'Chuỗi ký tự', '255', null),
  ('BG_00857', 'Học phí/năm khi học tập tại Việt Nam', 'Là tổng chi phí đào tạo mà người học phải nộp cho cơ sở giáo dục trong một năm học khi tham gia chương trình đào tạo được tổ chức tại Việt Nam.', 'Thuộc tính định lượng phản ánh học phí/năm khi học tập tại Việt Nam mà người học phải nộp cho cơ sở giáo dục khi theo học chương trình đào tạo.', array['MOET39']::text[], 'hocPhiTrongNuoc', 'Integer', 'Số nguyên', null, null),
  ('BG_00858', 'Học phí/năm khi học tập tại nước ngoài', 'Là tổng chi phí đào tạo mà người học phải nộp cho cơ sở giáo dục trong một năm học khi tham gia chương trình đào tạo được tổ chức tại nước ngoài.', 'Thuộc tính định lượng phản ánh học phí/năm khi học tập tại nước ngoài mà người học phải nộp cho cơ sở giáo dục khi theo học chương trình đào tạo.', array['MOET39']::text[], 'hocPhiNuocNgoai', 'Integer', 'Số nguyên', null, null),
  ('BG_00859', 'Tổng học phí toàn khóa', 'Là tổng học phí toàn khóa mà người học phải nộp cho cơ sở giáo dục.', 'Thuộc tính định lượng phản ánh tổng học phí toàn khóa mà người học phải nộp cho cơ sở giáo dục khi theo học chương trình đào tạo.', array['MOET39']::text[], 'tongHocPhi', 'Integer', 'Số nguyên', null, null),
  ('BG_00860', 'Số quyết định phê duyệt loại hình đào tạo do trường cấp bằng', 'Là số quyết định được xác định trong văn bản phê duyệt loại hình đào tạo do trường cấp bằng do cơ quan có thẩm quyền ban hành.', 'Thuộc tính ghi nhận số quyết định phê duyệt loại hình đào tạo do trường cấp bằng của cơ sở giáo dục.', array['MOET39']::text[], 'soQdPheDuyetLoaiHinhDt', 'String', 'Chuỗi ký tự', '50', null),
  ('BG_00861', 'Ngày quyết định phê duyệt loại hình đào tạo do trường cấp bằng', 'Là ngày ghi trên số quyết định phê duyệt loại hình đào tạo do trường cấp bằng do cơ quan có thẩm quyền ban hành.', 'Thuộc tính ghi nhận mốc thời gian ngày quyết định phê duyệt loại hình đào tạo do trường cấp bằng của cơ sở giáo dục.', array['MOET39']::text[], 'ngaYBanHanhQdLoaiHinhDt', 'Date', 'Ngày tháng', '10', 'CDE-TG-001'),
  ('BG_00862', 'Loại chương trình đào tạo do trường cấp bằng', 'Là phân loại chương trình đào tạo do cơ sở giáo dục tổ chức và cấp bằng.', 'Thuộc tính phân loại loại chương trình đào tạo do trường cấp bằng của cơ sở giáo dục.', array['MOET39']::text[], 'loaiCtdtDoTruongCapBang', 'Enumeration', 'Danh mục liệt kê', null, null),
  ('BG_00863', 'Tên cơ sở đào tạo nước ngoài', 'Là tên của cơ sở giáo dục được thành lập và hoạt động tại nước ngoài, tham gia vào hoạt động đào tạo, liên kết đào tạo hoặc hợp tác giáo dục với cơ sở giáo dục trong nước.', 'Thuộc tính ghi nhận tên cơ sở đào tạo nước ngoài của cơ sở giáo dục.', array['MOET39']::text[], 'tenCoSoDtNuocNgoai', 'string', 'Chuỗi ký tự', '50', null),
  ('BG_00864', 'Số quyết định phê duyệt loại hình đào tạo do nước ngoài cấp bằng', 'Là số quyết định được xác định trong văn bản phê duyệt loại hình đào tạo do nước ngoài cấp bằng do cơ quan có thẩm quyền ban hành.', 'Thuộc tính ghi nhận số quyết định phê duyệt loại hình đào sử dụng tạo do nước ngoài cấp bằng của cơ sở giáo dục.', array['MOET39']::text[], 'soQdChoPhepLoaiHinhDtNuocNgoaiCapBang', 'string', 'Chuỗi ký tự', '50', null),
  ('BG_00865', 'Ngày quyết định phê duyệt loại hình đào tạo do nước ngoài cấp bằng', 'Là ngày ghi trên số quyết định phê duyệt loại hình đào tạo do nước ngoài cấp bằng do cơ quan có thẩm quyền ban hành.', 'Thuộc tính ghi nhận số quyết định phê duyệt loại hình đào tạo do nước ngoài cấp bằng của cơ sở giáo dục.', array['MOET39']::text[], 'ngayBanHanhQdChoPhepDtNuocNgoaiCapBang', 'Date', 'Ngày tháng', '10', 'CDE-TG-001'),
  ('BG_00866', 'Số QĐ gia hạn loại hình đào tạo do nước ngoài cấp bằng lần 1', 'Là số quyết định được xác định trong văn bản phê duyệt gia hạn loại hình đào tạo do nước ngoài cấp bằng lần 1 do cơ quan có thẩm quyền ban hành.', 'Thuộc tính mô tả số QĐ gia hạn loại hình đào tạo do nước ngoài cấp bằng lần 1 của cơ sở giáo dục.', array['MOET39']::text[], 'soQdGiaHanLoaiHinhDtNuocNgoaiCapBangLan1', 'string', 'Chuỗi ký tự', '50', null),
  ('BG_00867', 'Ngày ban hành QĐ gia hạn loại hình đào tạo do nước ngoài cấp bằng lần 1', 'Là ngày ghi trên số quyết định gia hạn loại hình đào tạo do nước ngoài cấp bằng lần 1 do cơ quan có thẩm quyền ban hành.', 'Thuộc tính ghi nhận mốc thời gian ngày ban hành QĐ gia hạn loại hình đào tạo do nước ngoài cấp bằng lần 1 của cơ sở giáo dục.', array['MOET39']::text[], 'ngayBanHanhQdGiaHanDtNuocNgoaiCapBangLan1', 'Date', 'Ngày tháng', '10', 'CDE-TG-001'),
  ('BG_00868', 'Số QĐ gia hạn loại hình đào tạo do nước ngoài cấp bằng lần 2', 'Là số quyết định được xác định trong văn bản gia hạn loại hình đào tạo do nước ngoài cấp bằng lần 2 do cơ quan có thẩm quyền ban hành.', 'Thuộc tính mô tả số QĐ gia hạn loại hình đào tạo do nước ngoài cấp bằng lần 2 của cơ sở giáo dục.', array['MOET39']::text[], 'soQdGiaHanLanLoaiHinhDtNuocNgoaiCapBang2', 'String', 'Chuỗi ký tự', '50', null),
  ('BG_00869', 'Ngày ban hành QĐ gia hạn loại hình đào tạo do nước ngoài cấp bằng lần 2', 'Là ngày ghi trên số quyết định gia hạn loại hình đào tạo do nước ngoài cấp bằng lần 2 do cơ quan có thẩm quyền ban hành.', 'Thuộc tính ghi nhận mốc thời gian ngày ban hành QĐ gia hạn loại hình đào tạo do nước ngoài cấp bằng lần 2 của cơ sở giáo dục.', array['MOET39']::text[], 'ngayBanHanhQdGiaHanDtNuocNgoaiCapBangLan2', 'Date', 'Ngày tháng', '10', 'CDE-TG-001'),
  ('BG_00870', 'Tên tiếng anh chương trình đào tạo liên kết', 'Là tên gọi bằng tiếng Anh của chương trình đào tạo liên kết', 'Thuộc tính ghi nhận tên tiếng anh chương trình đào tạo liên kết của chương trình đào tạo.', array['MOET39']::text[], 'tenTiengAnhCtrLkDt', 'String', 'Chuỗi ký tự', '100', null),
  ('BG_00871', 'Tên cơ sở đào tạo nước ngoài liên kết', 'Là tên của cơ sở đào tạo được nước ngoài liên kết', 'Thuộc tính ghi nhận tên cơ sở đào tạo nước ngoài liên kết của chương trình đào tạo.', array['MOET39']::text[], 'tenCoSoDaoTao', 'String', 'Chuỗi ký tự', '100', null),
  ('BG_00872', 'Quốc gia liên kết đào tạo', 'Là tên quốc gia liên kết đào tạo.', 'Thuộc tính phân loại quốc gia liên kết đào tạo của chương trình đào tạo.', array['MOET39']::text[], 'qgLienKetDaoTao', 'Enumeration', 'Danh mục liệt kê', null, null),
  ('BG_00873', 'Đơn vị cấp bằng chương trình đào tạo liên kết', 'Là thông tin xác nhận việc cơ sở giáo dục có thẩm quyền cấp văn bằng hoặc chứng chỉ cho người học sau khi hoàn thành chương trình đào tạo liên kết', 'Thuộc tính mô tả đơn vị cấp bằng chương trình đào tạo liên kết của chương trình đào tạo.', array['MOET39']::text[], 'donViCapBang', 'String', 'Chuỗi ký tự', '100', null),
  ('BG_00874', 'Cách thức xây dựng chương trình đào tạo', 'Là phương thức xây dựng chương trình đào tạo liên kết giữa các bên', 'Thuộc tính mô tả cách thức xây dựng chương trình đào tạo liên kết giữa các bên.', array['MOET39']::text[], 'cachThucXayDung', 'String', 'Chuỗi ký tự', '255', null),
  ('BG_00875', 'Loại chương trình liên kết đào tạo', 'Là phân loại hình thức tổ chức chương trình đào tạo liên kết dựa trên cách thức hợp tác giữa các bên', 'Thuộc tính mô tả loại chương trình liên kết đào tạo của chương trình đào tạo.', array['MOET39']::text[], 'loaiCtLkDt', 'String', 'Chuỗi ký tự', '100', null),
  ('BG_00876', 'Trình độ ngoại ngữ đầu vào chương trình đào tạo liên kết', 'Là mức độ năng lực ngoại ngữ tối thiểu mà người học phải đạt được để đủ điều kiện tham gia chương trình đào tạo liên kết.', 'Thuộc tính phân loại trình độ ngoại ngữ đầu vào chương trình đào tạo liên kết.', array['MOET39']::text[], 'trinhDoNgoaiNguDauVaoCtLkDt', 'Enumeration', 'Danh mục liệt kê', null, null),
  ('BG_00877', 'Loại chứng chỉ được chấp thuận cho chương trình đào tạo liên kết', 'Là danh sách các loại chứng chỉ được cơ sở đào tạo hoặc đối tác liên kết công nhận để đáp ứng yêu cầu đầu vào hoặc điều kiện tham gia chương trình đào tạo liên kết.', 'Thuộc tính mô tả loại chứng chỉ được chấp thuận cho chương trình đào tạo liên kết', array['MOET39']::text[], 'loaiChungChiDuocChapThuan', 'String', 'Chuỗi ký tự', '500', null),
  ('BG_00878', 'Trạng thái của chương trình liên kết đào tạo', 'Là tình trạng hoạt động hiện tại của chương trình đào tạo liên kết.', 'Thuộc tính phân loại trạng thái của chương trình liên kết đào tạo.', array['MOET39']::text[], 'trangThaiCuaCtLkDt', 'Enumeration', 'Danh mục liệt kê', null, null),
  ('BG_00879', 'Đơn vị thực hiện chương trình liên kết đào tạo', 'Là tổ chức hoặc cơ sở đào tạo trực tiếp triển khai chương trình đào tạo liên kết.', 'Thuộc tính mô tả đơn vị trực tiếp triển khai chương trình liên kết đào tạo.', array['MOET39']::text[], 'donViThucHien', 'String', 'Chuỗi ký tự', '100', null),
  ('BG_00880', 'Chỉ tiêu tuyển sinh hằng năm của chương trình liên kết đào tạo', 'Là số lượng người học dự kiến được tuyển vào chương trình đào tạo liên kết trong một năm học.', 'Thuộc tính mô tả chỉ tiêu tuyển sinh hằng năm của chương trình liên kết đào tạo.', array['MOET39']::text[], 'chiTieuHangNam', 'String', 'Chuỗi ký tự', '100', null),
  ('BG_00881', 'Website giới thiệu về chương trình liên kết đào tạo', 'Là website cung cấp nội dung chính thức về chương trình đào tạo liên kết.', 'Thuộc tính mô tả website giới thiệu về chương trình liên kết đào tạo.', array['MOET39']::text[], 'websiteGioiThieu', 'String', 'Chuỗi ký tự', '50', null),
  ('BG_00882', 'Học phí năm học của người học chương trình đào tạo liên kết.', 'Là tổng chi phí đào tạo mà người học phải nộp trong một năm học khi tham gia chương trình đào tạo liên kết.', 'Thuộc tính định lượng phản ánh học phí năm học của người học phải nộp nếu tham gia chương trình đào tạo liên kết.', array['MOET39']::text[], 'hocPhiNamHoc', 'Integer', 'Số nguyên', '20', null),
  ('BG_00883', 'Học phí cả khóa học cho năm tuyển sinh báo cáo', 'Là tổng chi phí đào tạo mà người học phải nộp cho toàn bộ chương trình đào tạo liên kết đối với một khóa tuyển sinh cụ thể.', 'Thuộc tính định lượng phản ánh học phí cả khóa học mà người học phải nộp cho năm tuyển sinh đang báo cáo.', array['MOET39']::text[], 'hocPhiKhoaHoc', 'Integer', 'Số nguyên', '20', null),
  ('BG_00884', 'Số quyết định gia hạn chương trình đào tạo', 'Là số quyết định được xác định trong văn bản gia hạn chương trình đào tạo do cơ quan có thẩm quyền ban hành.', 'Thuộc tính ghi nhận số quyết định gia hạn chương trình đào tạo.', array['MOET39']::text[], 'soQdGiaHanCtdt', 'String', 'Chuỗi ký tự', '50', null),
  ('BG_00885', 'Ngày quyết định gia hạn chương trình đào tạo', 'Là ngày ghi trên số quyết định gia hạn chương trình đào tạo do cơ quan có thẩm quyền ban hành.', 'Thuộc tính ghi nhận mốc thời gian ngày quyết định gia hạn chương trình đào tạo.', array['MOET39']::text[], 'ngayQdGiaHanCtdt', 'Date', 'Ngày tháng', '10', 'CDE-TG-001'),
  ('BG_00886', 'Lần gia hạn chương trình đào tạo', 'Là số lần gia hạn được chấp thuận bởi cơ quan có thẩm quyền của chương trình đào tạo', 'Thuộc tính định lượng phản ánh lần gia hạn chương trình đào tạo.', array['MOET39']::text[], 'lanGiaHanCtdt', 'Integer', 'Số nguyên', null, null),
  ('BG_00887', 'Ngôn ngữ giảng dạy của chương trình đào tạo', 'Là ngôn ngữ chính được sử dụng trong hoạt động giảng dạy, học tập và đánh giá trong chương trình đào tạo.', 'Thuộc tính phân loại ngôn ngữ giảng dạy của chương trình đào tạo.', array['MOET39']::text[], 'ngonNguGiangDayCuaCtdt', 'Enumeration', 'Danh mục liệt kê', null, null),
  ('BG_00888', 'Thông tư quy định đánh giá học sinh các cấp', 'Là văn bản do Bộ Giáo dục và Đào tạo ban hành ngày quy định về đánh giá học sinh tiểu học, trung học cơ sở, trung học phổ thông và giáo dục thường xuyên.', 'Thuộc tính mô tả thông tư quy định đánh giá học sinh các cấp của người học.', array['MOET39']::text[], 'thongTu', 'String', 'Chuỗi ký tự', '10', null),
  ('BG_00889', 'Tổ chức kiểm định chương trình đào tạo', 'Là các đơn vị độc lập, được Bộ Giáo dục và Đào tạo cấp phép thực hiện đánh giá và công nhận chất lượng chương trình đào tạo theo tiêu chuẩn do cơ quan có thẩm quyền ban hành.', 'Thuộc tính thông tin tổ chức kiểm định thực hiện đánh giá chất lượng chương trình đào tạo.', array['MOET41']::text[], 'toChucKdCtdt', 'String', 'Chuỗi ký tự', '255', null),
  ('BG_00890', 'Kết quả kiểm định chương trình đào tạo', 'Là kết luận của tổ chức kiểm định về mức độ đạt tiêu chuẩn chất lượng giáo dục của chương trình đào tạo', 'Thuộc tính mô tả kết quả kiểm định chất lượng chương trình đào tạo.', array['MOET41']::text[], 'ketQuaKdCtdt', 'String', 'Chuỗi ký tự', '500', null),
  ('BG_00891', 'Ngày cấp chứng nhận kiểm định chất lượng chương trình đào tạo', 'Là thời điểm tổ chức kiểm định ban hành văn bản chứng nhận chương trình đào tạo đạt tiêu chuẩn chất lượng giáo dục.', 'Thuộc tính ghi nhận mốc thời gian ngày cấp chứng nhận kiểm định chất lượng của chương trình đào tạo.', array['MOET41']::text[], 'ngayCapChungNhanKdCtdt', 'Date', 'Ngày tháng', '10', 'CDE-TG-001'),
  ('BG_00892', 'Thời hạn kiểm định chất lượng chương trình đào tạo', 'Là khoảng thời gian có hiệu lực của giấy chứng nhận kiểm định chất lượng giáo dục.', 'Thuộc tính ghi nhận mốc thời gian thời hạn kiểm định chất lượng có hiệu lực của chương trình đào tạo.', array['MOET41']::text[], 'thoiHanKdCtdt', 'String', 'Chuỗi ký tự', '255', null);
